import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

out = []
for path, methods in spec.get('paths', {}).items():
    for method, op in methods.items():
        if method.startswith('x-'):
            continue
        rec = {
            "method": method.upper(),
            "path": path,
            "operationId": op.get("operationId"),
            "security": op.get("security"),
            "parameters": op.get("parameters"),
        }
        if "requestBody" in op:
            rec["request"] = op["requestBody"]["content"]["application/json"]["schema"]
        rec["responses"] = {}
        for code, resp in op.get("responses", {}).items():
            content = resp.get("content", {})
            if "application/json" in content:
                rec["responses"][code] = content["application/json"]["schema"]
            else:
                rec["responses"][code] = resp.get("description", "")
        out.append(rec)

with open('/tmp/api_ops.json', 'w') as f:
    json.dump(out, f, indent=2)
print(f"Wrote {len(out)} operations")

# Also print compact request/success for each
for rec in out:
    print("=" * 70)
    print(f"{rec['method']} {rec['path']}  [{rec['operationId']}]")
    print(f"  security: {rec['security']}")
    if rec.get("parameters"):
        print(f"  params: {json.dumps(rec['parameters'])}")
    if rec.get("request"):
        req = rec["request"]
        props = req.get("properties", {})
        reqd = req.get("required", [])
        print(f"  request required: {reqd}")
        for k,v in props.items():
            extra = ""
            if "$ref" in v:
                extra = v["$ref"]
            elif v.get("type") == "array":
                extra = f"array[{v.get('items',{})}]"
            elif v.get("enum"):
                extra = f"enum={v['enum']}"
            elif v.get("format"):
                extra = v["format"]
            else:
                extra = v.get("type","")
            star = "*" if k in reqd else " "
            print(f"    {star} {k}: {extra}")
    # success responses
    for code in rec["responses"]:
        if code.startswith("2"):
            schema = rec["responses"][code]
            print(f"  {code} success:")
            # unwrap data wrapper
            props = schema.get("properties", {})
            if "data" in props:
                data = props["data"]
                if "$ref" in data:
                    print(f"    data: {data['$ref']}")
                elif data.get("type") == "object":
                    dprops = data.get("properties", {})
                    dreq = data.get("required", [])
                    for k,v in dprops.items():
                        extra = v.get("$ref") or v.get("type") or v.get("enum") or ""
                        if isinstance(v.get("items"), dict):
                            extra = f"array[{v['items'].get('$ref', v['items'].get('type',''))}]"
                        star = "*" if k in dreq else " "
                        print(f"      {star} {k}: {extra}")
            else:
                print(f"    {json.dumps(schema)[:400]}")
        elif code in ("400","401","403","404","409","422"):
            schema = rec["responses"][code]
            codes = schema.get("properties", {}).get("code", {}).get("enum", [])
            print(f"  {code} codes: {codes}")
