import (
	"encoding/json"
	"time"

	"github.com/jackc/pgx/v5/pgtype"
)

const (
	RoleAdministrator          = "administrator"
	RoleDispatcher             = "dispatcher"
	RoleRequester              = "requester"
	RoleCollectionProfessional = "collection_professional"
	RoleDeliveryPartner        = "delivery_partner"
	RoleNodeHandler            = "node_handler"
	RoleLaboratoryTeam         = "laboratory_team"
)

var allRoles = []string{
	RoleAdministrator, RoleDispatcher, RoleRequester,
	RoleCollectionProfessional, RoleDeliveryPartner,
	RoleNodeHandler, RoleLaboratoryTeam,
}

func validRole(r string) bool {
	for _, x := range allRoles {
		if x == r {
			return true
		}
	}
	return false
}

const (
	FnCollection  = "collection_point"
	FnTransfer    = "transfer_point"
	FnHub         = "hub"
	FnLaboratory  = "laboratory"
)

const staleAfter = 5 * time.Minute
const offerTTL = 2 * time.Minute
const declinePenalty = 15 * time.Minute
const offerScanInterval = 15 * time.Second

type APIError struct {
	Error string `json:"error"`
	Code  string `json:"code"`
}

type Coord struct {
	Latitude  float64 `json:"latitude"`
	Longitude float64 `json:"longitude"`
}

type Certification struct {
	Code      string     `json:"code"`
	Active    bool       `json:"active"`
	ExpiresAt *time.Time `json:"expiresAt,omitempty"`
}

type LocationFunctions struct {
	CollectionPoint bool `json:"collection_point"`
	TransferPoint   bool `json:"transfer_point"`
	Hub             bool `json:"hub"`
	Laboratory      bool `json:"laboratory"`
}

type Capacity struct {
	CapacityUnits        int `json:"capacityUnits"`
	ReservedUnits        int `json:"reservedUnits"`
	AvailableUnits       int `json:"availableUnits"`
	CooledCapacityUnits  int `json:"cooledCapacityUnits"`
	CooledReservedUnits  int `json:"cooledReservedUnits"`
	CooledAvailableUnits int `json:"cooledAvailableUnits"`
}

func (c Capacity) fillAvail() Capacity {
	c.AvailableUnits = c.CapacityUnits - c.ReservedUnits
	c.CooledAvailableUnits = c.CooledCapacityUnits - c.CooledReservedUnits
	if c.AvailableUnits < 0 {
		c.AvailableUnits = 0
	}
	if c.CooledAvailableUnits < 0 {
		c.CooledAvailableUnits = 0
	}
	return c
}

type TimelineEntry struct {
	EventID    int64                  `json:"eventId"`
	Action     string                 `json:"action"`
	ActorID    string                 `json:"actorId"`
	Role       string                 `json:"role"`
	EntityType string                 `json:"entityType"`
	EntityID   string                 `json:"entityId"`
	Success    bool                   `json:"success"`
	OccurredAt time.Time              `json:"occurredAt"`
	Details    map[string]interface{} `json:"details"`
}

func nullUUID(s string) pgtype.UUID {
	var u pgtype.UUID
	if s == "" {
		u.Valid = false
		return u
	}
	if err := u.Scan(s); err != nil {
		u.Valid = false
	}
	return u
}

func uuidStr(u pgtype.UUID) string {
	if !u.Valid {
		return ""
	}
	b, _ := u.Value()
	if s, ok := b.(string); ok {
		return s
	}
	if bts, ok := b.([16]byte); ok {
		return formatUUID(bts)
	}
	return ""
}

func formatUUID(b [16]byte) string {
	const hex = "0123456789abcdef"
	buf := make([]byte, 36)
	j := 0
	for i, v := range b {
		if i == 4 || i == 6 || i == 8 || i == 10 {
			buf[j] = '-'
			j++
		}
		buf[j] = hex[v>>4]
		buf[j+1] = hex[v&0x0f]
		j += 2
	}
	return string(buf)
}

func ptrTime(t time.Time) *time.Time {
	if t.IsZero() {
		return nil
	}
	return &t
}

func iso(t time.Time) string {
	if t.IsZero() {
		return ""
	}
	return t.UTC().Format(time.RFC3339Nano)
}

func asJSON(v interface{}) []byte {
	b, _ := json.Marshal(v)
	return b
}

func isStale(t *time.Time, now time.Time) bool {
	if t == nil || t.IsZero() {
		return true
	}
	return now.Sub(*t) > staleAfter
}

func haversineKm(lat1, lng1, lat2, lng2 float64) float64 {
	const R = 6371.0
	p1 := lat1 * 3.141592653589793 / 180
	p2 := lat2 * 3.141592653589793 / 180
	dphi := (lat2 - lat1) * 3.141592653589793 / 180
	dl := (lng2 - lng1) * 3.141592653589793 / 180
	a := sin(dphi/2)*sin(dphi/2) + cos(p1)*cos(p2)*sin(dl/2)*sin(dl/2)
	c := 2 * atan2(sqrt(a), sqrt(1-a))
	return R * c
}

func sin(x float64) float64 {
	// use math
	return mathSin(x)
}

func cos(x float64) float64 { return mathCos(x) }
func sqrt(x float64) float64 { return mathSqrt(x) }
func atan2(y, x float64) float64 { return mathAtan2(y, x) }
"}

