{"path":"/workspace/backend/store.go","command":"create","file_text":"package main

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"log"
	"os"
	"sync"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo"
	"go.mongodb.org/mongo-driver/v2/mongo/options"
	"golang.org/x/crypto/bcrypt"
)

type Store struct {
	pg    *pgxpool.Pool
	mongo *mongo.Client
	mdb   *mongo.Database
	audit *mongo.Collection

	mu           sync.RWMutex
	eventSubs    map[chan RealtimeEvent]struct{}
	svcComputing bool
}

func NewStore(ctx context.Context, pgURL, mongoURL string) (*Store, error) {
	pg, err := pgxpool.New(ctx, pgURL)
	if err != nil {
		return nil, fmt.Errorf("pg connect: %w", err)
	}
	if err := pg.Ping(ctx); err != nil {
		return nil, fmt.Errorf("pg ping: %w", err)
	}

	mc, err := mongo.Connect(options.Client().ApplyURI(mongoURL))
	if err != nil {
		return nil, fmt.Errorf("mongo connect: %w", err)
	}
	if err := mc.Ping(ctx, nil); err != nil {
		return nil, fmt.Errorf("mongo ping: %w", err)
	}
	dbName := "arena"
	if v := os.Getenv("MONGO_DB"); v != "" {
		dbName = v
	}
	mdb := mc.Database(dbName)
	s := &Store{
		pg:        pg,
		mongo:     mc,
		mdb:       mdb,
		audit:     mdb.Collection("audit_logs"),
		eventSubs: map[chan RealtimeEvent]struct{}{},
	}
	return s, nil
}

func (s *Store) Close() {
	s.pg.Close()
	_ = s.mongo.Disconnect(context.Background())
}

func (s *Store) Ping(ctx context.Context) error {
	if err := s.pg.Ping(ctx); err != nil {
		return err
	}
	return s.mongo.Ping(ctx, nil)
}

func (s *Store) Reset(ctx context.Context) error {
	// Drop and recreate application tables
	drop := `
DROP TABLE IF EXISTS
  serviceability_regions, idempotency, timeline, realtime_events,
  exceptions, disruptions, worker_location_updates, checkpoints,
  handoffs, capacity_reservations, assignments, journey_stops,
  journey_samples, journeys, samples, collection_requests,
  lab_acceptances, connections, locations, sample_types,
  sessions, certifications, user_qualifications, user_roles, users,
  network_meta
CASCADE;
`
	if _, err := s.pg.Exec(ctx, drop); err != nil {
		return fmt.Errorf("drop: %w", err)
	}
	if _, err := s.pg.Exec(ctx, schemaSQL); err != nil {
		return fmt.Errorf("schema: %w", err)
	}
	if err := s.ensureMongo(ctx); err != nil {
		return err
	}
	if err := s.seedSampleTypes(ctx); err != nil {
		return err
	}
	return nil
}

func (s *Store) EnsureSchema(ctx context.Context) error {
	if _, err := s.pg.Exec(ctx, schemaSQL); err != nil {
		return fmt.Errorf("schema: %w", err)
	}
	if err := s.ensureMongo(ctx); err != nil {
		return err
	}
	if err := s.seedSampleTypes(ctx); err != nil {
		return err
	}
	return nil
}

func (s *Store) ensureMongo(ctx context.Context) error {
	// Materialize collection and indexes immediately.
	_ = s.mdb.CreateCollection(ctx, "audit_logs")
	idxs := []mongo.IndexModel{
		{Keys: bson.D{{Key: "auditId", Value: 1}}, Options: options.Index().SetUnique(true)},
		{Keys: bson.D{{Key: "actorId", Value: 1}}},
		{Keys: bson.D{{Key: "entityType", Value: 1}, {Key: "entityId", Value: 1}}},
		{Keys: bson.D{{Key: "action", Value: 1}}},
		{Keys: bson.D{{Key: "role", Value: 1}}},
		{Keys: bson.D{{Key: "success", Value: 1}}},
		{Keys: bson.D{{Key: "occurredAt", Value: -1}}},
		{Keys: bson.D{{Key: "searchText", Value: "text"}}},
	}
	_, err := s.audit.Indexes().CreateMany(ctx, idxs)
	return err
}

func (s *Store) seedSampleTypes(ctx context.Context) error {
	defaults := []struct {
		id, name, qual, container string
		tmin, tmax                float64
		cooled, batch             bool
	}{
		{"11111111-1111-1111-1111-111111111111", "Amber", "Amber", "standard", 2, 25, false, true},
		{"22222222-2222-2222-2222-222222222222", "Indigo", "Indigo", "standard", 2, 25, false, true},
		{"33333333-3333-3333-3333-333333333333", "Frost", "Frost", "cooled", 2, 8, true, true},
		{"44444444-4444-4444-4444-444444444444", "Pulse", "Pulse", "standard", 2, 25, false, false},
	}
	// Amber incompatible with Indigo and vice versa
	amberID := "11111111-1111-1111-1111-111111111111"
	indigoID := "22222222-2222-2222-2222-222222222222"
	for _, d := range defaults {
		incompat := []string{}
		if d.name == "Amber" {
			incompat = []string{indigoID}
		}
		if d.name == "Indigo" {
			incompat = []string{amberID}
		}
		_, err := s.pg.Exec(ctx, `
INSERT INTO sample_types (id, name, qualified_collector_required, required_qualification,
  container_type, temperature_min_c, temperature_max_c, incompatible_sample_types,
  requires_cooled_route, batching_allowed)
VALUES ($1,$2,TRUE,$3,$4,$5,$6,$7,$8,$9)
ON CONFLICT (id) DO NOTHING
`, d.id, d.name, d.qual, d.container, d.tmin, d.tmax, incompat, d.cooled, d.batch)
		if err != nil {
			return fmt.Errorf("seed sample type %s: %w", d.name, err)
		}
	}
	return nil
}

func (s *Store) EnsureAdmin(ctx context.Context) error {
	user := os.Getenv("ADMIN_USERNAME")
	pass := os.Getenv("ADMIN_PASSWORD")
	if user == "" || pass == "" {
		return nil
	}
	var n int
	if err := s.pg.QueryRow(ctx, `SELECT COUNT(*) FROM users`).Scan(&n); err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
	hash, err := bcrypt.GenerateFromPassword([]byte(pass), bcrypt.DefaultCost)
	if err != nil {
		return err
	}
	id := newUUID()
	_, err = s.pg.Exec(ctx, `
INSERT INTO users (id, username, password_hash, full_name, active)
VALUES ($1,$2,$3,'Administrator', TRUE)`, id, user, string(hash))
	if err != nil {
		return err
	}
	_, err = s.pg.Exec(ctx, `INSERT INTO user_roles (user_id, role) VALUES ($1,$2)`, id, RoleAdministrator)
	if err != nil {
		return err
	}
	log.Printf("created initial administrator %s", user)
	return nil
}

func newUUID() string {
	b := make([]byte, 16)
	_, _ = rand.Read(b)
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
}

func newToken() string {
	b := make([]byte, 32)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

func hashPassword(p string) (string, error) {
	b, err := bcrypt.GenerateFromPassword([]byte(p), bcrypt.DefaultCost)
	return string(b), err
}

func checkPassword(hash, p string) bool {
	return bcrypt.CompareHashAndPassword([]byte(hash), []byte(p)) == nil
}

type Tx = pgx.Tx

func (s *Store) Begin(ctx context.Context) (Tx, error) {
	return s.pg.Begin(ctx)
}
"}

{"path":"/workspace/backend/http.go","command":"create","file_text":"package main

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"log"
	"net/http"
	"strings"
	"time"
)

type ctxKey int

const (
	ctxUser ctxKey = iota
	ctxSession
)

type SessionUser struct {
	UserID              string
	Username            string
	FullName            string
	Roles               []string
	ActiveRole          string
	AssignedLocationID  string
	Available           bool
	CapacityUnits       int
	Active              bool
	Qualifications      []string
	Certifications      []Certification
}

func (u SessionUser) hasRole(r string) bool {
	for _, x := range u.Roles {
		if x == r {
			return true
		}
	}
	return false
}

func (u SessionUser) isAdmin() bool {
	return u.ActiveRole == RoleAdministrator
}

func (u SessionUser) isDispatcher() bool {
	return u.ActiveRole == RoleDispatcher || u.ActiveRole == RoleAdministrator
}

func writeJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeData(w http.ResponseWriter, status int, data interface{}) {
	writeJSON(w, status, map[string]interface{}{"data": data})
}

func writeErr(w http.ResponseWriter, status int, code, msg string) {
	if msg == "" {
		msg = code
	}
	writeJSON(w, status, APIError{Error: msg, Code: code})
}

func readJSON(r *http.Request, dst interface{}) error {
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		return err
	}
	return nil
}

func parseTime(s string) (time.Time, error) {
	if s == "" {
		return time.Time{}, errors.New("empty time")
	}
	if t, err := time.Parse(time.RFC3339Nano, s); err == nil {
		return t, nil
	}
	if t, err := time.Parse(time.RFC3339, s); err == nil {
		return t, nil
	}
	return time.Time{}, errors.New("invalid time")
}

func (app *App) requireAuth(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		tok := bearerToken(r)
		if tok == "" {
			writeErr(w, 401, "unauthorized", "unauthorized")
			return
		}
		u, err := app.loadSession(r.Context(), tok)
		if err != nil || u == nil {
			writeErr(w, 401, "unauthorized", "unauthorized")
			return
		}
		ctx := context.WithValue(r.Context(), ctxUser, u)
		next(w, r.WithContext(ctx))
	}
}

func bearerToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if strings.HasPrefix(strings.ToLower(h), "bearer ") {
		return strings.TrimSpace(h[7:])
	}
	return ""
}

func currentUser(r *http.Request) *SessionUser {
	v, _ := r.Context().Value(ctxUser).(*SessionUser)
	return v
}

func (app *App) requireRoleSelected(next http.HandlerFunc) http.HandlerFunc {
	return app.requireAuth(func(w http.ResponseWriter, r *http.Request) {
		u := currentUser(r)
		if u.ActiveRole == "" {
			writeErr(w, 409, "role_not_selected", "role not selected")
			return
		}
		next(w, r)
	})
}

func (app *App) requireRoles(roles ...string) func(http.HandlerFunc) http.HandlerFunc {
	return func(next http.HandlerFunc) http.HandlerFunc {
		return app.requireRoleSelected(func(w http.ResponseWriter, r *http.Request) {
			u := currentUser(r)
			ok := false
			for _, role := range roles {
				if u.ActiveRole == role {
					ok = true
					break
				}
			}
			if !ok && u.ActiveRole == RoleAdministrator {
				// admin can do dispatcher things; other admin-only checks are explicit
				for _, role := range roles {
					if role == RoleDispatcher || role == RoleAdministrator {
						ok = true
						break
					}
				}
			}
			if !ok {
				writeErr(w, 403, "forbidden", "forbidden")
				return
			}
			next(w, r)
		})
	}
}

func methodGuard(allowed string, h http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != allowed {
			writeErr(w, 405, "method_not_allowed", "method not allowed")
			return
		}
		h(w, r)
	}
}

func (app *App) loadSession(ctx context.Context, token string) (*SessionUser, error) {
	var userID, activeRole string
	var expires time.Time
	err := app.store.pg.QueryRow(ctx, `
SELECT user_id, active_role, expires_at FROM sessions WHERE token=$1`, token).
		Scan(&userID, &activeRole, &expires)
	if err != nil {
		return nil, err
	}
	if time.Now().After(expires) {
		return nil, errors.New("expired")
	}
	return app.loadUser(ctx, userID, activeRole)
}

func (app *App) loadUser(ctx context.Context, userID, activeRole string) (*SessionUser, error) {
	u := &SessionUser{UserID: userID, ActiveRole: activeRole}
	var assigned *string
	err := app.store.pg.QueryRow(ctx, `
SELECT username, full_name, active, COALESCE(assigned_location_id::text,''), available, capacity_units
FROM users WHERE id=$1`, userID).Scan(&u.Username, &u.FullName, &u.Active, &assigned, &u.Available, &u.CapacityUnits)
	if err != nil {
		return nil, err
	}
	if assigned != nil {
		u.AssignedLocationID = *assigned
	}
	rows, err := app.store.pg.Query(ctx, `SELECT role FROM user_roles WHERE user_id=$1`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var role string
		if err := rows.Scan(&role); err != nil {
			return nil, err
		}
		u.Roles = append(u.Roles, role)
	}
	qrows, err := app.store.pg.Query(ctx, `SELECT qualification FROM user_qualifications WHERE user_id=$1`, userID)
	if err != nil {
		return nil, err
	}
	defer qrows.Close()
	for qrows.Next() {
		var q string
		if err := qrows.Scan(&q); err != nil {
			return nil, err
		}
		u.Qualifications = append(u.Qualifications, q)
	}
	crows, err := app.store.pg.Query(ctx, `SELECT code, active, expires_at FROM certifications WHERE user_id=$1`, userID)
	if err != nil {
		return nil, err
	}
	defer crows.Close()
	for crows.Next() {
		var c Certification
		var exp *time.Time
		if err := crows.Scan(&c.Code, &c.Active, &exp); err != nil {
			return nil, err
		}
		c.ExpiresAt = exp
		u.Certifications = append(u.Certifications, c)
	}
	if u.Roles == nil {
		u.Roles = []string{}
	}
	if u.Qualifications == nil {
		u.Qualifications = []string{}
	}
	if u.Certifications == nil {
		u.Certifications = []Certification{}
	}
	return u, nil
}

func decodeStrict(r *http.Request, dst interface{}) error {
	b, err := io.ReadAll(r.Body)
	if err != nil {
		return err
	}
	if len(b) == 0 {
		// empty body is ok for endpoints that accept empty objects
		return json.Unmarshal([]byte("{}"), dst)
	}
	if err := json.Unmarshal(b, dst); err != nil {
		return err
	}
	return nil
}

func (app *App) withIdempotency(w http.ResponseWriter, r *http.Request, key string, handler func() (int, interface{}, error)) {
	u := currentUser(r)
	if key == "" {
		writeErr(w, 400, "idempotency_required", "idempotency key required")
		return
	}
	ctx := r.Context()
	var existingStatus int
	var existing []byte
	var existingUser string
	err := app.store.pg.QueryRow(ctx, `
SELECT user_id::text, status_code, response FROM idempotency WHERE key=$1`, key).
		Scan(&existingUser, &existingStatus, &existing)
	if err == nil {
		if existingUser != u.UserID {
			writeErr(w, 409, "idempotency_conflict", "idempotency conflict")
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(existingStatus)
		_, _ = w.Write(existing)
		return
	}
	status, payload, herr := handler()
	if herr != nil {
		// handler already wrote? no, we write
		if ae, ok := herr.(*httpErr); ok {
			writeErr(w, ae.status, ae.code, ae.msg)
			return
		}
		log.Printf("handler error: %v", herr)
		writeErr(w, 500, "internal_error", "internal error")
		return
	}
	body, _ := json.Marshal(map[string]interface{}{"data": payload})
	_, _ = app.store.pg.Exec(ctx, `
INSERT INTO idempotency (key, user_id, request_hash, status_code, response)
VALUES ($1,$2,'', $3, $4)
ON CONFLICT (key) DO NOTHING`, key, u.UserID, status, body)
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_, _ = w.Write(body)
}

type httpErr struct {
	status int
	code   string
	msg    string
}

func (e *httpErr) Error() string { return e.code }

func herr(status int, code, msg string) *httpErr {
	if msg == "" {
		msg = code
	}
	return &httpErr{status: status, code: code, msg: msg}
}

func (app *App) handleErr(w http.ResponseWriter, err error) {
	if err == nil {
		return
	}
	if ae, ok := err.(*httpErr); ok {
		writeErr(w, ae.status, ae.code, ae.msg)
		return
	}
	log.Printf("internal: %v", err)
	writeErr(w, 500, "internal_error", "internal error")
}

func cors(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type, Sec-WebSocket-Protocol")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, PATCH, DELETE, OPTIONS")
		if r.Method == http.MethodOptions {
			w.WriteHeader(204)
			return
		}
		next.ServeHTTP(w, r)
	})
}
"}

{"path":"/workspace/backend/audit.go","command":"create","file_text":"package main

import (
	"context"
	"log"
	"strings"
	"time"

	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo/options"
)

func (app *App) audit(ctx context.Context, actorID, role, action, entityType, entityId string, success bool, details map[string]interface{}) {
	if details == nil {
		details = map[string]interface{}{}
	}
	now := time.Now().UTC()
	id := newUUID()
	searchParts := []string{action, entityType, entityId, actorID, role}
	for k, v := range details {
		searchParts = append(searchParts, k, stringify(v))
	}
	doc := bson.M{
		"auditId":    id,
		"audit_id":   id,
		"actorId":    actorID,
		"actor_id":   actorID,
		"role":       role,
		"actorRole":  role,
		"action":     action,
		"entityType": entityType,
		"entity_type": entityType,
		"entityId":   entityId,
		"entity_id":  entityId,
		"success":    success,
		"occurredAt": now,
		"occurred_at": now,
		"details":    details,
		"searchText": strings.Join(searchParts, " "),
	}
	if _, err := app.store.audit.InsertOne(ctx, doc); err != nil {
		log.Printf("audit insert: %v", err)
	}
	_, err := app.store.pg.Exec(ctx, `
INSERT INTO timeline (action, actor_id, role, entity_type, entity_id, success, occurred_at, details)
VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
		action, actorID, role, entityType, entityId, success, now, asJSON(details))
	if err != nil {
		log.Printf("timeline insert: %v", err)
	}
}

func stringify(v interface{}) string {
	switch t := v.(type) {
	case string:
		return t
	default:
		return string(asJSON(v))
	}
}

func (app *App) emit(typ, entityType, entityId string, payload map[string]interface{}) {
	if payload == nil {
		payload = map[string]interface{}{}
	}
	var id int64
	err := app.store.pg.QueryRow(context.Background(), `
INSERT INTO realtime_events (type, entity_type, entity_id, payload)
VALUES ($1,$2,$3,$4) RETURNING id`, typ, entityType, entityId, asJSON(payload)).Scan(&id)
	if err != nil {
		log.Printf("emit: %v", err)
		return
	}
	ev := RealtimeEvent{
		ID:         id,
		Type:       typ,
		EntityType: entityType,
		EntityID:   entityId,
		Payload:    payload,
		CreatedAt:  time.Now().UTC(),
	}
	app.store.mu.RLock()
	defer app.store.mu.RUnlock()
	for ch := range app.store.eventSubs {
		select {
		case ch <- ev:
		default:
		}
	}
}

type RealtimeEvent struct {
	ID         int64                  `json:"id"`
	Type       string                 `json:"type"`
	EntityType string                 `json:"entityType"`
	EntityID   string                 `json:"entityId"`
	Payload    map[string]interface{} `json:"payload"`
	CreatedAt  time.Time              `json:"createdAt"`
}

func (app *App) subscribe() chan RealtimeEvent {
	ch := make(chan RealtimeEvent, 32)
	app.store.mu.Lock()
	app.store.eventSubs[ch] = struct{}{}
	app.store.mu.Unlock()
	return ch
}

func (app *App) unsubscribe(ch chan RealtimeEvent) {
	app.store.mu.Lock()
	delete(app.store.eventSubs, ch)
	app.store.mu.Unlock()
	close(ch)
}

func (app *App) loadTimeline(ctx context.Context, entityType, entityId string) []TimelineEntry {
	rows, err := app.store.pg.Query(ctx, `
SELECT event_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
FROM timeline WHERE entity_type=$1 AND entity_id=$2 ORDER BY event_id ASC`, entityType, entityId)
	if err != nil {
		return []TimelineEntry{}
	}
	defer rows.Close()
	out := []TimelineEntry{}
	for rows.Next() {
		var e TimelineEntry
		var details []byte
		if err := rows.Scan(&e.EventID, &e.Action, &e.ActorID, &e.Role, &e.EntityType, &e.EntityID, &e.Success, &e.OccurredAt, &details); err != nil {
			continue
		}
		e.Details = map[string]interface{}{}
		_ = jsonUnmarshal(details, &e.Details)
		if e.Details == nil {
			e.Details = map[string]interface{}{}
		}
		out = append(out, e)
	}
	return out
}

func (app *App) loadTimelineAny(ctx context.Context, entityIds ...string) []TimelineEntry {
	if len(entityIds) == 0 {
		return []TimelineEntry{}
	}
	rows, err := app.store.pg.Query(ctx, `
SELECT event_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
FROM timeline WHERE entity_id = ANY($1) ORDER BY event_id ASC`, entityIds)
	if err != nil {
		return []TimelineEntry{}
	}
	defer rows.Close()
	out := []TimelineEntry{}
	for rows.Next() {
		var e TimelineEntry
		var details []byte
		if err := rows.Scan(&e.EventID, &e.Action, &e.ActorID, &e.Role, &e.EntityType, &e.EntityID, &e.Success, &e.OccurredAt, &details); err != nil {
			continue
		}
		e.Details = map[string]interface{}{}
		_ = jsonUnmarshal(details, &e.Details)
		if e.Details == nil {
			e.Details = map[string]interface{}{}
		}
		out = append(out, e)
	}
	return out
}

func jsonUnmarshal(b []byte, v interface{}) error {
	if len(b) == 0 {
		return nil
	}
	return json.Unmarshal(b, v)
}

func (app *App) searchAudit(ctx context.Context, q queryAudit) (map[string]interface{}, error) {
	filter := bson.M{}
	ands := []bson.M{}
	if q.Query != "" {
		ands = append(ands, bson.M{"$text": bson.M{"$search": q.Query}})
	}
	if q.ActorID != "" {
		ands = append(ands, bson.M{"actorId": q.ActorID})
	}
	if q.EntityType != "" {
		ands = append(ands, bson.M{"entityType": q.EntityType})
	}
	if q.EntityID != "" {
		ands = append(ands, bson.M{"entityId": q.EntityID})
	}
	if q.Action != "" {
		ands = append(ands, bson.M{"action": q.Action})
	}
	if q.Role != "" {
		ands = append(ands, bson.M{"role": q.Role})
	}
	if q.Success != nil {
		ands = append(ands, bson.M{"success": *q.Success})
	}
	if q.FromTime != nil || q.ToTime != nil {
		rng := bson.M{}
		if q.FromTime != nil {
			rng["$gte"] = *q.FromTime
		}
		if q.ToTime != nil {
			rng["$lte"] = *q.ToTime
		}
		ands = append(ands, bson.M{"occurredAt": rng})
	}
	if len(ands) == 1 {
		filter = ands[0]
	} else if len(ands) > 1 {
		filter = bson.M{"$and": ands}
	}
	limit := q.Limit
	if limit <= 0 {
		limit = 50
	}
	if limit > 200 {
		limit = 200
	}
	offset := q.Offset
	if offset < 0 {
		offset = 0
	}
	order := q.Order
	if order == "" {
		order = "newest_first"
	}
	sort := bson.D{{Key: "occurredAt", Value: -1}}
	if order == "oldest_first" {
		sort = bson.D{{Key: "occurredAt", Value: 1}}
	}
	total, err := app.store.audit.CountDocuments(ctx, filter)
	if err != nil {
		return nil, err
	}
	opts := options.Find().SetSort(sort).SetSkip(int64(offset)).SetLimit(int64(limit))
	cur, err := app.store.audit.Find(ctx, filter, opts)
	if err != nil {
		return nil, err
	}
	defer cur.Close(ctx)
	entries := []map[string]interface{}{}
	for cur.Next(ctx) {
		var raw bson.M
		if err := cur.Decode(&raw); err != nil {
			continue
		}
		entries = append(entries, normalizeAudit(raw))
	}
	returned := len(entries)
	hasMore := int64(offset+returned) < total
	res := map[string]interface{}{
		"entries":  entries,
		"total":    total,
		"returned": returned,
		"offset":   offset,
		"limit":    limit,
		"order":    order,
		"hasMore":  hasMore,
	}
	if hasMore {
		res["nextOffset"] = offset + returned
	}
	return res, nil
}

type queryAudit struct {
	Query      string
	ActorID    string
	EntityType string
	EntityID   string
	Action     string
	Role       string
	Success    *bool
	FromTime   *time.Time
	ToTime     *time.Time
	Limit      int
	Offset     int
	Order      string
}

func normalizeAudit(raw bson.M) map[string]interface{} {
	get := func(keys ...string) interface{} {
		for _, k := range keys {
			if v, ok := raw[k]; ok && v != nil {
				return v
			}
		}
		return ""
	}
	occurred := get("occurredAt", "occurred_at")
	var occurredStr string
	switch t := occurred.(type) {
	case time.Time:
		occurredStr = t.UTC().Format(time.RFC3339Nano)
	case bson.DateTime:
		occurredStr = t.Time().UTC().Format(time.RFC3339Nano)
	default:
		occurredStr = stringify(occurred)
	}
	details, _ := raw["details"].(bson.M)
	if details == nil {
		details = bson.M{}
	}
	return map[string]interface{}{
		"auditId":    get("auditId", "audit_id"),
		"audit_id":   get("audit_id", "auditId"),
		"actorId":    get("actorId", "actor_id"),
		"actor_id":   get("actor_id", "actorId"),
		"role":       get("role"),
		"actorRole":  get("actorRole", "role"),
		"action":     get("action"),
		"entityType": get("entityType", "entity_type"),
		"entity_type": get("entity_type", "entityType"),
		"entityId":   get("entityId", "entity_id"),
		"entity_id":  get("entity_id", "entityId"),
		"success":    raw["success"] == true,
		"occurredAt": occurredStr,
		"occurred_at": occurredStr,
		"details":    details,
	}
}
"}

