func (app *App) loadLocations(ctx context.Context) ([]locRow, error) {
	rows, err := app.store.pg.Query(ctx, `
SELECT id, name, latitude, longitude, coverage_km, handling_minutes, active,
  fn_collection, fn_transfer, fn_hub, fn_laboratory,
  capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
FROM locations`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []locRow{}
	byID := map[string]*locRow{}
	for rows.Next() {
		var l locRow
		if err := rows.Scan(&l.ID, &l.Name, &l.Lat, &l.Lng, &l.CoverageKm, &l.HandlingMinutes, &l.Active,
			&l.FnCollection, &l.FnTransfer, &l.FnHub, &l.FnLaboratory,
			&l.CapacityUnits, &l.ReservedUnits, &l.CooledCap, &l.CooledRes); err != nil {
			return nil, err
		}
		out = append(out, l)
		byID[l.ID] = &out[len(out)-1]
	}
	arows, err := app.store.pg.Query(ctx, `SELECT laboratory_id, sample_type_id FROM lab_acceptances WHERE accepts=TRUE`)
	if err != nil {
		return nil, err
	}
	defer arows.Close()
	for arows.Next() {
		var lab, st string
		if err := arows.Scan(&lab, &st); err != nil {
			return nil, err
		}
		if l, ok := byID[lab]; ok {
			l.AcceptedTypes = append(l.AcceptedTypes, st)
		}
	}
	// copy accepted types back
	for i := range out {
		if l, ok := byID[out[i].ID]; ok {
			out[i].AcceptedTypes = l.AcceptedTypes
		}
	}
	return out, nil
}

