		if err := rows.Scan(&c.ID, &c.From, &c.To, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active,
			&c.CapacityUnits, &c.ReservedUnits, &c.CooledCap, &c.CooledRes); err != nil {
