	err := app.store.pg.QueryRow(ctx, `
SELECT id, name, qualified_collector_required, required_qualification, container_type,
  temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed
FROM sample_types WHERE id=$1`, id).Scan(
		&st.ID, &st.Name, &st.QualifiedRequired, &st.RequiredQualification, &st.ContainerType,
		&st.TempMin, &st.TempMax, &incompat, &st.RequiresCooled, &st.BatchingAllowed)
	if err != nil {
		return nil, err
	}
	if incompat == nil {
		incompat = []string{}
	}
	st.Incompatible = incompat
	return &st, nil
}

func (app *App) loadWorkers(ctx context.Context) ([]workerRow, error) {
	rows, err := app.store.pg.Query(ctx, `
SELECT id, full_name, COALESCE(assigned_location_id::text,''), available, capacity_units, active,
  decline_count, decline_penalty_until, last_offered_at, last_assigned_at
FROM users WHERE active=TRUE`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	byID := map[string]*workerRow{}
	out := []workerRow{}
	for rows.Next() {
		var w workerRow
		if err := rows.Scan(&w.ID, &w.FullName, &w.AssignedLocationID, &w.Available, &w.CapacityUnits, &w.Active,
			&w.DeclineCount, &w.DeclineUntil, &w.LastOfferedAt, &w.LastAssignedAt); err != nil {
			return nil, err
		}
		out = append(out, w)
		byID[w.ID] = &out[len(out)-1]
	}
	rrows, err := app.store.pg.Query(ctx, `SELECT user_id, role FROM user_roles`)
	if err != nil {
		return nil, err
	}
	defer rrows.Close()
	for rrows.Next() {
		var uid, role string
		if err := rrows.Scan(&uid, &role); err != nil {
			return nil, err
		}
		if w, ok := byID[uid]; ok {
			w.Roles = append(w.Roles, role)
		}
	}
	qrows, err := app.store.pg.Query(ctx, `SELECT user_id, qualification FROM user_qualifications`)
	if err != nil {
		return nil, err
	}
	defer qrows.Close()
	for qrows.Next() {
		var uid, q string
		if err := qrows.Scan(&uid, &q); err != nil {
			return nil, err
		}
		if w, ok := byID[uid]; ok {
			w.Qualifications = append(w.Qualifications, q)
		}
	}
	crows, err := app.store.pg.Query(ctx, `SELECT user_id, code, active, expires_at FROM certifications`)
	if err != nil {
		return nil, err
	}
	defer crows.Close()
	for crows.Next() {
		var uid string
		var c Certification
		if err := crows.Scan(&uid, &c.Code, &c.Active, &c.ExpiresAt); err != nil {
			return nil, err
		}
		if w, ok := byID[uid]; ok {
			w.Certs = append(w.Certs, c)
		}
	}
	arows, err := app.store.pg.Query(ctx, `
SELECT worker_id, COUNT(*) FROM assignments
WHERE worker_id IS NOT NULL AND status NOT IN ('completed','cancelled','declined','expired')
GROUP BY worker_id`)
	if err != nil {
		return nil, err
	}
	defer arows.Close()
	for arows.Next() {
		var uid string
		var n int
		if err := arows.Scan(&uid, &n); err != nil {
			return nil, err
		}
		if w, ok := byID[uid]; ok {
			w.AssignmentCount = n
		}
	}
	// copy back
	for i := range out {
		if w, ok := byID[out[i].ID]; ok {
			out[i].Roles = w.Roles
			out[i].Qualifications = w.Qualifications
			out[i].Certs = w.Certs
			out[i].AssignmentCount = w.AssignmentCount
		}
	}
	return out, nil
}

func (app *App) serviceabilityVersion(ctx context.Context) (int, int64, time.Time, error) {
	var ver int
	var rev int64
	var at time.Time
	err := app.store.pg.QueryRow(ctx, `SELECT serviceability_version, revision, serviceability_computed_at FROM network_meta WHERE id=1`).
		Scan(&ver, &rev, &at)
	return ver, rev, at, err
}

func (app *App) bumpNetwork(ctx context.Context) {
	_, _ = app.store.pg.Exec(ctx, `UPDATE network_meta SET revision = revision + 1 WHERE id=1`)
	go app.recomputeServiceability()
}

func (app *App) recomputeServiceability() {
	app.store.mu.Lock()
	if app.store.svcComputing {
		app.store.mu.Unlock()
		return
	}
	app.store.svcComputing = true
	app.store.mu.Unlock()
	defer func() {
		app.store.mu.Lock()
		app.store.svcComputing = false
		app.store.mu.Unlock()
	}()
	ctx := context.Background()
	locs, err := app.loadLocations(ctx)
	if err != nil {
		return
	}
	_, _ = app.store.pg.Exec(ctx, `DELETE FROM serviceability_regions`)
	count := 0
	for _, l := range locs {
		if l.Active && l.FnCollection {
			_, _ = app.store.pg.Exec(ctx, `
INSERT INTO serviceability_regions (location_id, name, latitude, longitude, coverage_km)
VALUES ($1,$2,$3,$4,$5)
ON CONFLICT (location_id) DO UPDATE SET name=$2, latitude=$3, longitude=$4, coverage_km=$5`,
				l.ID, l.Name, l.Lat, l.Lng, l.CoverageKm)
			count++
		}
	}
	_, _ = app.store.pg.Exec(ctx, `
UPDATE network_meta SET serviceability_version = serviceability_version + 1,
  serviceability_computed_at = NOW() WHERE id=1`)
	_ = count
}

func (app *App) checkServiceability(ctx context.Context, origin Coord, originType, originNodeID, sampleTypeID string, requestedAt, deadline, earliest, latest time.Time) (*planResult, error) {
	st, err := app.loadSampleType(ctx, sampleTypeID)
	if err != nil {
		return nil, herr(404, "not_found", "sample type not found")
	}
	locs, err := app.loadLocations(ctx)
	if err != nil {
		return nil, err
	}
	conns, err := app.loadConnections(ctx)
	if err != nil {
		return nil, err
	}
	return planRoute(locs, conns, st, origin, originType, originNodeID, requestedAt, deadline, earliest, latest, false)
}

func planRoute(locs []locRow, conns []connRow, st *sampleTypeRow, origin Coord, originType, originNodeID string, requestedAt, deadline, earliest, latest time.Time, skipStaff bool) (*planResult, error) {
	_ = skipStaff
	byID := map[string]locRow{}
	for _, l := range locs {
		byID[l.ID] = l
	}
	// find collection points covering origin
	var starts []locRow
	if originType == "node" && originNodeID != "" {
		if l, ok := byID[originNodeID]; ok && l.Active {
			starts = []locRow{l}
		}
	} else {
		for _, l := range locs {
			if !l.Active || !l.FnCollection {
				continue
			}
			d := haversineKm(origin.Latitude, origin.Longitude, l.Lat, l.Lng)
			if d <= l.CoverageKm+1e-9 {
				starts = append(starts, l)
			}
		}
	}
	if len(starts) == 0 {
		return &planResult{Serviceable: false, Reason: "outside_service_coverage"}, nil
	}

	// labs that accept sample type
	labs := []locRow{}
	for _, l := range locs {
		if !l.Active || !l.FnLaboratory {
			continue
		}
		ok := false
		for _, t := range l.AcceptedTypes {
			if t == st.ID {
				ok = true
				break
			}
		}
		if ok {
			labs = append(labs, l)
		}
	}
	if len(labs) == 0 {
		return &planResult{Serviceable: false, Reason: "no_accepting_laboratory"}, nil
	}

	// graph of active connections
	type edge struct {
		to   string
		conn connRow
	}
	adj := map[string][]edge{}
	for _, c := range conns {
		if !c.Active {
			continue
		}
		if st.RequiresCooled && !c.Cooled {
			continue
		}
		// capacity check (network structure — configured capacity, not staff)
		needReg, needCool := 1, 0
		if st.RequiresCooled {
			needReg, needCool = 0, 1
		}
		availR := c.CapacityUnits - c.ReservedUnits
		availC := c.CooledCap - c.CooledRes
		if c.CapacityUnits == 0 && c.CooledCap == 0 {
			// unconfigured treated as unlimited for serviceability structure
		} else {
			if needReg > 0 && availR < needReg {
				continue
			}
			if needCool > 0 && availC < needCool {
				continue
			}
		}
		adj[c.From] = append(adj[c.From], edge{c.To, c})
	}

	type state struct {
		node   string
		cost   float64
		mins   int
		path   []string
		conns  []string
	}
	best := (*planResult)(nil)
	for _, start := range starts {
		// if start itself is a lab that accepts
		for _, lab := range labs {
			if start.ID == lab.ID {
				handle := start.HandlingMinutes + lab.HandlingMinutes
				arr := requestedAt.Add(time.Duration(handle) * time.Minute)
				if earliest.After(time.Time{}) && arr.Before(earliest) {
					arr = earliest.Add(time.Duration(handle) * time.Minute)
				}
				if !deadline.IsZero() && arr.After(deadline) {
					continue
				}
				cand := &planResult{
					Serviceable: true, Reason: "serviceable", TargetLab: lab.ID,
					EstimatedArrival: arr, CollectionPoint: start.ID,
					Path: []string{start.ID}, NeedsCooled: st.RequiresCooled,
					HandlingMinutes: handle,
				}
				if best == nil || cand.Cost < best.Cost {
					best = cand
				}
			}
		}
		// dijkstra
		dist := map[string]float64{start.ID: 0}
		prev := map[string]string{}
		prevC := map[string]connRow{}
		mins := map[string]int{start.ID: 0}
		pq := []state{{node: start.ID, cost: 0, mins: 0, path: []string{start.ID}}}
		seen := map[string]bool{}
		for len(pq) > 0 {
			sort.Slice(pq, func(i, j int) bool { return pq[i].cost < pq[j].cost })
			cur := pq[0]
			pq = pq[1:]
			if seen[cur.node] {
				continue
			}
			seen[cur.node] = true
			for _, e := range adj[cur.node] {
				nl := byID[e.to]
				if !nl.Active {
					continue
				}
				// node capacity
				needReg, needCool := 1, 0
				if st.RequiresCooled {
					needReg, needCool = 0, 1
				}
				if nl.CapacityUnits > 0 || nl.CooledCap > 0 {
					if needReg > 0 && nl.CapacityUnits-nl.ReservedUnits < needReg {
						continue
					}
					if needCool > 0 && nl.CooledCap-nl.CooledRes < needCool {
						continue
					}
				}
				nc := cur.cost + e.conn.CostUnits
				nm := cur.mins + e.conn.TravelMinutes + nl.HandlingMinutes
				if old, ok := dist[e.to]; !ok || nc < old {
					dist[e.to] = nc
					mins[e.to] = nm
					prev[e.to] = cur.node
					prevC[e.to] = e.conn
					np := append(append([]string{}, cur.path...), e.to)
					ncids := append(append([]string{}, cur.conns...), e.conn.ID)
					pq = append(pq, state{node: e.to, cost: nc, mins: nm, path: np, conns: ncids})
				}
			}
		}
		for _, lab := range labs {
			if lab.ID == start.ID {
				continue
			}
			c, ok := dist[lab.ID]
			if !ok {
				continue
			}
			handle := start.HandlingMinutes
			totalMins := mins[lab.ID] + handle
			// reconstruct
			path := []string{lab.ID}
			conIDs := []string{}
			cur := lab.ID
			for cur != start.ID {
				p, ok := prev[cur]
				if !ok {
					path = nil
					break
				}
				conIDs = append([]string{prevC[cur].ID}, conIDs...)
				path = append([]string{p}, path...)
				cur = p
			}
			if path == nil {
				continue
			}
			startAt := requestedAt
			if !earliest.IsZero() && earliest.After(startAt) {
				startAt = earliest
			}
			arr := startAt.Add(time.Duration(totalMins) * time.Minute)
			if !deadline.IsZero() && arr.After(deadline) {
				continue
			}
			// lab capacity
			needReg, needCool := 1, 0
			if st.RequiresCooled {
				needReg, needCool = 0, 1
			}
			if lab.CapacityUnits > 0 || lab.CooledCap > 0 {
				if needReg > 0 && lab.CapacityUnits-lab.ReservedUnits < needReg {
					continue
				}
				if needCool > 0 && lab.CooledCap-lab.CooledRes < needCool {
					continue
				}
			}
			cand := &planResult{
				Serviceable: true, Reason: "serviceable", TargetLab: lab.ID,
				EstimatedArrival: arr, CollectionPoint: start.ID,
				Path: path, Connections: conIDs, Cost: c, TravelMinutes: totalMins,
				HandlingMinutes: handle, NeedsCooled: st.RequiresCooled,
			}
			if best == nil || cand.Cost < best.Cost || (cand.Cost == best.Cost && cand.TravelMinutes < best.TravelMinutes) {
				best = cand
			}
		}
	}
	if best == nil {
		// distinguish no route vs deadline vs capacity
		// try without deadline / capacity to classify
		// simple: if any path exists ignoring deadline
		return &planResult{Serviceable: false, Reason: classifyUnserviceable(locs, conns, st, starts, labs)}, nil
	}
	return best, nil
}

func classifyUnserviceable(locs []locRow, conns []connRow, st *sampleTypeRow, starts, labs []locRow) string {
	// connectivity ignoring capacity and cooling
	adj := map[string][]string{}
	for _, c := range conns {
		if c.Active {
			adj[c.From] = append(adj[c.From], c.To)
		}
	}
	reachLab := false
	for _, s := range starts {
		seen := map[string]bool{s.ID: true}
		q := []string{s.ID}
		for len(q) > 0 {
			n := q[0]
			q = q[1:]
			for _, lab := range labs {
				if lab.ID == n {
					reachLab = true
				}
			}
			for _, to := range adj[n] {
				if !seen[to] {
					seen[to] = true
					q = append(q, to)
				}
			}
		}
	}
	if !reachLab {
		// try with cooling ignored already; if cooled required maybe no cooled route
		if st.RequiresCooled {
			// check if any cooled path
			adjc := map[string][]string{}
			for _, c := range conns {
				if c.Active && c.Cooled {
					adjc[c.From] = append(adjc[c.From], c.To)
				}
			}
			ok := false
			for _, s := range starts {
				seen := map[string]bool{s.ID: true}
				q := []string{s.ID}
				for len(q) > 0 {
					n := q[0]
					q = q[1:]
					for _, lab := range labs {
						if lab.ID == n {
							ok = true
						}
					}
					for _, to := range adjc[n] {
						if !seen[to] {
							seen[to] = true
							q = append(q, to)
						}
					}
				}
			}
			if !ok {
				return "no_route"
			}
		}
		return "no_route"
	}
	return "deadline_unreachable"
}

func (w workerRow) hasRole(r string) bool {
	for _, x := range w.Roles {
		if x == r {
			return true
		}
	}
	return false
}

func (w workerRow) hasQual(code string) bool {
	if code == "" {
		return true
	}
	for _, q := range w.Qualifications {
		if q == code {
			return true
		}
	}
	for _, c := range w.Certs {
		if c.Code == code && c.Active {
			if c.ExpiresAt == nil || c.ExpiresAt.After(time.Now()) {
				return true
			}
		}
	}
	return false
}

func (w workerRow) certActive(code string) bool {
	return w.hasQual(code)
}

func pickWorker(workers []workerRow, role, qual, assignedLoc string, now time.Time) *workerRow {
	var cands []workerRow
	for _, w := range workers {
		if !w.Active || !w.Available {
			continue
		}
		if !w.hasRole(role) {
			continue
		}
		if qual != "" && !w.hasQual(qual) {
			continue
		}
		if assignedLoc != "" && w.AssignedLocationID != assignedLoc {
			continue
		}
		if w.DeclineUntil != nil && w.DeclineUntil.After(now) {
			// still eligible but deprioritized
		}
		cands = append(cands, w)
	}
	if len(cands) == 0 {
		return nil
	}
	sort.Slice(cands, func(i, j int) bool {
		pi, pj := 0, 0
		if cands[i].DeclineUntil != nil && cands[i].DeclineUntil.After(now) {
			pi = 1
		}
		if cands[j].DeclineUntil != nil && cands[j].DeclineUntil.After(now) {
			pj = 1
		}
		if pi != pj {
			return pi < pj
		}
		if cands[i].AssignmentCount != cands[j].AssignmentCount {
			return cands[i].AssignmentCount < cands[j].AssignmentCount
		}
		ti, tj := time.Time{}, time.Time{}
		if cands[i].LastOfferedAt != nil {
			ti = *cands[i].LastOfferedAt
		}
		if cands[j].LastOfferedAt != nil {
			tj = *cands[j].LastOfferedAt
		}
		if !ti.Equal(tj) {
			return ti.Before(tj)
		}
		return cands[i].ID < cands[j].ID
	})
	return &cands[0]
}

func (app *App) reserveCapacity(ctx context.Context, resourceID, kind, journeyID, sampleID string, regular, cooled int) error {
	if regular == 0 && cooled == 0 {
		return nil
	}
	var cap, res, ccap, cres int
	var q string
	switch kind {
	case "location":
		q = `SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM locations WHERE id=$1 FOR UPDATE`
	case "connection":
		q = `SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM connections WHERE id=$1 FOR UPDATE`
	default:
		return fmt.Errorf("unknown resource kind")
	}
	if err := app.store.pg.QueryRow(ctx, q, resourceID).Scan(&cap, &res, &ccap, &cres); err != nil {
		return err
	}
	// 0 configured = unlimited
	if cap > 0 && res+regular > cap {
		return herr(409, "capacity_exhausted", "capacity exhausted")
	}
	if ccap > 0 && cres+cooled > ccap {
		return herr(409, "cooled_capacity_exhausted", "cooled capacity exhausted")
	}
	upd := ""
	switch kind {
	case "location":
		upd = `UPDATE locations SET reserved_units = reserved_units + $2, cooled_reserved_units = cooled_reserved_units + $3 WHERE id=$1`
	case "connection":
		upd = `UPDATE connections SET reserved_units = reserved_units + $2, cooled_reserved_units = cooled_reserved_units + $3 WHERE id=$1`
	}
	if _, err := app.store.pg.Exec(ctx, upd, resourceID, regular, cooled); err != nil {
		return err
	}
	_, err := app.store.pg.Exec(ctx, `
INSERT INTO capacity_reservations (id, resource_id, resource_kind, journey_id, sample_id, regular_units, cooled_units, active)
VALUES ($1,$2,$3,$4,$5,$6,$7,TRUE)`, newUUID(), resourceID, kind, journeyID, sampleID, regular, cooled)
	return err
}

func (app *App) releaseJourneyCapacity(ctx context.Context, journeyID string) error {
	rows, err := app.store.pg.Query(ctx, `
SELECT id, resource_id, resource_kind, regular_units, cooled_units
FROM capacity_reservations WHERE journey_id=$1 AND active=TRUE`, journeyID)
	if err != nil {
		return err
	}
	defer rows.Close()
	type resv struct {
		id, rid, kind string
		reg, cool     int
	}
	list := []resv{}
	for rows.Next() {
		var r resv
		if err := rows.Scan(&r.id, &r.rid, &r.kind, &r.reg, &r.cool); err != nil {
			return err
		}
		list = append(list, r)
	}
	for _, r := range list {
		var upd string
		switch r.kind {
		case "location":
			upd = `UPDATE locations SET reserved_units = GREATEST(reserved_units - $2, 0), cooled_reserved_units = GREATEST(cooled_reserved_units - $3, 0) WHERE id=$1`
		case "connection":
			upd = `UPDATE connections SET reserved_units = GREATEST(reserved_units - $2, 0), cooled_reserved_units = GREATEST(cooled_reserved_units - $3, 0) WHERE id=$1`
		}
		if upd != "" {
			_, _ = app.store.pg.Exec(ctx, upd, r.rid, r.reg, r.cool)
		}
		_, _ = app.store.pg.Exec(ctx, `UPDATE capacity_reservations SET active=FALSE WHERE id=$1`, r.id)
	}
	return nil
}

func (app *App) materializeJourney(ctx context.Context, actor *SessionUser, sampleID, requestID string, plan *planResult, st *sampleTypeRow, origin Coord, originType string, earliest, latest, deadline time.Time, alreadySealed bool) (journeyID string, assignmentIDs []string, err error) {
	now := time.Now().UTC()
	journeyID = newUUID()
	mode := "direct"
	if len(plan.Path) > 2 {
		mode = "multi_stop"
	}
	_, err = app.store.pg.Exec(ctx, `
INSERT INTO journeys (id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, capacity_used, capacity_available, valid, replan_status)
VALUES ($1,1,$2,'planned',$3,$4,1,0,TRUE,'not_required')`,
		journeyID, mode, plan.EstimatedArrival, plan.Cost)
	if err != nil {
		return "", nil, err
	}
	_, err = app.store.pg.Exec(ctx, `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2)`, journeyID, sampleID)
	if err != nil {
		return "", nil, err
	}

	// stops
	seq := 0
	// origin pickup stop (virtual)
	originStopID := newUUID()
	_, err = app.store.pg.Exec(ctx, `
INSERT INTO journey_stops (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude)
VALUES ($1,$2,$3,'pickup',$4,$5,0,$6,$7)`,
		originStopID, journeyID, nilIfEmpty(plan.CollectionPoint), seq, earliest, origin.Latitude, origin.Longitude)
	if err != nil {
		return "", nil, err
	}
	seq++
	for i, locID := range plan.Path {
		stType := "handoff"
		if i == len(plan.Path)-1 {
			stType = "delivery"
		}
		var lat, lng *float64
		var loc *locRow
		// look up
		_ = app.store.pg.QueryRow(ctx, `SELECT latitude, longitude FROM locations WHERE id=$1`, locID).Scan(new(float64), new(float64))
		row := locRow{}
		if e := app.store.pg.QueryRow(ctx, `SELECT latitude, longitude FROM locations WHERE id=$1`, locID).Scan(&row.Lat, &row.Lng); e == nil {
			lat, lng = &row.Lat, &row.Lng
			loc = &row
		}
		_ = loc
		est := earliest.Add(time.Duration(i*15) * time.Minute)
		_, err = app.store.pg.Exec(ctx, `
INSERT INTO journey_stops (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude)
VALUES ($1,$2,$3,$4,$5,$6,0,$7,$8)`, newUUID(), journeyID, locID, stType, seq, est, lat, lng)
		if err != nil {
			return "", nil, err
		}
		seq++
	}

	workers, err := app.loadWorkers(ctx)
	if err != nil {
		return "", nil, err
	}

	// reserve capacity
	reg, cool := 1, 0
	if st.RequiresCooled {
		reg, cool = 0, 1
	}
	for _, locID := range plan.Path {
		if err := app.reserveCapacity(ctx, locID, "location", journeyID, sampleID, reg, cool); err != nil {
			return "", nil, err
		}
	}
	for _, cid := range plan.Connections {
		if err := app.reserveCapacity(ctx, cid, "connection", journeyID, sampleID, reg, cool); err != nil {
			return "", nil, err
		}
	}

	// assignments
	// collection if not already sealed
	if !alreadySealed {
		aid := newUUID()
		w := pickWorker(workers, RoleCollectionProfessional, st.RequiredQualification, "", now)
		var offered *string
		status := "unassigned"
		var exp *time.Time
		if w != nil {
			offered = &w.ID
			status = "offered"
			t := now.Add(offerTTL)
			exp = &t
			_, _ = app.store.pg.Exec(ctx, `UPDATE users SET last_offered_at=NOW() WHERE id=$1`, w.ID)
		}
		_, err = app.store.pg.Exec(ctx, `
INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, status, from_location_id, to_location_id, offered_to, offer_expires_at, expected_sample_type_id)
VALUES ($1,$2,$3,'collection',0,$4,$5,$6,$7,$8,$9)`,
			aid, journeyID, sampleID, status, nilIfEmpty(plan.CollectionPoint), nilIfEmpty(plan.CollectionPoint), offered, exp, st.ID)
		if err != nil {
			return "", nil, err
		}
		assignmentIDs = append(assignmentIDs, aid)
	}

	// transport legs
	fromLoc := ""
	if alreadySealed && originType == "node" {
		fromLoc = plan.CollectionPoint
	}
	// first hop from origin/collection point along path
	path := plan.Path
	for i := 0; i < len(path); i++ {
		from := plan.CollectionPoint
		if i > 0 {
			from = path[i-1]
		} else if alreadySealed && originType == "node" {
			from = path[0]
			if i == 0 && len(path) == 1 {
				// already at lab
				break
			}
			if i == 0 && len(path) > 1 {
				// start from first path node to next
				from = path[0]
				// skip creating a 0-length first hop if sealed at first node
				continue
			}
		}
		to := path[i]
		if from == to && i == 0 && !alreadySealed {
			// collection delivers to collection point; first transport is collection-point onward
			if len(path) == 1 {
				// origin covered by a lab that is also a collection point: still need a transport? treat as node/lab assignment
			} else {
				continue
			}
		}
		if from == "" {
			from = to
		}
		if from == to && len(path) > 1 && i == 0 {
			continue
		}
		aid := newUUID()
		w := pickWorker(workers, RoleDeliveryPartner, "", "", now)
		var offered *string
		status := "unassigned"
		var exp *time.Time
		if w != nil {
			offered = &w.ID
			status = "offered"
			t := now.Add(offerTTL)
			exp = &t
			_, _ = app.store.pg.Exec(ctx, `UPDATE users SET last_offered_at=NOW() WHERE id=$1`, w.ID)
		}
		_, err = app.store.pg.Exec(ctx, `
INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, status, from_location_id, to_location_id, offered_to, offer_expires_at)
VALUES ($1,$2,$3,'transport',$4,$5,$6,$7,$8,$9)`,
			aid, journeyID, sampleID, i+1, status, nilIfEmpty(from), nilIfEmpty(to), offered, exp)
		if err != nil {
			return "", nil, err
		}
		assignmentIDs = append(assignmentIDs, aid)
		_ = fromLoc
	}

	// node assignments for intermediate hubs/transfer
	for i, locID := range path {
		if i == len(path)-1 {
			continue
		}
		var fnHub, fnTransfer bool
		_ = app.store.pg.QueryRow(ctx, `SELECT fn_hub, fn_transfer FROM locations WHERE id=$1`, locID).Scan(&fnHub, &fnTransfer)
		if !fnHub && !fnTransfer && i > 0 {
			continue
		}
		if i == 0 && !fnHub && !fnTransfer {
			// collection point only
		}
		aid := newUUID()
		w := pickWorker(workers, RoleNodeHandler, "", locID, now)
		var offered *string
		status := "unassigned"
		var exp *time.Time
		if w != nil {
			offered = &w.ID
			status = "offered"
			t := now.Add(offerTTL)
			exp = &t
			_, _ = app.store.pg.Exec(ctx, `UPDATE users SET last_offered_at=NOW() WHERE id=$1`, w.ID)
		}
		var incoming, outgoing *string
		if i > 0 {
			incoming = &path[i-1]
		}
		if i+1 < len(path) {
			outgoing = &path[i+1]
		}
		_, err = app.store.pg.Exec(ctx, `
INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, status, node_id, incoming_from_location_id, outgoing_to_location_id, offered_to, offer_expires_at)
VALUES ($1,$2,$3,'node',$4,$5,$6,$7,$8,$9,$10)`,
			aid, journeyID, sampleID, 100+i, status, locID, incoming, outgoing, offered, exp)
		if err != nil {
			return "", nil, err
		}
		assignmentIDs = append(assignmentIDs, aid)
	}

	// laboratory assignment
	if plan.TargetLab != "" {
		aid := newUUID()
		w := pickWorker(workers, RoleLaboratoryTeam, "", plan.TargetLab, now)
		var offered *string
		status := "unassigned"
		var exp *time.Time
		if w != nil {
			offered = &w.ID
			status = "offered"
			t := now.Add(offerTTL)
			exp = &t
			_, _ = app.store.pg.Exec(ctx, `UPDATE users SET last_offered_at=NOW() WHERE id=$1`, w.ID)
		}
		_, err = app.store.pg.Exec(ctx, `
INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, status, laboratory_id, expected_sample_type_id, offered_to, offer_expires_at)
VALUES ($1,$2,$3,'laboratory',200,$4,$5,$6,$7,$8)`,
			aid, journeyID, sampleID, status, plan.TargetLab, st.ID, offered, exp)
		if err != nil {
			return "", nil, err
		}
		assignmentIDs = append(assignmentIDs, aid)
	}

	_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET active_journey_id=$1, target_laboratory_id=$2 WHERE id=$3`, journeyID, plan.TargetLab, sampleID)
	return journeyID, assignmentIDs, nil
}

func nilIfEmpty(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}

func (app *App) expireOffers(ctx context.Context) {
	now := time.Now().UTC()
	rows, err := app.store.pg.Query(ctx, `
SELECT id, offered_to, sample_id, kind, journey_id FROM assignments
WHERE status='offered' AND offer_expires_at IS NOT NULL AND offer_expires_at < $1`, now)
	if err != nil {
		return
	}
	defer rows.Close()
	type off struct{ id, worker, sample, kind, journey string }
	list := []off{}
	for rows.Next() {
		var o off
		var w *string
		if err := rows.Scan(&o.id, &w, &o.sample, &o.kind, &o.journey); err != nil {
			continue
		}
		if w != nil {
			o.worker = *w
		}
		list = append(list, o)
	}
	for _, o := range list {
		_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='declined', declined_at=NOW() WHERE id=$1 AND status='offered'`, o.id)
		app.reoffer(ctx, o.id)
	}
}

func (app *App) reoffer(ctx context.Context, assignmentID string) {
	var kind, sampleID, journeyID string
	var nodeID, labID, offeredTo *string
	var expectedType *string
	err := app.store.pg.QueryRow(ctx, `
SELECT kind, sample_id, journey_id, node_id, laboratory_id, offered_to, expected_sample_type_id
FROM assignments WHERE id=$1`, assignmentID).Scan(&kind, &sampleID, &journeyID, &nodeID, &labID, &offeredTo, &expectedType)
	if err != nil {
		return
	}
	workers, err := app.loadWorkers(ctx)
	if err != nil {
		return
	}
	now := time.Now().UTC()
	var role, qual, loc string
	switch kind {
	case "collection":
		role = RoleCollectionProfessional
		if expectedType != nil {
			if st, e := app.loadSampleType(ctx, *expectedType); e == nil {
				qual = st.RequiredQualification
			}
		}
	case "transport":
		role = RoleDeliveryPartner
	case "node":
		role = RoleNodeHandler
		if nodeID != nil {
			loc = *nodeID
		}
	case "laboratory":
		role = RoleLaboratoryTeam
		if labID != nil {
			loc = *labID
		}
	}
	// exclude last offered
	filtered := []workerRow{}
	for _, w := range workers {
		if offeredTo != nil && w.ID == *offeredTo {
			continue
		}
		filtered = append(filtered, w)
	}
	w := pickWorker(filtered, role, qual, loc, now)
	if w == nil {
		// try including previous
		w = pickWorker(workers, role, qual, loc, now)
	}
	if w == nil {
		// flag exception: no qualified worker
		if sampleID != "" {
			exc := map[string]interface{}{"reason": "no_qualified_worker", "assignmentId": assignmentID, "kind": kind}
			_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status='exception', exception=$2 WHERE id=$1 AND status NOT IN ('received','cancelled')`, sampleID, asJSON(exc))
			app.audit(ctx, "system", "system", "exception.no_qualified_worker", "sample", sampleID, true, exc)
			app.emit("sample.exception", "sample", sampleID, exc)
		}
		_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='unassigned', offered_to=NULL, offer_expires_at=NULL WHERE id=$1`, assignmentID)
		return
	}
	exp := now.Add(offerTTL)
	_, _ = app.store.pg.Exec(ctx, `
UPDATE assignments SET status='offered', offered_to=$2, offer_expires_at=$3, worker_id=NULL WHERE id=$1`,
		assignmentID, w.ID, exp)
	_, _ = app.store.pg.Exec(ctx, `UPDATE users SET last_offered_at=NOW() WHERE id=$1`, w.ID)
	app.emit("assignment.offered", "assignment", assignmentID, map[string]interface{}{"workerId": w.ID})
}

func (app *App) startOfferScanner() {
	go func() {
		t := time.NewTicker(offerScanInterval)
		defer t.Stop()
		for range t.C {
			app.expireOffers(context.Background())
		}
	}()
}
"}

