	if err != nil {
		app.handleErr(w, err)
		return
	}
	app.audit(r.Context(), u.UserID, req.Role, "auth.select_role", "user", u.UserID, true, map[string]interface{}{"role": req.Role})
	writeData(w, 200, map[string]interface{}{
		"activeRole": req.Role,
		"roles":      u.Roles,
	})
}

func (app *App) handleCreateUser(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u.ActiveRole != RoleAdministrator {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		Username           string           `json:"username"`
		InitialPassword    string           `json:"initialPassword"`
		Email              string           `json:"email"`
		FullName           string           `json:"fullName"`
		Phone              string           `json:"phone"`
		Roles              []string         `json:"roles"`
		Qualifications     []string         `json:"qualifications"`
		Certifications     []Certification  `json:"certifications"`
		Active             bool             `json:"active"`
		AssignedLocationID string           `json:"assignedLocationId"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.Username == "" || req.InitialPassword == "" || len(req.Roles) == 0 {
		writeErr(w, 400, "invalid_user", "invalid user")
		return
	}
	for _, role := range req.Roles {
		if !validRole(role) {
			writeErr(w, 400, "invalid_user", "invalid role")
			return
		}
	}
	var exists int
	_ = app.store.pg.QueryRow(r.Context(), `SELECT COUNT(*) FROM users WHERE username=$1`, req.Username).Scan(&exists)
	if exists > 0 {
		writeErr(w, 409, "username_exists", "username exists")
		return
	}
	hash, err := hashPassword(req.InitialPassword)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	id := newUUID()
	var assigned interface{}
	if req.AssignedLocationID != "" {
		assigned = req.AssignedLocationID
	}
	_, err = app.store.pg.Exec(r.Context(), `
INSERT INTO users (id, username, password_hash, email, full_name, phone, active, assigned_location_id)
VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
		id, req.Username, hash, req.Email, req.FullName, req.Phone, req.Active, assigned)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	for _, role := range req.Roles {
		_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO user_roles (user_id, role) VALUES ($1,$2)`, id, role)
	}
	if req.Qualifications == nil {
		req.Qualifications = []string{}
	}
	for _, q := range req.Qualifications {
		_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO user_qualifications (user_id, qualification) VALUES ($1,$2)`, id, q)
	}
	if req.Certifications == nil {
		req.Certifications = []Certification{}
	}
	for _, c := range req.Certifications {
		if c.Code == "" {
			writeErr(w, 400, "invalid_certification", "invalid certification")
			return
		}
		_, _ = app.store.pg.Exec(r.Context(), `
INSERT INTO certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)`, id, c.Code, c.Active, c.ExpiresAt)
	}
	app.audit(r.Context(), u.UserID, u.ActiveRole, "user.create", "user", id, true, map[string]interface{}{"username": req.Username, "roles": req.Roles})
	writeData(w, 201, map[string]interface{}{
		"userId":         id,
		"username":       req.Username,
		"email":          req.Email,
		"fullName":       req.FullName,
		"phone":          req.Phone,
		"roles":          req.Roles,
		"qualifications": req.Qualifications,
		"certifications": req.Certifications,
		"active":         req.Active,
	})
}

func (app *App) handleUpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u.ActiveRole != RoleAdministrator {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		UserID             string          `json:"userId"`
		Roles              []string        `json:"roles"`
		Qualifications     []string        `json:"qualifications"`
		Certifications     []Certification `json:"certifications"`
		Active             bool            `json:"active"`
		AssignedLocationID string          `json:"assignedLocationId"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	var exists int
	_ = app.store.pg.QueryRow(r.Context(), `SELECT COUNT(*) FROM users WHERE id=$1`, req.UserID).Scan(&exists)
	if exists == 0 {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	for _, role := range req.Roles {
		if !validRole(role) {
			writeErr(w, 400, "invalid_json", "invalid role")
			return
		}
	}
	var assigned interface{}
	if req.AssignedLocationID != "" {
		assigned = req.AssignedLocationID
	}
	_, err := app.store.pg.Exec(r.Context(), `UPDATE users SET active=$2, assigned_location_id=$3 WHERE id=$1`, req.UserID, req.Active, assigned)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	_, _ = app.store.pg.Exec(r.Context(), `DELETE FROM user_roles WHERE user_id=$1`, req.UserID)
	for _, role := range req.Roles {
		_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO user_roles (user_id, role) VALUES ($1,$2)`, req.UserID, role)
	}
	if req.Qualifications != nil {
		_, _ = app.store.pg.Exec(r.Context(), `DELETE FROM user_qualifications WHERE user_id=$1`, req.UserID)
		for _, q := range req.Qualifications {
			_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO user_qualifications (user_id, qualification) VALUES ($1,$2)`, req.UserID, q)
		}
	}
	if req.Certifications != nil {
		_, _ = app.store.pg.Exec(r.Context(), `DELETE FROM certifications WHERE user_id=$1`, req.UserID)
		for _, c := range req.Certifications {
			if c.Code == "" {
				writeErr(w, 400, "invalid_certification", "invalid certification")
				return
			}
			_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)`, req.UserID, c.Code, c.Active, c.ExpiresAt)
		}
	}
	loaded, _ := app.loadUser(r.Context(), req.UserID, "")
	app.audit(r.Context(), u.UserID, u.ActiveRole, "user.update_access", "user", req.UserID, true, map[string]interface{}{"roles": req.Roles})
	writeData(w, 201, map[string]interface{}{
		"userId":         req.UserID,
		"roles":          loaded.Roles,
		"qualifications": loaded.Qualifications,
		"certifications": loaded.Certifications,
		"active":         req.Active,
	})
}

func (app *App) handleReadUser(w http.ResponseWriter, r *http.Request) {
	userID := r.PathValue("userId")
	u := currentUser(r)
	if u.ActiveRole != RoleAdministrator && u.UserID != userID && !u.isDispatcher() {
		writeErr(w, 403, "forbidden", "forbidden")
