	var email, phone string
	_ = app.store.pg.QueryRow(r.Context(), `SELECT email, phone FROM users WHERE id=$1`, userID).Scan(&email, &phone)
	writeData(w, 200, map[string]interface{}{
		"userId":         loaded.UserID,
		"username":       loaded.Username,
		"email":          email,
		"fullName":       loaded.FullName,
		"phone":          phone,
		"roles":          loaded.Roles,
		"qualifications": loaded.Qualifications,
		"certifications": loaded.Certifications,
		"active":         loaded.Active,
	})
}

func (app *App) handleSetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if !u.isDispatcher() && u.ActiveRole != RoleAdministrator {
		// workers can set their own
		var reqPeek struct {
			WorkerID string `json:"workerId"`
		}
		// will decode again below
		_ = reqPeek
	}
	var req struct {
		WorkerID      string `json:"workerId"`
		Available     bool   `json:"available"`
		CapacityUnits int    `json:"capacityUnits"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.CapacityUnits < 0 {
		writeErr(w, 400, "invalid_capacity", "invalid capacity")
		return
	}
	if !u.isDispatcher() && u.UserID != req.WorkerID {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var exists int
	_ = app.store.pg.QueryRow(r.Context(), `SELECT COUNT(*) FROM users WHERE id=$1`, req.WorkerID).Scan(&exists)
	if exists == 0 {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	_, err := app.store.pg.Exec(r.Context(), `UPDATE users SET available=$2, capacity_units=$3 WHERE id=$1`, req.WorkerID, req.Available, req.CapacityUnits)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	app.audit(r.Context(), u.UserID, u.ActiveRole, "worker.set_availability", "user", req.WorkerID, true, map[string]interface{}{"available": req.Available})
	writeData(w, 200, map[string]interface{}{
		"workerId":      req.WorkerID,
		"available":     req.Available,
		"capacityUnits": req.CapacityUnits,
	})
}
