func (app *App) handleSetCapacity(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	var req struct {
		ResourceType        string `json:"resourceType"`
		ResourceID          string `json:"resourceId"`
		CapacityUnits       int    `json:"capacityUnits"`
		CooledCapacityUnits int    `json:"cooledCapacityUnits"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.CapacityUnits < 0 || req.CooledCapacityUnits < 0 {
		writeErr(w, 400, "invalid_capacity", "invalid capacity")
		return
	}
	// node handler / lab team can set their assigned location
	if u.ActiveRole == RoleAdministrator || u.isDispatcher() {
		// ok
	} else if (u.ActiveRole == RoleNodeHandler || u.ActiveRole == RoleLaboratoryTeam) && u.AssignedLocationID == req.ResourceID && (req.ResourceType == "node" || req.ResourceType == "laboratory") {
		// ok
	} else {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var reserved, cooledReserved int
	switch req.ResourceType {
	case "node", "laboratory":
		err := app.store.pg.QueryRow(r.Context(), `SELECT reserved_units, cooled_reserved_units FROM locations WHERE id=$1`, req.ResourceID).Scan(&reserved, &cooledReserved)
		if err != nil {
			writeErr(w, 404, "not_found", "not found")
			return
		}
		if reserved > req.CapacityUnits && req.CapacityUnits > 0 {
			writeErr(w, 409, "capacity_below_reserved", "capacity below reserved")
			return
		}
		if cooledReserved > req.CooledCapacityUnits && req.CooledCapacityUnits > 0 {
			writeErr(w, 409, "capacity_below_reserved", "capacity below reserved")
			return
		}
		_, err = app.store.pg.Exec(r.Context(), `UPDATE locations SET capacity_units=$2, cooled_capacity_units=$3 WHERE id=$1`, req.ResourceID, req.CapacityUnits, req.CooledCapacityUnits)
		if err != nil {
			app.handleErr(w, err)
			return
		}
	case "connection":
		err := app.store.pg.QueryRow(r.Context(), `SELECT reserved_units, cooled_reserved_units FROM connections WHERE id=$1`, req.ResourceID).Scan(&reserved, &cooledReserved)
		if err != nil {
			writeErr(w, 404, "not_found", "not found")
			return
		}
		if reserved > req.CapacityUnits && req.CapacityUnits > 0 {
			writeErr(w, 409, "capacity_below_reserved", "capacity below reserved")
			return
		}
		_, err = app.store.pg.Exec(r.Context(), `UPDATE connections SET capacity_units=$2, cooled_capacity_units=$3 WHERE id=$1`, req.ResourceID, req.CapacityUnits, req.CooledCapacityUnits)
		if err != nil {
			app.handleErr(w, err)
			return
		}
	default:
		writeErr(w, 400, "invalid_resource_type", "invalid resource type")
		return
	}
	app.bumpNetwork(r.Context())
	app.audit(r.Context(), u.UserID, u.ActiveRole, "capacity.set", req.ResourceType, req.ResourceID, true, map[string]interface{}{"capacityUnits": req.CapacityUnits})
	writeData(w, 200, map[string]interface{}{
		"resourceType": req.ResourceType,
		"resourceId":   req.ResourceID,
		"capacity": Capacity{
			CapacityUnits: req.CapacityUnits, ReservedUnits: reserved,
			CooledCapacityUnits: req.CooledCapacityUnits, CooledReservedUnits: cooledReserved,
		}.fillAvail(),
	})
}

