func (app *App) handleListSampleTypes(w http.ResponseWriter, r *http.Request) {
	rows, err := app.store.pg.Query(r.Context(), `
SELECT id, name, qualified_collector_required, required_qualification, container_type,
  temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed
FROM sample_types ORDER BY name`)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	defer rows.Close()
	list := []map[string]interface{}{}
	for rows.Next() {
		var st sampleTypeRow
		var incompat []string
		if err := rows.Scan(&st.ID, &st.Name, &st.QualifiedRequired, &st.RequiredQualification, &st.ContainerType,
			&st.TempMin, &st.TempMax, &incompat, &st.RequiresCooled, &st.BatchingAllowed); err != nil {
			continue
		}
		if incompat == nil {
			incompat = []string{}
		}
		list = append(list, map[string]interface{}{
			"sampleTypeId":               st.ID,
			"name":                       st.Name,
			"qualifiedCollectorRequired": st.QualifiedRequired,
			"requiredQualification":      st.RequiredQualification,
			"containerType":              st.ContainerType,
			"temperatureMinC":            st.TempMin,
			"temperatureMaxC":            st.TempMax,
			"incompatibleSampleTypes":    incompat,
			"requiresCooledRoute":        st.RequiresCooled,
			"batchingAllowed":            st.BatchingAllowed,
		})
	}
	writeData(w, 200, map[string]interface{}{"sampleTypes": list})
}

func (app *App) handleReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	ver, _, at, err := app.serviceabilityVersion(r.Context())
	if err != nil {
		app.handleErr(w, err)
		return
	}
	rows, err := app.store.pg.Query(r.Context(), `SELECT location_id, name, latitude, longitude, coverage_km FROM serviceability_regions`)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	defer rows.Close()
	regions := []map[string]interface{}{}
	for rows.Next() {
		var id, name string
		var lat, lng, cov float64
		if err := rows.Scan(&id, &name, &lat, &lng, &cov); err != nil {
			continue
		}
		regions = append(regions, map[string]interface{}{
			"locationId": id,
			"name":       name,
			"center":     Coord{lat, lng},
			"coverageKm": cov,
		})
	}
	// if empty, compute on the fly from current locations (still a complete version)
	if len(regions) == 0 {
		locs, _ := app.loadLocations(r.Context())
		for _, l := range locs {
			if l.Active && l.FnCollection {
				regions = append(regions, map[string]interface{}{
					"locationId": l.ID, "name": l.Name, "center": Coord{l.Lat, l.Lng}, "coverageKm": l.CoverageKm,
				})
			}
		}
	}
	writeData(w, 200, map[string]interface{}{
		"version":    ver,
		"computedAt": at.UTC().Format(time.RFC3339Nano),
		"regions":    regions,
	})
}
"}

