func (app *App) handleReadSample(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("sampleId")
	s, err := app.loadSampleState(r.Context(), id)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	u := currentUser(r)
	if !app.canSeeSample(u, s) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	writeData(w, 200, s)
}

func (app *App) canSeeSample(u *SessionUser, s map[string]interface{}) bool {
	if u.isDispatcher() || u.ActiveRole == RoleAdministrator {
		return true
	}
	if u.ActiveRole == RoleRequester {
		return s["requesterId"] == u.UserID
	}
	// workers who hold or are assigned
	if holder, _ := s["currentHolderId"].(string); holder == u.UserID {
		return true
	}
	return app.userTouchesSample(u.UserID, s["sampleId"].(string))
}

func (app *App) userTouchesSample(userID, sampleID string) bool {
	var n int
	_ = app.store.pg.QueryRow(contextBG(), `
SELECT COUNT(*) FROM assignments
WHERE sample_id=$1 AND (worker_id=$2 OR offered_to=$2)`, sampleID, userID).Scan(&n)
	return n > 0
}

func (app *App) loadSampleState(ctx interface{ Done() <-chan struct{} }, id string) (map[string]interface{}, error) {
	return app.loadSampleStateC(id)
}

func (app *App) loadSampleStateC(id string) (map[string]interface{}, error) {
	var requestID, requesterID, typeID, status, svc, reason string
	var sealed bool
	var holder, journey, target, received *string
	var container string
	var tmin, tmax float64
	var incompat []string
	var olat, olng float64
	var otype string
	var requested, deadline, earliest, latest time.Time
	var llat, llng *float64
	var locAt *time.Time
	var exc []byte
	err := app.store.pg.QueryRow(contextBG(), `
SELECT request_id, requester_id, sample_type_id, status, sealed, current_holder_id,
  serviceability, serviceability_reason, active_journey_id, target_laboratory_id, received_laboratory_id,
  container_type, temperature_min_c, temperature_max_c, incompatible_sample_types,
  origin_lat, origin_lng, origin_type, requested_at, delivery_deadline, earliest_collection_at, latest_collection_at,
  latest_lat, latest_lng, location_recorded_at, exception
FROM samples WHERE id=$1`, id).Scan(
		&requestID, &requesterID, &typeID, &status, &sealed, &holder,
		&svc, &reason, &journey, &target, &received,
		&container, &tmin, &tmax, &incompat,
		&olat, &olng, &otype, &requested, &deadline, &earliest, &latest,
		&llat, &llng, &locAt, &exc)
	if err != nil {
		return nil, err
	}
	if incompat == nil {
		incompat = []string{}
	}
	now := time.Now().UTC()
	var loc map[string]interface{}
	if llat != nil && llng != nil {
		stale := isStale(locAt, now)
		loc = map[string]interface{}{
			"coordinates":     Coord{*llat, *llng},
			"recordedAt":      locAt.UTC().Format(time.RFC3339Nano),
			"stale":           stale,
			"freshnessStatus": map[bool]string{true: "stale", false: "fresh"}[stale],
		}
	}
	var exception interface{}
	if len(exc) > 0 && string(exc) != "null" {
		var m map[string]interface{}
		if json.Unmarshal(exc, &m) == nil && m != nil {
			exception = m
		}
	}
	tl := app.loadTimelineAny(contextBG(), id, requestID)
	if journey != nil {
		tl = append(tl, app.loadTimeline(contextBG(), "journey", *journey)...)
	}
	out := map[string]interface{}{
		"sampleId":     id,
		"requestId":    requestID,
		"requesterId":  requesterID,
		"sampleTypeId": typeID,
		"status":       status,
		"sealed":       sealed,
		"serviceability": svc,
		"handling": map[string]interface{}{
			"containerType":           container,
			"temperatureMinC":         tmin,
			"temperatureMaxC":         tmax,
			"incompatibleSampleTypes": incompat,
		},
		"origin":           Coord{olat, olng},
		"originType":       otype,
		"requestedAt":      requested.UTC().Format(time.RFC3339Nano),
		"deliveryDeadline": deadline.UTC().Format(time.RFC3339Nano),
		"collectionWindow": map[string]string{
			"earliest": earliest.UTC().Format(time.RFC3339Nano),
			"latest":   latest.UTC().Format(time.RFC3339Nano),
		},
		"timeline": tl,
	}
	if holder != nil {
		out["currentHolderId"] = *holder
	}
	if journey != nil {
		out["activeJourneyId"] = *journey
	}
	if target != nil {
		out["targetLaboratoryId"] = *target
	}
	if received != nil {
		out["receivedLaboratoryId"] = *received
	}
	if loc != nil {
		out["latestLocation"] = loc
	}
	if exception != nil {
		out["exception"] = exception
	}
	if reason != "" && svc != "serviceable" {
		out["serviceabilityReason"] = reason
	}
	return out, nil
}

func (app *App) handleReadRequest(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("requestId")
