func (app *App) handleSearchAudit(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if !u.isDispatcher() {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		Query      string  `json:"query"`
		ActorID    string  `json:"actorId"`
		EntityType string  `json:"entityType"`
		EntityID   string  `json:"entityId"`
		Action     string  `json:"action"`
		Role       string  `json:"role"`
		Success    *bool   `json:"success"`
		FromTime   string  `json:"fromTime"`
		ToTime     string  `json:"toTime"`
		Limit      int     `json:"limit"`
		Offset     int     `json:"offset"`
		Order      string  `json:"order"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	q := queryAudit{
		Query: req.Query, ActorID: req.ActorID, EntityType: req.EntityType, EntityID: req.EntityID,
		Action: req.Action, Role: req.Role, Success: req.Success, Limit: req.Limit, Offset: req.Offset, Order: req.Order,
	}
	if req.FromTime != "" {
		t, err := parseTime(req.FromTime)
		if err == nil {
			q.FromTime = &t
		}
	}
	if req.ToTime != "" {
		t, err := parseTime(req.ToTime)
		if err == nil {
			q.ToTime = &t
		}
	}
	res, err := app.searchAudit(r.Context(), q)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	writeData(w, 200, res)
}
"}

