		items = app.listWorkerWork(u, scope)
	case RoleDispatcher, RoleAdministrator:
		items = app.listDispatcherWork(u, scope)
	}
	if items == nil {
		items = []map[string]interface{}{}
	}
	writeData(w, 200, map[string]interface{}{
		"role":  u.ActiveRole,
		"scope": scope,
		"items": items,
