func (app *App) listRequesterWork(u *SessionUser, scope string) []map[string]interface{} {
	q := `SELECT id, request_id, status, sample_type_id, delivery_deadline FROM samples WHERE requester_id=$1`
	if scope == "past" {
		q += ` AND status IN ('received','cancelled')`
	} else {
		q += ` AND status NOT IN ('received','cancelled')`
	}
	q += ` ORDER BY requested_at DESC`
	rows, err := app.store.pg.Query(contextBG(), q, u.UserID)
	if err != nil {
		return []map[string]interface{}{}
	}
	defer rows.Close()
	out := []map[string]interface{}{}
	for rows.Next() {
		var sid, rid, status, stid string
		var dl time.Time
		if err := rows.Scan(&sid, &rid, &status, &stid, &dl); err != nil {
			continue
		}
		out = append(out, map[string]interface{}{
			"kind":             "request",
			"sampleId":         sid,
			"requestId":        rid,
			"status":           status,
			"sampleTypeId":     stid,
			"deliveryDeadline": dl.UTC().Format(time.RFC3339Nano),
		})
	}
	return out
}

func (app *App) listWorkerWork(u *SessionUser, scope string) []map[string]interface{} {
	q := `
SELECT id, journey_id, sample_id, kind, status, from_location_id, to_location_id, node_id, laboratory_id, offer_expires_at
FROM assignments
WHERE (worker_id=$1 OR offered_to=$1)`
	if scope == "past" {
		q += ` AND status IN ('completed','cancelled','declined')`
	} else {
		q += ` AND status IN ('offered','accepted','in_progress','handoff_pending')`
	}
	q += ` ORDER BY created_at DESC`
	rows, err := app.store.pg.Query(contextBG(), q, u.UserID)
	if err != nil {
		return []map[string]interface{}{}
	}
	defer rows.Close()
	out := []map[string]interface{}{}
	for rows.Next() {
		var id, jid, kind, status string
		var sid, from, to, node, lab *string
		var exp *time.Time
		if err := rows.Scan(&id, &jid, &sid, &kind, &status, &from, &to, &node, &lab, &exp); err != nil {
			continue
		}
		item := map[string]interface{}{
			"kind":         "assignment",
			"assignmentId": id,
			"journeyId":    jid,
			"assignmentKind": kind,
			"status":       status,
		}
		if sid != nil {
			item["sampleId"] = *sid
		}
		if from != nil {
			item["fromLocationId"] = *from
		}
		if to != nil {
			item["toLocationId"] = *to
		}
		if node != nil {
			item["nodeId"] = *node
		}
		if lab != nil {
			item["laboratoryId"] = *lab
		}
		if exp != nil {
			item["offerExpiresAt"] = exp.UTC().Format(time.RFC3339Nano)
		}
		out = append(out, item)
	}
	return out
}

func (app *App) listDispatcherWork(u *SessionUser, scope string) []map[string]interface{} {
	q := `SELECT id, request_id, status, sample_type_id, delivery_deadline FROM samples`
	if scope == "past" {
		q += ` WHERE status IN ('received','cancelled')`
	} else {
		q += ` WHERE status NOT IN ('received','cancelled')`
	}
	q += ` ORDER BY requested_at DESC LIMIT 200`
	rows, err := app.store.pg.Query(contextBG(), q)
	if err != nil {
		return []map[string]interface{}{}
	}
	defer rows.Close()
	out := []map[string]interface{}{}
	for rows.Next() {
		var sid, rid, status, stid string
		var dl time.Time
		if err := rows.Scan(&sid, &rid, &status, &stid, &dl); err != nil {
			continue
		}
		out = append(out, map[string]interface{}{
			"kind": "sample", "sampleId": sid, "requestId": rid, "status": status,
			"sampleTypeId": stid, "deliveryDeadline": dl.UTC().Format(time.RFC3339Nano),
		})
	}
	return out
}

func (app *App) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
