func (app *App) handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	var req struct {
		AssignmentID string `json:"assignmentId"`
		Reason       string `json:"reason"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	var offered *string
	var status string
	err := app.store.pg.QueryRow(r.Context(), `SELECT offered_to, status FROM assignments WHERE id=$1`, req.AssignmentID).
		Scan(&offered, &status)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if status != "offered" {
		writeErr(w, 409, "invalid_state", "assignment is not offered")
		return
	}
	if offered == nil || *offered != u.UserID {
		writeErr(w, 403, "not_offered_to_you", "assignment was not offered to you")
		return
	}
	_, err = app.store.pg.Exec(r.Context(), `
UPDATE assignments SET status='declined', declined_by=$2, declined_at=NOW() WHERE id=$1`, req.AssignmentID, u.UserID)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	var dc int
	_ = app.store.pg.QueryRow(r.Context(), `SELECT decline_count FROM users WHERE id=$1`, u.UserID).Scan(&dc)
	dc++
	var until interface{}
	if dc >= 3 {
		until = time.Now().Add(declinePenalty)
		dc = 0
	}
	_, _ = app.store.pg.Exec(r.Context(), `UPDATE users SET decline_count=$2, decline_penalty_until=$3 WHERE id=$1`, u.UserID, dc, until)
	app.audit(r.Context(), u.UserID, u.ActiveRole, "assignment.decline", "assignment", req.AssignmentID, true, map[string]interface{}{"reason": req.Reason})
	app.reoffer(r.Context(), req.AssignmentID)
	writeData(w, 200, map[string]interface{}{
		"assignmentId": req.AssignmentID,
		"status":       "declined",
	})
}

func (app *App) handleRecordCollection(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u.ActiveRole != RoleCollectionProfessional && u.ActiveRole != RoleAdministrator {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		AssignmentID string `json:"assignmentId"`
		CollectedAt  string `json:"collectedAt"`
		Latitude     float64 `json:"latitude"`
		Longitude    float64 `json:"longitude"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	var worker, sampleID *string
	var status, kind string
	var earliest, latest time.Time
	err := app.store.pg.QueryRow(r.Context(), `
SELECT a.worker_id, a.status, a.kind, a.sample_id, s.earliest_collection_at, s.latest_collection_at
FROM assignments a JOIN samples s ON s.id=a.sample_id WHERE a.id=$1`, req.AssignmentID).
		Scan(&worker, &status, &kind, &sampleID, &earliest, &latest)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if kind != "collection" {
		writeErr(w, 409, "invalid_assignment_kind", "not a collection assignment")
		return
	}
	if status != "accepted" && status != "in_progress" {
		writeErr(w, 409, "invalid_state", "assignment not accepted")
		return
	}
	if worker == nil || *worker != u.UserID {
		writeErr(w, 403, "forbidden", "not your assignment")
		return
	}
	collectedAt, err := parseTime(req.CollectedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid collectedAt")
		return
	}
	if collectedAt.Before(earliest) || collectedAt.After(latest) {
		writeErr(w, 409, "outside_collection_window", "collection outside window")
		return
	}
	// qualification check
	var stID string
	_ = app.store.pg.QueryRow(r.Context(), `SELECT sample_type_id FROM samples WHERE id=$1`, *sampleID).Scan(&stID)
	st, _ := app.loadSampleType(r.Context(), stID)
	if st != nil && st.QualifiedRequired && !contains(u.Qualifications, st.RequiredQualification) && !hasActiveCert(u.Certifications, st.RequiredQualification) {
		writeErr(w, 403, "missing_qualification", "missing qualification")
		return
	}
	_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET status='in_progress' WHERE id=$1`, req.AssignmentID)
	_, _ = app.store.pg.Exec(r.Context(), `
UPDATE samples SET status='collected', latest_lat=$2, latest_lng=$3, location_recorded_at=$4, current_holder_id=$5
WHERE id=$1`, *sampleID, req.Latitude, req.Longitude, collectedAt, u.UserID)
	app.audit(r.Context(), u.UserID, u.ActiveRole, "sample.collect", "sample", *sampleID, true, nil)
	app.emit("sample.collected", "sample", *sampleID, map[string]interface{}{"assignmentId": req.AssignmentID})
	writeData(w, 200, map[string]interface{}{
		"assignmentId": req.AssignmentID,
		"sampleId":     *sampleID,
		"status":       "collected",
		"collectedAt":  collectedAt.UTC().Format(time.RFC3339Nano),
	})
}

func contains(xs []string, v string) bool {
	for _, x := range xs {
		if x == v {
			return true
		}
	}
	return false
}

func hasActiveCert(cs []Certification, code string) bool {
	now := time.Now()
	for _, c := range cs {
		if c.Code == code && c.Active && (c.ExpiresAt == nil || c.ExpiresAt.After(now)) {
			return true
		}
	}
	return false
}

