func (app *App) handleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	var req struct {
		SampleID              string  `json:"sampleId"`
		AssignmentID          string  `json:"assignmentId"`
		LocationID            string  `json:"locationId"`
		ContainerType         string  `json:"containerType"`
		ObservedTemperatureC  float64 `json:"observedTemperatureC"`
		RecordedAt            string  `json:"recordedAt"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	var holder *string
	var tmin, tmax float64
	var reqContainer, status string
	err := app.store.pg.QueryRow(r.Context(), `
SELECT current_holder_id, temperature_min_c, temperature_max_c, container_type, status FROM samples WHERE id=$1`, req.SampleID).
		Scan(&holder, &tmin, &tmax, &reqContainer, &status)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if holder == nil || *holder != u.UserID {
		writeErr(w, 403, "not_current_holder", "not current holder")
		return
	}
	at, err := parseTime(req.RecordedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid recordedAt")
		return
	}
	compliant := req.ObservedTemperatureC >= tmin && req.ObservedTemperatureC <= tmax
	if req.ContainerType != "" && reqContainer != "" && req.ContainerType != reqContainer {
		compliant = false
	}
	id := newUUID()
	var loc interface{}
	if req.LocationID != "" {
		loc = req.LocationID
	}
	_, err = app.store.pg.Exec(r.Context(), `
INSERT INTO checkpoints (id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, recorded_at, compliant)
VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
		id, req.SampleID, req.AssignmentID, loc, req.ContainerType, req.ObservedTemperatureC, at, compliant)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	if !compliant {
		exc := map[string]interface{}{
			"reason": "handling_violation", "containerType": req.ContainerType,
			"observedTemperatureC": req.ObservedTemperatureC, "checkpointId": id,
		}
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET status='exception', exception=$2 WHERE id=$1 AND status NOT IN ('received','cancelled')`, req.SampleID, asJSON(exc))
		app.audit(r.Context(), u.UserID, u.ActiveRole, "sample.handling_exception", "sample", req.SampleID, true, exc)
		app.emit("sample.exception", "sample", req.SampleID, exc)
	} else {
		app.audit(r.Context(), u.UserID, u.ActiveRole, "sample.checkpoint", "sample", req.SampleID, true, map[string]interface{}{"checkpointId": id})
	}
	writeData(w, 200, map[string]interface{}{
		"checkpointId": id,
		"sampleId":     req.SampleID,
		"compliant":    compliant,
		"recordedAt":   at.UTC().Format(time.RFC3339Nano),
	})
}

