func (app *App) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	var req struct {
		HandoffID string `json:"handoffId"`
		Role      string `json:"role"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	var sampleID, sender, receiver, status, fromA, toA string
	var sConf, rConf bool
	err := app.store.pg.QueryRow(r.Context(), `
SELECT sample_id, sender_id, receiver_id, status, sender_confirmed, receiver_confirmed, from_assignment_id, to_assignment_id
FROM handoffs WHERE id=$1`, req.HandoffID).Scan(&sampleID, &sender, &receiver, &status, &sConf, &rConf, &fromA, &toA)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if status == "completed" {
		writeData(w, 200, map[string]interface{}{"handoffId": req.HandoffID, "status": "completed", "sampleId": sampleID})
		return
	}
	if req.Role == "sender" {
		if u.UserID != sender {
			writeErr(w, 403, "forbidden", "not the sender")
			return
		}
		sConf = true
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE handoffs SET sender_confirmed=TRUE WHERE id=$1`, req.HandoffID)
	} else if req.Role == "receiver" {
		if u.UserID != receiver {
			writeErr(w, 403, "forbidden", "not the receiver")
			return
		}
		rConf = true
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE handoffs SET receiver_confirmed=TRUE WHERE id=$1`, req.HandoffID)
	} else {
		writeErr(w, 400, "invalid_role", "role must be sender or receiver")
		return
	}
	outStatus := "pending"
	if sConf && rConf {
		now := time.Now().UTC()
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE handoffs SET status='completed', completed_at=$2 WHERE id=$1`, req.HandoffID, now)
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET current_holder_id=$2, status='in_transit' WHERE id=$1 AND status NOT IN ('received','cancelled')`, sampleID, receiver)
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET status='completed', completed_at=$2 WHERE id=$1`, fromA, now)
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET status='in_progress' WHERE id=$1 AND status IN ('accepted','offered')`, toA)
		outStatus = "completed"
		app.audit(r.Context(), u.UserID, u.ActiveRole, "handoff.complete", "handoff", req.HandoffID, true, map[string]interface{}{"sampleId": sampleID, "newHolder": receiver})
		app.emit("handoff.completed", "handoff", req.HandoffID, map[string]interface{}{"sampleId": sampleID, "holderId": receiver})
	} else {
		app.audit(r.Context(), u.UserID, u.ActiveRole, "handoff.confirm", "handoff", req.HandoffID, true, map[string]interface{}{"role": req.Role})
	}
	writeData(w, 200, map[string]interface{}{
		"handoffId": req.HandoffID,
		"status":    outStatus,
		"sampleId":  sampleID,
	})
}

