		return
	}
	if kind != "laboratory" {
		writeErr(w, 409, "invalid_assignment_kind", "not a laboratory assignment")
		return
	}
	if worker == nil || *worker != u.UserID {
		writeErr(w, 403, "forbidden", "not your assignment")
		return
	}
	if sampleID != nil && req.SampleID != "" && *sampleID != req.SampleID {
		writeErr(w, 400, "sample_mismatch", "sample mismatch")
		return
	}
	sid := req.SampleID
	if sid == "" && sampleID != nil {
		sid = *sampleID
	}
	at, err := parseTime(req.ReceivedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid receivedAt")
		return
	}
	var deadline time.Time
	_ = app.store.pg.QueryRow(r.Context(), `SELECT delivery_deadline FROM samples WHERE id=$1`, sid).Scan(&deadline)
	newStatus := "received"
	if at.After(deadline) {
		exc := map[string]interface{}{"reason": "missed_deadline", "receivedAt": at.UTC().Format(time.RFC3339Nano)}
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET status='exception', exception=$2, received_laboratory_id=$3 WHERE id=$1`, sid, asJSON(exc), labID)
		newStatus = "exception"
	} else {
		_, _ = app.store.pg.Exec(r.Context(), `
UPDATE samples SET status='received', received_laboratory_id=$2, current_holder_id=$3 WHERE id=$1`, sid, labID, u.UserID)
	}
	_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET status='completed', completed_at=$2 WHERE id=$1`, req.AssignmentID, at)
	if jid := ""; true {
		_ = app.store.pg.QueryRow(r.Context(), `SELECT active_journey_id FROM samples WHERE id=$1`, sid).Scan(&jid)
		if jid != "" {
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE journeys SET status='completed' WHERE id=$1`, jid)
			_ = app.releaseJourneyCapacity(r.Context(), jid)
		}
	}
	app.audit(r.Context(), u.UserID, u.ActiveRole, "sample.receive", "sample", sid, true, map[string]interface{}{"status": newStatus})
	app.emit("sample.received", "sample", sid, map[string]interface{}{"status": newStatus})
	writeData(w, 200, map[string]interface{}{
		"assignmentId": req.AssignmentID,
		"sampleId":     sid,
		"status":       newStatus,
		"receivedAt":   at.UTC().Format(time.RFC3339Nano),
	})
}

func (app *App) handleRecordLaboratoryException(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u.ActiveRole != RoleLaboratoryTeam && u.ActiveRole != RoleAdministrator {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		AssignmentID string `json:"assignmentId"`
		SampleID     string `json:"sampleId"`
		Reason       string `json:"reason"`
		ObservedAt   string `json:"observedAt"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.Reason == "" {
		writeErr(w, 400, "invalid_reason", "reason required")
		return
	}
	at, err := parseTime(req.ObservedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid observedAt")
		return
	}
	var labID *string
	_ = app.store.pg.QueryRow(r.Context(), `SELECT laboratory_id FROM assignments WHERE id=$1`, req.AssignmentID).Scan(&labID)
	id := newUUID()
	_, err = app.store.pg.Exec(r.Context(), `
INSERT INTO exceptions (id, sample_id, laboratory_id, reason, observed_at) VALUES ($1,$2,$3,$4,$5)`,
		id, req.SampleID, labID, req.Reason, at)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	exc := map[string]interface{}{"reason": req.Reason, "exceptionId": id, "assignmentId": req.AssignmentID}
	_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET status='exception', exception=$2 WHERE id=$1`, req.SampleID, asJSON(exc))
	app.audit(r.Context(), u.UserID, u.ActiveRole, "sample.lab_exception", "sample", req.SampleID, true, exc)
	app.emit("sample.exception", "sample", req.SampleID, exc)
	writeData(w, 200, map[string]interface{}{
		"exceptionId": id,
		"sampleId":    req.SampleID,
		"reason":      req.Reason,
		"observedAt":  at.UTC().Format(time.RFC3339Nano),
	})
}
"}

