{"path":"/workspace/backend/http.go","command":"create","file_text":"package main

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"log"
	"net/http"
	"strings"
	"time"
)

type ctxKey int

const ctxUser ctxKey = iota

type SessionUser struct {
	UserID             string
	Username           string
	FullName           string
	Email              string
	Phone              string
	Roles              []string
	ActiveRole         string
	AssignedLocationID string
	Available          bool
	CapacityUnits      int
	Active             bool
	Qualifications     []string
	Certifications     []Certification
}

func (u SessionUser) hasRole(r string) bool {
	for _, x := range u.Roles {
		if x == r {
			return true
		}
	}
	return false
}

func (u SessionUser) isDispatcher() bool {
	return u.ActiveRole == RoleDispatcher || u.ActiveRole == RoleAdministrator
}

func writeJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	enc := json.NewEncoder(w)
	enc.SetEscapeHTML(false)
	_ = enc.Encode(v)
}

func writeData(w http.ResponseWriter, status int, data interface{}) {
	writeJSON(w, status, map[string]interface{}{"data": data})
}

func writeErr(w http.ResponseWriter, status int, code, msg string) {
	if msg == "" {
		msg = strings.ReplaceAll(code, "_", " ")
	}
	writeJSON(w, status, APIError{Error: msg, Code: code})
}

func parseTime(s string) (time.Time, error) {
	if s == "" {
		return time.Time{}, errors.New("empty time")
	}
	if t, err := time.Parse(time.RFC3339Nano, s); err == nil {
		return t, nil
	}
	if t, err := time.Parse(time.RFC3339, s); err == nil {
		return t, nil
	}
	return time.Time{}, errors.New("invalid time")
}

func rfc3339(t time.Time) string {
	if t.IsZero() {
		return ""
	}
	return t.UTC().Format(time.RFC3339)
}

func bearerToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if strings.HasPrefix(strings.ToLower(h), "bearer ") {
		return strings.TrimSpace(h[7:])
	}
	return ""
}

func currentUser(r *http.Request) *SessionUser {
	v, _ := r.Context().Value(ctxUser).(*SessionUser)
	return v
}

func readBody(r *http.Request) []byte {
	b, _ := io.ReadAll(r.Body)
	if b == nil {
		b = []byte{}
	}
	return b
}

func decodeBody(b []byte, dst interface{}) error {
	if len(bytesTrim(b)) == 0 {
		return json.Unmarshal([]byte("{}"), dst)
	}
	return json.Unmarshal(b, dst)
}

func bytesTrim(b []byte) []byte {
	return []byte(strings.TrimSpace(string(b)))
}

func idemKeyFrom(b []byte) string {
	var m map[string]interface{}
	if json.Unmarshal(b, &m) != nil {
		return ""
	}
	if k, ok := m["idempotencyKey"].(string); ok {
		return k
	}
	return ""
}

type httpErr struct {
	status int
	code   string
	msg    string
}

func (e *httpErr) Error() string { return e.code }

func herr(status int, code, msg string) *httpErr {
	if msg == "" {
		msg = strings.ReplaceAll(code, "_", " ")
	}
	return &httpErr{status: status, code: code, msg: msg}
}

func (app *App) handleErr(w http.ResponseWriter, err error) {
	if err == nil {
		return
	}
	if ae, ok := err.(*httpErr); ok {
		writeErr(w, ae.status, ae.code, ae.msg)
		return
	}
	log.Printf("internal: %v", err)
	writeErr(w, 500, "internal_error", "internal error")
}

func (app *App) requireAuth(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		tok := bearerToken(r)
		if tok == "" {
			writeErr(w, 401, "unauthorized", "unauthorized")
			return
		}
		u, err := app.loadSession(r.Context(), tok)
		if err != nil || u == nil {
			writeErr(w, 401, "unauthorized", "unauthorized")
			return
		}
		next(w, r.WithContext(context.WithValue(r.Context(), ctxUser, u)))
	}
}

func (app *App) requireRole(next http.HandlerFunc) http.HandlerFunc {
	return app.requireAuth(func(w http.ResponseWriter, r *http.Request) {
		u := currentUser(r)
		if u.ActiveRole == "" {
			writeErr(w, 409, "role_not_selected", "role not selected")
			return
		}
		next(w, r)
	})
}

func (app *App) requireAny(roles ...string) func(http.HandlerFunc) http.HandlerFunc {
	return func(next http.HandlerFunc) http.HandlerFunc {
		return app.requireRole(func(w http.ResponseWriter, r *http.Request) {
			u := currentUser(r)
			ok := false
			for _, role := range roles {
				if u.ActiveRole == role {
					ok = true
					break
				}
			}
			if !ok && u.ActiveRole == RoleAdministrator {
				for _, role := range roles {
					if role == RoleDispatcher || role == RoleAdministrator {
						ok = true
						break
					}
				}
			}
			if !ok {
				writeErr(w, 403, "forbidden", "forbidden")
				return
			}
			next(w, r)
		})
	}
}

func method(allowed string, h http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method == http.MethodOptions {
			w.WriteHeader(204)
			return
		}
		if r.Method != allowed {
			writeErr(w, 405, "method_not_allowed", "method not allowed")
			return
		}
		h(w, r)
	}
}

func (app *App) loadSession(ctx context.Context, token string) (*SessionUser, error) {
	var userID, activeRole string
	var expires time.Time
	err := app.store.pg.QueryRow(ctx, `SELECT user_id, active_role, expires_at FROM sessions WHERE token=$1`, token).
		Scan(&userID, &activeRole, &expires)
	if err != nil {
		return nil, err
	}
	if time.Now().After(expires) {
		return nil, errors.New("expired")
	}
	return app.loadUser(ctx, userID, activeRole)
}

func (app *App) loadUser(ctx context.Context, userID, activeRole string) (*SessionUser, error) {
	u := &SessionUser{UserID: userID, ActiveRole: activeRole}
	var assigned *string
	err := app.store.pg.QueryRow(ctx, `
SELECT username, COALESCE(full_name,''), COALESCE(email,''), COALESCE(phone,''), active,
  COALESCE(assigned_location_id::text,''), available, capacity_units
FROM users WHERE id=$1`, userID).Scan(&u.Username, &u.FullName, &u.Email, &u.Phone, &u.Active, &assigned, &u.Available, &u.CapacityUnits)
	if err != nil {
		return nil, err
	}
	if assigned != nil {
		u.AssignedLocationID = *assigned
	}
	rows, err := app.store.pg.Query(ctx, `SELECT role FROM user_roles WHERE user_id=$1 ORDER BY role`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var role string
		if err := rows.Scan(&role); err != nil {
			return nil, err
		}
		u.Roles = append(u.Roles, role)
	}
	qrows, err := app.store.pg.Query(ctx, `SELECT qualification FROM user_qualifications WHERE user_id=$1`, userID)
	if err != nil {
		return nil, err
	}
	defer qrows.Close()
	for qrows.Next() {
		var q string
		if err := qrows.Scan(&q); err != nil {
			return nil, err
		}
		u.Qualifications = append(u.Qualifications, q)
	}
	crows, err := app.store.pg.Query(ctx, `SELECT code, active, expires_at FROM certifications WHERE user_id=$1`, userID)
	if err != nil {
		return nil, err
	}
	defer crows.Close()
	for crows.Next() {
		var c Certification
		var exp *time.Time
		if err := crows.Scan(&c.Code, &c.Active, &exp); err != nil {
			return nil, err
		}
		c.ExpiresAt = exp
		u.Certifications = append(u.Certifications, c)
	}
	if u.Roles == nil {
		u.Roles = []string{}
	}
	if u.Qualifications == nil {
		u.Qualifications = []string{}
	}
	if u.Certifications == nil {
		u.Certifications = []Certification{}
	}
	return u, nil
}

func (app *App) withIdem(w http.ResponseWriter, r *http.Request, body []byte, required bool, fn func() (int, interface{}, error)) {
	u := currentUser(r)
	key := idemKeyFrom(body)
	if required && key == "" {
		writeErr(w, 400, "idempotency_required", "idempotency key required")
		return
	}
	if key != "" {
		var existingUser string
		var existingStatus int
		var existing []byte
		err := app.store.pg.QueryRow(r.Context(), `SELECT user_id::text, status_code, response FROM idempotency WHERE key=$1`, key).
			Scan(&existingUser, &existingStatus, &existing)
		if err == nil {
			if existingUser != u.UserID {
				writeErr(w, 409, "idempotency_conflict", "idempotency conflict")
				return
			}
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(existingStatus)
			_, _ = w.Write(existing)
			return
		}
	}
	status, payload, herr := fn()
	if herr != nil {
		app.handleErr(w, herr)
		return
	}
	bodyOut, _ := json.Marshal(map[string]interface{}{"data": payload})
	if key != "" {
		_, _ = app.store.pg.Exec(r.Context(), `
INSERT INTO idempotency (key, user_id, request_hash, status_code, response)
VALUES ($1,$2,'', $3, $4) ON CONFLICT (key) DO NOTHING`, key, u.UserID, status, bodyOut)
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_, _ = w.Write(bodyOut)
}

func cors(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type, Sec-WebSocket-Protocol")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, PATCH, DELETE, OPTIONS")
		if r.Method == http.MethodOptions {
			w.WriteHeader(204)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func contains(xs []string, v string) bool {
	for _, x := range xs {
		if x == v {
			return true
		}
	}
	return false
}

func hasActiveCert(cs []Certification, code string) bool {
	now := time.Now()
	for _, c := range cs {
		if c.Code == code && c.Active && (c.ExpiresAt == nil || c.ExpiresAt.After(now)) {
			return true
		}
	}
	return false
}

func strPtr(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}
"}

{"path":"/workspace/backend/models.go","command":"create","file_text":"package main

import (
	"encoding/json"
	"math"
	"time"

	"github.com/jackc/pgx/v5/pgtype"
)

const (
	RoleAdministrator          = "administrator"
	RoleDispatcher             = "dispatcher"
	RoleRequester              = "requester"
	RoleCollectionProfessional = "collection_professional"
	RoleDeliveryPartner        = "delivery_partner"
	RoleNodeHandler            = "node_handler"
	RoleLaboratoryTeam         = "laboratory_team"
)

var allRoles = []string{
	RoleAdministrator, RoleDispatcher, RoleRequester,
	RoleCollectionProfessional, RoleDeliveryPartner,
	RoleNodeHandler, RoleLaboratoryTeam,
}

func validRole(r string) bool {
	for _, x := range allRoles {
		if x == r {
			return true
		}
	}
	return false
}

const (
	FnCollection = "collection_point"
	FnTransfer   = "transfer_point"
	FnHub        = "hub"
	FnLaboratory = "laboratory"
)

var allFunctions = []string{FnCollection, FnTransfer, FnHub, FnLaboratory}

func validFunction(f string) bool {
	for _, x := range allFunctions {
		if x == f {
			return true
		}
	}
	return false
}

const staleAfter = 5 * time.Minute
const offerTTL = 2 * time.Minute
const declinePenalty = 15 * time.Minute
const offerScanInterval = 15 * time.Second

type APIError struct {
	Error string `json:"error"`
	Code  string `json:"code"`
}

type Coord struct {
	Latitude  float64 `json:"latitude"`
	Longitude float64 `json:"longitude"`
}

type Certification struct {
	Code      string     `json:"code"`
	Active    bool       `json:"active"`
	ExpiresAt *time.Time `json:"expiresAt,omitempty"`
}

type LocationFunctions struct {
	CollectionPoint bool `json:"collection_point"`
	TransferPoint   bool `json:"transfer_point"`
	Hub             bool `json:"hub"`
	Laboratory      bool `json:"laboratory"`
}

func functionsFromList(fns []string) LocationFunctions {
	var f LocationFunctions
	for _, x := range fns {
		switch x {
		case FnCollection:
			f.CollectionPoint = true
		case FnTransfer:
			f.TransferPoint = true
		case FnHub:
			f.Hub = true
		case FnLaboratory:
			f.Laboratory = true
		}
	}
	return f
}

func (f LocationFunctions) list() []string {
	out := []string{}
	if f.CollectionPoint {
		out = append(out, FnCollection)
	}
	if f.TransferPoint {
		out = append(out, FnTransfer)
	}
	if f.Hub {
		out = append(out, FnHub)
	}
	if f.Laboratory {
		out = append(out, FnLaboratory)
	}
	return out
}

type Capacity struct {
	CapacityUnits        int `json:"capacityUnits"`
	ReservedUnits        int `json:"reservedUnits"`
	AvailableUnits       int `json:"availableUnits"`
	CooledCapacityUnits  int `json:"cooledCapacityUnits"`
	CooledReservedUnits  int `json:"cooledReservedUnits"`
	CooledAvailableUnits int `json:"cooledAvailableUnits"`
}

func (c Capacity) fill() Capacity {
	c.AvailableUnits = c.CapacityUnits - c.ReservedUnits
	c.CooledAvailableUnits = c.CooledCapacityUnits - c.CooledReservedUnits
	if c.AvailableUnits < 0 {
		c.AvailableUnits = 0
	}
	if c.CooledAvailableUnits < 0 {
		c.CooledAvailableUnits = 0
	}
	return c
}

type TimelineEntry struct {
	EventID    int64                  `json:"eventId"`
	Action     string                 `json:"action"`
	ActorID    string                 `json:"actorId"`
	Role       string                 `json:"role"`
	EntityType string                 `json:"entityType"`
	EntityID   string                 `json:"entityId"`
	Success    bool                   `json:"success"`
	OccurredAt time.Time              `json:"occurredAt"`
	Details    map[string]interface{} `json:"details"`
}

func uuidStr(u pgtype.UUID) string {
	if !u.Valid {
		return ""
	}
	b, _ := u.Value()
	if s, ok := b.(string); ok {
		return s
	}
	if bts, ok := b.([16]byte); ok {
		return formatUUID(bts)
	}
	return ""
}

func formatUUID(b [16]byte) string {
	const hex = "0123456789abcdef"
	buf := make([]byte, 36)
	j := 0
	for i, v := range b {
		if i == 4 || i == 6 || i == 8 || i == 10 {
			buf[j] = '-'
			j++
		}
		buf[j] = hex[v>>4]
		buf[j+1] = hex[v&0x0f]
		j += 2
	}
	return string(buf)
}

func asJSON(v interface{}) []byte {
	if v == nil {
		return []byte("null")
	}
	b, _ := json.Marshal(v)
	return b
}

func isStale(t *time.Time, now time.Time) bool {
	if t == nil || t.IsZero() {
		return true
	}
	return now.Sub(*t) > staleAfter
}

func haversineKm(lat1, lng1, lat2, lng2 float64) float64 {
	const R = 6371.0
	p1 := lat1 * math.Pi / 180
	p2 := lat2 * math.Pi / 180
	dphi := (lat2 - lat1) * math.Pi / 180
	dl := (lng2 - lng1) * math.Pi / 180
	a := math.Sin(dphi/2)*math.Sin(dphi/2) + math.Cos(p1)*math.Cos(p2)*math.Sin(dl/2)*math.Sin(dl/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return R * c
}

func nilIfEmpty(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}
"}

{"path":"/workspace/backend/http.go","command":"create","file_text":"package main

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"log"
	"net/http"
	"strings"
	"time"
)

type ctxKey int

const ctxUser ctxKey = iota

type SessionUser struct {
	UserID             string
	Username           string
	FullName           string
	Email              string
	Phone              string
	Roles              []string
	ActiveRole         string
	AssignedLocationID string
	Available          bool
	CapacityUnits      int
	Active             bool
	Qualifications     []string
	Certifications     []Certification
}

func (u SessionUser) hasRole(r string) bool {
	for _, x := range u.Roles {
		if x == r {
			return true
		}
	}
	return false
}

func (u SessionUser) isDispatcher() bool {
	return u.ActiveRole == RoleDispatcher || u.ActiveRole == RoleAdministrator
}

func writeJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	enc := json.NewEncoder(w)
	enc.SetEscapeHTML(false)
	_ = enc.Encode(v)
}

func writeData(w http.ResponseWriter, status int, data interface{}) {
	writeJSON(w, status, map[string]interface{}{"data": data})
}

func writeErr(w http.ResponseWriter, status int, code, msg string) {
	if msg == "" {
		msg = strings.ReplaceAll(code, "_", " ")
	}
	writeJSON(w, status, APIError{Error: msg, Code: code})
}

func parseTime(s string) (time.Time, error) {
	if s == "" {
		return time.Time{}, errors.New("empty time")
	}
	if t, err := time.Parse(time.RFC3339Nano, s); err == nil {
		return t, nil
	}
	if t, err := time.Parse(time.RFC3339, s); err == nil {
		return t, nil
	}
	return time.Time{}, errors.New("invalid time")
}

func rfc3339(t time.Time) string {
	return t.UTC().Format(time.RFC3339)
}

func bearerToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if strings.HasPrefix(strings.ToLower(h), "bearer ") {
		return strings.TrimSpace(h[7:])
	}
	return ""
}

func currentUser(r *http.Request) *SessionUser {
	v, _ := r.Context().Value(ctxUser).(*SessionUser)
	return v
}

func readBody(r *http.Request) []byte {
	b, _ := io.ReadAll(r.Body)
	if b == nil {
		return []byte{}
	}
	return b
}

func decodeBody(b []byte, dst interface{}) error {
	if len(strings.TrimSpace(string(b))) == 0 {
		return json.Unmarshal([]byte("{}"), dst)
	}
	return json.Unmarshal(b, dst)
}

func idemKeyFrom(b []byte) string {
	var m map[string]interface{}
	if json.Unmarshal(b, &m) != nil {
		return ""
	}
	if k, ok := m["idempotencyKey"].(string); ok {
		return k
	}
	return ""
}

type httpErr struct {
	status int
	code   string
	msg    string
}

func (e *httpErr) Error() string { return e.code }

func herr(status int, code, msg string) *httpErr {
	if msg == "" {
		msg = strings.ReplaceAll(code, "_", " ")
	}
	return &httpErr{status: status, code: code, msg: msg}
}

func (app *App) handleErr(w http.ResponseWriter, err error) {
	if err == nil {
		return
	}
	if ae, ok := err.(*httpErr); ok {
		writeErr(w, ae.status, ae.code, ae.msg)
		return
	}
	log.Printf("internal: %v", err)
	writeErr(w, 500, "internal_error", "internal error")
}

func (app *App) requireAuth(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		tok := bearerToken(r)
		if tok == "" {
			writeErr(w, 401, "unauthorized", "unauthorized")
			return
		}
		u, err := app.loadSession(r.Context(), tok)
		if err != nil || u == nil {
			writeErr(w, 401, "unauthorized", "unauthorized")
			return
		}
		next(w, r.WithContext(context.WithValue(r.Context(), ctxUser, u)))
	}
}

func (app *App) requireRole(next http.HandlerFunc) http.HandlerFunc {
	return app.requireAuth(func(w http.ResponseWriter, r *http.Request) {
		u := currentUser(r)
		if u.ActiveRole == "" {
			writeErr(w, 409, "role_not_selected", "role not selected")
			return
		}
		next(w, r)
	})
}

func (app *App) requireAny(roles ...string) func(http.HandlerFunc) http.HandlerFunc {
	return func(next http.HandlerFunc) http.HandlerFunc {
		return app.requireRole(func(w http.ResponseWriter, r *http.Request) {
			u := currentUser(r)
			ok := false
			for _, role := range roles {
				if u.ActiveRole == role {
					ok = true
					break
				}
			}
			if !ok && u.ActiveRole == RoleAdministrator {
				for _, role := range roles {
					if role == RoleDispatcher || role == RoleAdministrator {
						ok = true
						break
					}
				}
			}
			if !ok {
				writeErr(w, 403, "forbidden", "forbidden")
				return
			}
			next(w, r)
		})
	}
}

func method(allowed string, h http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method == http.MethodOptions {
			w.WriteHeader(204)
			return
		}
		if r.Method != allowed {
			writeErr(w, 405, "method_not_allowed", "method not allowed")
			return
		}
		h(w, r)
	}
}

func (app *App) loadSession(ctx context.Context, token string) (*SessionUser, error) {
	var userID, activeRole string
	var expires time.Time
	err := app.store.pg.QueryRow(ctx, `SELECT user_id, active_role, expires_at FROM sessions WHERE token=$1`, token).
		Scan(&userID, &activeRole, &expires)
	if err != nil {
		return nil, err
	}
	if time.Now().After(expires) {
		return nil, errors.New("expired")
	}
	return app.loadUser(ctx, userID, activeRole)
}

func (app *App) loadUser(ctx context.Context, userID, activeRole string) (*SessionUser, error) {
	u := &SessionUser{UserID: userID, ActiveRole: activeRole}
	var assigned *string
	err := app.store.pg.QueryRow(ctx, `
SELECT username, COALESCE(full_name,''), COALESCE(email,''), COALESCE(phone,''), active,
  COALESCE(assigned_location_id::text,''), available, capacity_units
FROM users WHERE id=$1`, userID).Scan(&u.Username, &u.FullName, &u.Email, &u.Phone, &u.Active, &assigned, &u.Available, &u.CapacityUnits)
	if err != nil {
		return nil, err
	}
	if assigned != nil {
		u.AssignedLocationID = *assigned
	}
	rows, err := app.store.pg.Query(ctx, `SELECT role FROM user_roles WHERE user_id=$1 ORDER BY role`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var role string
		if err := rows.Scan(&role); err != nil {
			return nil, err
		}
		u.Roles = append(u.Roles, role)
	}
	qrows, err := app.store.pg.Query(ctx, `SELECT qualification FROM user_qualifications WHERE user_id=$1`, userID)
	if err != nil {
		return nil, err
	}
	defer qrows.Close()
	for qrows.Next() {
		var q string
		if err := qrows.Scan(&q); err != nil {
			return nil, err
		}
		u.Qualifications = append(u.Qualifications, q)
	}
	crows, err := app.store.pg.Query(ctx, `SELECT code, active, expires_at FROM certifications WHERE user_id=$1`, userID)
	if err != nil {
		return nil, err
	}
	defer crows.Close()
	for crows.Next() {
		var c Certification
		var exp *time.Time
		if err := crows.Scan(&c.Code, &c.Active, &exp); err != nil {
			return nil, err
		}
		c.ExpiresAt = exp
		u.Certifications = append(u.Certifications, c)
	}
	if u.Roles == nil {
		u.Roles = []string{}
	}
	if u.Qualifications == nil {
		u.Qualifications = []string{}
	}
	if u.Certifications == nil {
		u.Certifications = []Certification{}
	}
	return u, nil
}

func (app *App) withIdem(w http.ResponseWriter, r *http.Request, body []byte, required bool, fn func() (int, interface{}, error)) {
	u := currentUser(r)
	key := idemKeyFrom(body)
	if required && key == "" {
		writeErr(w, 400, "idempotency_required", "idempotency key required")
		return
	}
	if key != "" {
		var existingUser string
		var existingStatus int
		var existing []byte
		err := app.store.pg.QueryRow(r.Context(), `SELECT user_id::text, status_code, response FROM idempotency WHERE key=$1`, key).
			Scan(&existingUser, &existingStatus, &existing)
		if err == nil {
			if existingUser != u.UserID {
				writeErr(w, 409, "idempotency_conflict", "idempotency conflict")
				return
			}
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(existingStatus)
			_, _ = w.Write(existing)
			return
		}
	}
	status, payload, e := fn()
	if e != nil {
		app.handleErr(w, e)
		return
	}
	bodyOut, _ := json.Marshal(map[string]interface{}{"data": payload})
	if key != "" {
		_, _ = app.store.pg.Exec(r.Context(), `
INSERT INTO idempotency (key, user_id, request_hash, status_code, response)
VALUES ($1,$2,'', $3, $4) ON CONFLICT (key) DO NOTHING`, key, u.UserID, status, bodyOut)
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_, _ = w.Write(bodyOut)
}

func cors(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type, Sec-WebSocket-Protocol")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, PATCH, DELETE, OPTIONS")
		if r.Method == http.MethodOptions {
			w.WriteHeader(204)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func contains(xs []string, v string) bool {
	for _, x := range xs {
		if x == v {
			return true
		}
	}
	return false
}

func hasActiveCert(cs []Certification, code string) bool {
	now := time.Now()
	for _, c := range cs {
		if c.Code == code && c.Active && (c.ExpiresAt == nil || c.ExpiresAt.After(now)) {
			return true
		}
	}
	return false
}
"}

{"path":"/workspace/backend/audit.go","command":"create","file_text":"package main

import (
	"context"
	"encoding/json"
	"log"
	"strings"
	"time"

	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo/options"
)

func (app *App) audit(ctx context.Context, actorID, role, action, entityType, entityId string, success bool, details map[string]interface{}) {
	if details == nil {
		details = map[string]interface{}{}
	}
	now := time.Now().UTC()
	id := newUUID()
	searchParts := []string{action, entityType, entityId, actorID, role}
	for k, v := range details {
		searchParts = append(searchParts, k, stringify(v))
	}
	doc := bson.M{
		"auditId":     id,
		"audit_id":    id,
		"actorId":     actorID,
		"actor_id":    actorID,
		"role":        role,
		"actorRole":   role,
		"action":      action,
		"entityType":  entityType,
		"entity_type": entityType,
		"entityId":    entityId,
		"entity_id":   entityId,
		"success":     success,
		"occurredAt":  now,
		"occurred_at": now,
		"details":     details,
		"searchText":  strings.Join(searchParts, " "),
	}
	if _, err := app.store.audit.InsertOne(ctx, doc); err != nil {
		log.Printf("audit insert: %v", err)
	}
	_, err := app.store.pg.Exec(ctx, `
INSERT INTO timeline (action, actor_id, role, entity_type, entity_id, success, occurred_at, details)
VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
		action, actorID, role, entityType, entityId, success, now, asJSON(details))
	if err != nil {
		log.Printf("timeline insert: %v", err)
	}
}

func stringify(v interface{}) string {
	switch t := v.(type) {
	case string:
		return t
	default:
		return string(asJSON(v))
	}
}

func (app *App) emit(typ, entityType, entityId string, payload map[string]interface{}) {
	if payload == nil {
		payload = map[string]interface{}{}
	}
	var id int64
	err := app.store.pg.QueryRow(context.Background(), `
INSERT INTO realtime_events (type, entity_type, entity_id, payload)
VALUES ($1,$2,$3,$4) RETURNING id`, typ, entityType, entityId, asJSON(payload)).Scan(&id)
	if err != nil {
		log.Printf("emit: %v", err)
		return
	}
	ev := RealtimeEvent{
		ID: id, Type: typ, EntityType: entityType, EntityID: entityId,
		Payload: payload, CreatedAt: time.Now().UTC(),
	}
	app.store.mu.RLock()
	defer app.store.mu.RUnlock()
	for ch := range app.store.eventSubs {
		select {
		case ch <- ev:
		default:
		}
	}
}

type RealtimeEvent struct {
	ID         int64                  `json:"id"`
	Type       string                 `json:"type"`
	EntityType string                 `json:"entityType"`
	EntityID   string                 `json:"entityId"`
	Payload    map[string]interface{} `json:"payload"`
	CreatedAt  time.Time              `json:"createdAt"`
}

func (app *App) subscribe() chan RealtimeEvent {
	ch := make(chan RealtimeEvent, 32)
	app.store.mu.Lock()
	app.store.eventSubs[ch] = struct{}{}
	app.store.mu.Unlock()
	return ch
}

func (app *App) unsubscribe(ch chan RealtimeEvent) {
	app.store.mu.Lock()
	delete(app.store.eventSubs, ch)
	app.store.mu.Unlock()
	close(ch)
}

func (app *App) loadTimeline(ctx context.Context, entityIds ...string) []map[string]interface{} {
	if len(entityIds) == 0 {
		return []map[string]interface{}{}
	}
	rows, err := app.store.pg.Query(ctx, `
SELECT event_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
FROM timeline WHERE entity_id = ANY($1) ORDER BY event_id ASC`, entityIds)
	if err != nil {
		return []map[string]interface{}{}
	}
	defer rows.Close()
	out := []map[string]interface{}{}
	for rows.Next() {
		var e TimelineEntry
		var details []byte
		if err := rows.Scan(&e.EventID, &e.Action, &e.ActorID, &e.Role, &e.EntityType, &e.EntityID, &e.Success, &e.OccurredAt, &details); err != nil {
			continue
		}
		e.Details = map[string]interface{}{}
		if len(details) > 0 {
			_ = json.Unmarshal(details, &e.Details)
		}
		if e.Details == nil {
			e.Details = map[string]interface{}{}
		}
		out = append(out, map[string]interface{}{
			"eventId":    e.EventID,
			"action":     e.Action,
			"actorId":    e.ActorID,
			"role":       e.Role,
			"entityType": e.EntityType,
			"entityId":   e.EntityID,
			"success":    e.Success,
			"occurredAt": rfc3339(e.OccurredAt),
			"details":    e.Details,
		})
	}
	return out
}

func (app *App) searchAudit(ctx context.Context, q queryAudit) (map[string]interface{}, error) {
	filter := bson.M{}
	ands := []bson.M{}
	if q.Query != "" {
		ands = append(ands, bson.M{"$or": []bson.M{
			{"$text": bson.M{"$search": q.Query}},
			{"action": bson.M{"$regex": q.Query, "$options": "i"}},
			{"entityId": bson.M{"$regex": q.Query, "$options": "i"}},
			{"searchText": bson.M{"$regex": q.Query, "$options": "i"}},
		}})
	}
	if q.ActorID != "" {
		ands = append(ands, bson.M{"actorId": q.ActorID})
	}
	if q.EntityType != "" {
		ands = append(ands, bson.M{"entityType": q.EntityType})
	}
	if q.EntityID != "" {
		ands = append(ands, bson.M{"entityId": q.EntityID})
	}
	if q.Action != "" {
		ands = append(ands, bson.M{"action": q.Action})
	}
	if q.Role != "" {
		ands = append(ands, bson.M{"role": q.Role})
	}
	if q.Success != nil {
		ands = append(ands, bson.M{"success": *q.Success})
	}
	if q.FromTime != nil || q.ToTime != nil {
		rng := bson.M{}
		if q.FromTime != nil {
			rng["$gte"] = *q.FromTime
		}
		if q.ToTime != nil {
			rng["$lte"] = *q.ToTime
		}
		ands = append(ands, bson.M{"occurredAt": rng})
	}
	if len(ands) == 1 {
		filter = ands[0]
	} else if len(ands) > 1 {
		filter = bson.M{"$and": ands}
	}
	limit := q.Limit
	if limit <= 0 {
		limit = 500
	}
	if limit > 5000 {
		return nil, herr(400, "invalid_limit", "invalid limit")
	}
	offset := q.Offset
	if offset < 0 {
		return nil, herr(400, "invalid_offset", "invalid offset")
	}
	order := q.Order
	if order == "" {
		order = "newest_first"
	}
	if order != "newest_first" && order != "oldest_first" {
		return nil, herr(400, "invalid_order", "invalid order")
	}
	sort := bson.D{{Key: "occurredAt", Value: -1}}
	if order == "oldest_first" {
		sort = bson.D{{Key: "occurredAt", Value: 1}}
	}
	total, err := app.store.audit.CountDocuments(ctx, filter)
	if err != nil {
		return nil, err
	}
	opts := options.Find().SetSort(sort).SetSkip(int64(offset)).SetLimit(int64(limit))
	cur, err := app.store.audit.Find(ctx, filter, opts)
	if err != nil {
		return nil, err
	}
	defer cur.Close(ctx)
	entries := []map[string]interface{}{}
	for cur.Next(ctx) {
		var raw bson.M
		if err := cur.Decode(&raw); err != nil {
			continue
		}
		entries = append(entries, normalizeAudit(raw))
	}
	returned := len(entries)
	hasMore := int64(offset+returned) < total
	res := map[string]interface{}{
		"entries":  entries,
		"total":    total,
		"returned": returned,
		"offset":   offset,
		"limit":    limit,
		"order":    order,
		"hasMore":  hasMore,
	}
	if hasMore {
		res["nextOffset"] = offset + returned
	}
	return res, nil
}

type queryAudit struct {
	Query      string
	ActorID    string
	EntityType string
	EntityID   string
	Action     string
	Role       string
	Success    *bool
	FromTime   *time.Time
	ToTime     *time.Time
	Limit      int
	Offset     int
	Order      string
}

func normalizeAudit(raw bson.M) map[string]interface{} {
	get := func(keys ...string) interface{} {
		for _, k := range keys {
			if v, ok := raw[k]; ok && v != nil {
				return v
			}
		}
		return ""
	}
	occurred := get("occurredAt", "occurred_at")
	var occurredStr string
	switch t := occurred.(type) {
	case time.Time:
		occurredStr = t.UTC().Format(time.RFC3339)
	case bson.DateTime:
		occurredStr = t.Time().UTC().Format(time.RFC3339)
	default:
		occurredStr = stringify(occurred)
	}
	details := map[string]interface{}{}
	switch d := raw["details"].(type) {
	case bson.M:
		for k, v := range d {
			details[k] = v
		}
	case map[string]interface{}:
		details = d
	}
	aid := get("auditId", "audit_id")
	actor := get("actorId", "actor_id")
	et := get("entityType", "entity_type")
	eid := get("entityId", "entity_id")
	role, _ := get("role").(string)
	return map[string]interface{}{
		"auditId":     aid,
		"audit_id":    aid,
		"actorId":     actor,
		"actor_id":    actor,
		"role":        role,
		"actorRole":   get("actorRole", "role"),
		"action":      get("action"),
		"entityType":  et,
		"entity_type": et,
		"entityId":    eid,
		"entity_id":   eid,
		"success":     raw["success"] == true,
		"occurredAt":  occurredStr,
		"occurred_at": occurredStr,
		"details":     details,
	}
}
"}

