	}
	defer rows.Close()
	out := []locRow{}
	ids := []string{}
	idx := map[string]int{}
	for rows.Next() {
		var l locRow
		if err := rows.Scan(&l.ID, &l.Name, &l.Lat, &l.Lng, &l.CoverageKm, &l.HandlingMinutes, &l.Active,
			&l.FnCollection, &l.FnTransfer, &l.FnHub, &l.FnLaboratory,
			&l.CapacityUnits, &l.ReservedUnits, &l.CooledCap, &l.CooledReserved); err != nil {
			return nil, err
		}
		idx[l.ID] = len(out)
		ids = append(ids, l.ID)
		out = append(out, l)
	}
	if len(ids) == 0 {
		return out, nil
	}
	arows, err := app.store.pg.Query(ctx, `SELECT laboratory_id, sample_type_id FROM laboratory_acceptance WHERE accepts=true`)
	if err != nil {
		return nil, err
	}
	defer arows.Close()
	for arows.Next() {
		var lab, st string
		if err := arows.Scan(&lab, &st); err != nil {
			return nil, err
		}
		if i, ok := idx[lab]; ok {
			out[i].AcceptedTypes = append(out[i].AcceptedTypes, st)
		}
	}
	return out, nil
}

func (app *App) loadConnections(ctx context.Context) ([]connRow, error) {
	rows, err := app.store.pg.Query(ctx, `
SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active,
  capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
FROM connections`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []connRow{}
	for rows.Next() {
		var c connRow
		if err := rows.Scan(&c.ID, &c.FromID, &c.ToID, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active,
			&c.CapacityUnits, &c.ReservedUnits, &c.CooledCap, &c.CooledReserved); err != nil {
			return nil, err
		}
		out = append(out, c)
	}
	return out, nil
}

