func locByID(locs []locRow, id string) *locRow {
	for i := range locs {
		if locs[i].ID == id {
			return &locs[i]
		}
	}
	return nil
}

func (app *App) evaluateServiceability(ctx context.Context, origin Coord, originType, originNodeID, sampleTypeID string, requestedAt, deadline, earliest, latest time.Time) (*planResult, error) {
	st, err := app.loadSampleType(ctx, sampleTypeID)
	if err != nil {
		return nil, err
	}
	locs, err := app.loadLocations(ctx)
	if err != nil {
		return nil, err
	}
	conns, err := app.loadConnections(ctx)
	if err != nil {
		return nil, err
	}
	return planServiceability(locs, conns, st, origin, originType, originNodeID, requestedAt, deadline, earliest, latest), nil
}

func planServiceability(locs []locRow, conns []connRow, st *sampleTypeRow, origin Coord, originType, originNodeID string, requestedAt, deadline, earliest, latest time.Time) *planResult {
	res := &planResult{Serviceable: false, Reason: "outside_service_coverage", NeedsCooled: st.RequiresCooled}

	var start *locRow
	if originType == "node" && originNodeID != "" {
		start = locByID(locs, originNodeID)
		if start == nil || !start.Active {
			res.Reason = "outside_service_coverage"
			return res
		}
	} else {
		bestDist := math.MaxFloat64
		for i := range locs {
			l := &locs[i]
			if !l.Active || !l.FnCollection {
				continue
			}
			d := haversineKm(origin.Latitude, origin.Longitude, l.Lat, l.Lng)
			cov := l.CoverageKm
			if cov <= 0 {
				cov = 5
			}
			if d <= cov && d < bestDist {
				bestDist = d
				start = l
			}
		}
		if start == nil {
			res.Reason = "outside_service_coverage"
			return res
		}
		// home/clinic travel minutes from origin to collection point at 25 km/h
		res.CollectionTravelMin = int(math.Ceil(bestDist / 25.0 * 60.0))
		if res.CollectionTravelMin < 1 {
			res.CollectionTravelMin = 1
		}
	}
	res.CollectionPoint = start.ID

	labs := []locRow{}
	for _, l := range locs {
		if !l.Active || !l.FnLaboratory {
			continue
		}
		if !contains(l.AcceptedTypes, st.ID) && len(l.AcceptedTypes) > 0 {
			continue
		}
		// if no acceptances configured, treat as accepting all
		if len(l.AcceptedTypes) == 0 {
			// still a laboratory; allow unless we have other labs that do accept
			labs = append(labs, l)
			continue
		}
		labs = append(labs, l)
	}
	// prefer labs that explicitly accept
	explicit := []locRow{}
	for _, l := range labs {
		if contains(l.AcceptedTypes, st.ID) {
			explicit = append(explicit, l)
		}
	}
	if len(explicit) > 0 {
		labs = explicit
	}
	if len(labs) == 0 {
		res.Reason = "no_accepting_laboratory"
		return res
	}

	type cand struct {
		lab   locRow
		path  []string
		mins  int
		cost  float64
		hmin  int
	}
	var best *cand
	for _, lab := range labs {
		path, mins, cost, ok := shortestPath(locs, conns, start.ID, lab.ID, st.RequiresCooled)
		if !ok {
			continue
		}
		hmin := 0
		for _, id := range path {
			if l := locByID(locs, id); l != nil {
				hmin += l.HandlingMinutes
			}
		}
		c := cand{lab: lab, path: path, mins: mins, cost: cost, hmin: hmin}
		if best == nil || c.mins < best.mins || (c.mins == best.mins && c.cost < best.cost) {
			cp := c
			best = &cp
		}
	}
	if best == nil {
		res.Reason = "no_route"
		return res
	}

	// capacity along path
	for i := 0; i+1 < len(best.path); i++ {
		c := findConn(conns, best.path[i], best.path[i+1])
		if c == nil {
			res.Reason = "no_route"
			return res
		}
		if st.RequiresCooled {
			if c.CooledCap-c.CooledReserved < 1 && c.CooledCap > 0 {
				res.Reason = "insufficient_capacity"
				return res
			}
		} else if c.CapacityUnits > 0 && c.CapacityUnits-c.ReservedUnits < 1 {
			res.Reason = "insufficient_capacity"
			return res
		}
	}
	for _, id := range best.path {
		l := locByID(locs, id)
		if l == nil {
			continue
		}
		if st.RequiresCooled {
			if l.CooledCap > 0 && l.CooledCap-l.CooledReserved < 1 {
				res.Reason = "insufficient_capacity"
				return res
			}
		} else if l.CapacityUnits > 0 && l.CapacityUnits-l.ReservedUnits < 1 {
			res.Reason = "insufficient_capacity"
			return res
		}
	}

	startAt := requestedAt
	if !earliest.IsZero() && earliest.After(startAt) {
		startAt = earliest
	}
	arrival := startAt.Add(time.Duration(res.CollectionTravelMin+best.mins+best.hmin) * time.Minute)
	if !deadline.IsZero() && arrival.After(deadline) {
		res.Reason = "deadline_unreachable"
		res.TargetLab = best.lab.ID
		res.EstimatedArrival = arrival
		res.Path = best.path
		return res
	}

	res.Serviceable = true
	res.Reason = "serviceable"
	res.TargetLab = best.lab.ID
	res.EstimatedArrival = arrival
	res.Path = best.path
	res.TravelMinutes = best.mins
	res.HandlingMinutes = best.hmin
	res.TotalCost = best.cost
	return res
}

func findConn(conns []connRow, from, to string) *connRow {
	for i := range conns {
		if conns[i].FromID == from && conns[i].ToID == to && conns[i].Active {
			return &conns[i]
		}
	}
	return nil
}

func shortestPath(locs []locRow, conns []connRow, from, to string, needCooled bool) ([]string, int, float64, bool) {
	if from == to {
		return []string{from}, 0, 0, true
	}
	type node struct {
		id   string
		mins int
		cost float64
		prev string
	}
	dist := map[string]int{}
	cost := map[string]float64{}
	prev := map[string]string{}
	for _, l := range locs {
		dist[l.ID] = math.MaxInt32
	}
	dist[from] = 0
	type item struct {
		id   string
		mins int
	}
	q := []item{{from, 0}}
	for len(q) > 0 {
		sort.Slice(q, func(i, j int) bool { return q[i].mins < q[j].mins })
		cur := q[0]
		q = q[1:]
		if cur.mins != dist[cur.id] {
			continue
		}
		if cur.id == to {
			break
		}
		for _, c := range conns {
			if !c.Active || c.FromID != cur.id {
				continue
			}
			if needCooled && !c.Cooled {
				continue
			}
			nm := cur.mins + c.TravelMinutes
			if nm < dist[c.ToID] {
				dist[c.ToID] = nm
				cost[c.ToID] = cost[cur.id] + c.CostUnits
				prev[c.ToID] = cur.id
				q = append(q, item{c.ToID, nm})
			}
		}
	}
	if dist[to] == math.MaxInt32 {
		return nil, 0, 0, false
	}
	path := []string{to}
	for path[0] != from {
		p, ok := prev[path[0]]
		if !ok {
			return nil, 0, 0, false
		}
		path = append([]string{p}, path...)
	}
	return path, dist[to], cost[to], true
}

func (app *App) bumpNetwork(ctx context.Context) {
	_, _ = app.store.pg.Exec(ctx, `UPDATE network_meta SET revision = revision + 1, updated_at=now() WHERE id=1`)
	go app.recomputeServiceability()
}

func (app *App) recomputeServiceability() {
	app.store.mu.Lock()
	if app.store.svcComputing {
		app.store.mu.Unlock()
		return
	}
	app.store.svcComputing = true
	app.store.mu.Unlock()
	defer func() {
		app.store.mu.Lock()
		app.store.svcComputing = false
		app.store.mu.Unlock()
	}()

	ctx := context.Background()
	var rev int
	_ = app.store.pg.QueryRow(ctx, `SELECT revision FROM network_meta WHERE id=1`).Scan(&rev)
	locs, err := app.loadLocations(ctx)
	if err != nil {
		return
	}
	regions := []map[string]interface{}{}
	count := 0
	for _, l := range locs {
		if l.Active && l.FnCollection {
			count++
			cov := l.CoverageKm
			if cov <= 0 {
				cov = 5
			}
			regions = append(regions, map[string]interface{}{
				"locationId": l.ID,
				"name":       l.Name,
				"latitude":   l.Lat,
				"longitude":  l.Lng,
				"coverageKm": cov,
			})
		}
	}
	var ver int
	_ = app.store.pg.QueryRow(ctx, `SELECT COALESCE(MAX(version),0)+1 FROM serviceability_snapshots`).Scan(&ver)
	if ver < 1 {
		ver = 1
	}
	now := time.Now().UTC()
	_, err = app.store.pg.Exec(ctx, `
INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, regions, active_collection_point_count)
VALUES ($1,'complete',$2,$3,$4,$5)`, ver, now, rev, asJSON(regions), count)
	if err != nil {
		return
	}
	app.store.mu.Lock()
	app.store.svcVersion = ver
	app.store.svcComputed = now
	app.store.svcRevision = rev
	app.store.mu.Unlock()
}

func (app *App) currentServiceability(ctx context.Context) (int, time.Time, int, []map[string]interface{}, int, error) {
	var ver, rev, count int
	var computed time.Time
	var raw []byte
	err := app.store.pg.QueryRow(ctx, `
SELECT version, computed_at, network_revision, regions, active_collection_point_count
FROM serviceability_snapshots WHERE status='complete' ORDER BY version DESC LIMIT 1`).
		Scan(&ver, &computed, &rev, &raw, &count)
	if err != nil {
		return 1, time.Now().UTC(), 0, []map[string]interface{}{}, 0, nil
	}
	regions := []map[string]interface{}{}
	_ = jsonUnmarshal(raw, &regions)
	if regions == nil {
		regions = []map[string]interface{}{}
	}
	return ver, computed, rev, regions, count, nil
}

func jsonUnmarshal(b []byte, v interface{}) error {
	if len(b) == 0 {
		return nil
	}
	return json.Unmarshal(b, v)
}
"}

