	repl := []string{}
	if s.ActiveJourneyID != nil {
		r2, err := app.store.pg.Query(ctx, `SELECT id FROM journeys WHERE parent_journey_id=$1 AND status NOT IN ('cancelled','completed')`, *s.ActiveJourneyID)
		if err == nil {
			defer r2.Close()
			for r2.Next() {
				var id string
				if r2.Scan(&id) == nil {
					repl = append(repl, id)
				}
			}
		}
	}
	out := map[string]interface{}{
		"sampleId":                  s.ID,
		"status":                    s.Status,
		"sealed":                    s.Sealed,
		"completedLegIds":           completed,
		"activeReplacementPlanIds":  repl,
		"timeline":                  tl,
		"locationStale":             isStale(s.LocationRecordedAt, now),
	}
	if s.ActiveJourneyID != nil {
		out["activeJourneyId"] = *s.ActiveJourneyID
	}
	if s.CurrentHolderID != nil {
		out["currentHolderId"] = *s.CurrentHolderID
	}
	if s.ReceivedLabID != nil {
		out["receivedLaboratoryId"] = *s.ReceivedLabID
	}
	if len(s.Exception) > 0 && string(s.Exception) != "null" {
		var ex interface{}
		if json.Unmarshal(s.Exception, &ex) == nil && ex != nil {
			out["exception"] = ex
		}
	}
	var hid *string
	_ = app.store.pg.QueryRow(ctx, `SELECT id FROM handoffs WHERE sample_id=$1 AND status='pending' ORDER BY created_at DESC LIMIT 1`, s.ID).Scan(&hid)
	if hid != nil {
		out["pendingHandoffId"] = *hid
		out["pendingHandoff"] = map[string]interface{}{"handoffId": *hid, "status": "pending"}
	}
	if s.LatestLat != nil && s.LatestLng != nil {
		out["latestLocation"] = map[string]interface{}{"latitude": *s.LatestLat, "longitude": *s.LatestLng}
	}
	if s.LocationRecordedAt != nil {
		out["locationRecordedAt"] = rfc3339(*s.LocationRecordedAt)
	}
	return out
}

type journeyRow struct {
	ID, ParentID, RouteMode, Status, ReplanStatus string
	PlanVersion                                   int
	Estimated                                     *time.Time
	TotalCost                                     float64
	CapacityUsed, CapacityAvail                   int
	Valid                                         bool
}

func (app *App) loadJourney(ctx context.Context, id string) (*journeyRow, error) {
	var j journeyRow
	var parent *string
	err := app.store.pg.QueryRow(ctx, `
SELECT id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at,
  total_cost_units, capacity_used, capacity_available, valid, replan_status
FROM journeys WHERE id=$1`, id).Scan(&j.ID, &parent, &j.PlanVersion, &j.RouteMode, &j.Status, &j.Estimated,
		&j.TotalCost, &j.CapacityUsed, &j.CapacityAvail, &j.Valid, &j.ReplanStatus)
	if err != nil {
		return nil, herr(404, "not_found", "journey not found")
	}
	if parent != nil {
		j.ParentID = *parent
	}
	return &j, nil
}

func (app *App) journeySampleIDs(ctx context.Context, journeyID string) []string {
	rows, err := app.store.pg.Query(ctx, `SELECT sample_id FROM journey_samples WHERE journey_id=$1`, journeyID)
	if err != nil {
		return []string{}
	}
	defer rows.Close()
	out := []string{}
	for rows.Next() {
		var id string
		if rows.Scan(&id) == nil {
			out = append(out, id)
		}
	}
	return out
}

func (app *App) journeyPlanPayload(ctx context.Context, journeyID, viewerRole, viewerID string) (map[string]interface{}, error) {
	j, err := app.loadJourney(ctx, journeyID)
	if err != nil {
		return nil, err
	}
	sids := app.journeySampleIDs(ctx, journeyID)
	if sids == nil {
		sids = []string{}
	}
	stops := []map[string]interface{}{}
	srows, err := app.store.pg.Query(ctx, `
SELECT id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude, completed_at
FROM journey_stops WHERE journey_id=$1 ORDER BY sequence`, journeyID)
	if err == nil {
		defer srows.Close()
		for srows.Next() {
			var id, stype string
			var locID *string
			var seq, dwell int
			var est time.Time
			var lat, lng *float64
			var done *time.Time
			if err := srows.Scan(&id, &locID, &stype, &seq, &est, &dwell, &lat, &lng, &done); err != nil {
				continue
			}
			item := map[string]interface{}{
				"stopId":      id,
				"stopType":    stype,
				"stop_type":   stype,
				"sequence":    seq,
				"estimatedAt": rfc3339(est),
				"estimated_at": rfc3339(est),
				"dwellMinutes": dwell,
			}
			if locID != nil {
				item["locationId"] = *locID
				item["location_id"] = *locID
			} else {
				item["locationId"] = "00000000-0000-0000-0000-000000000000"
			}
			if lat != nil && lng != nil {
				item["coordinate"] = map[string]interface{}{"latitude": *lat, "longitude": *lng}
			}
			if done != nil {
				item["completedAt"] = rfc3339(*done)
			}
			stops = append(stops, item)
		}
	}

	legs := []map[string]interface{}{}
	arows, err := app.store.pg.Query(ctx, `
SELECT id, sample_id, sequence, status, from_location_id, to_location_id, worker_id, kind
FROM assignments WHERE journey_id=$1 ORDER BY sequence, created_at`, journeyID)
	if err == nil {
		defer arows.Close()
		for arows.Next() {
			var id, status, kind string
			var sid, from, to, worker *string
			var seq int
			if err := arows.Scan(&id, &sid, &seq, &status, &from, &to, &worker, &kind); err != nil {
				continue
			}
			if viewerRole == RoleDeliveryPartner || viewerRole == RoleCollectionProfessional || viewerRole == RoleNodeHandler || viewerRole == RoleLaboratoryTeam {
				if worker == nil || *worker != viewerID {
					// still include offered-to
					var offered *string
					_ = app.store.pg.QueryRow(ctx, `SELECT offered_to FROM assignments WHERE id=$1`, id).Scan(&offered)
					if offered == nil || *offered != viewerID {
						continue
					}
				}
			}
			leg := map[string]interface{}{
				"assignmentId":  id,
				"assignment_id": id,
				"sequence":      seq,
				"status":        status,
			}
			if from != nil {
				leg["fromLocationId"] = *from
				leg["from_location_id"] = *from
			}
			if to != nil {
				leg["toLocationId"] = *to
				leg["to_location_id"] = *to
			}
			if worker != nil && viewerRole != RoleRequester {
				leg["workerId"] = *worker
				leg["worker_id"] = *worker
			}
			if sid != nil {
				leg["sampleId"] = *sid
			}
			legs = append(legs, leg)
		}
	}

	out := map[string]interface{}{
		"journeyId":     j.ID,
		"planVersion":   j.PlanVersion,
		"routeMode":     j.RouteMode,
		"status":        j.Status,
		"totalCostUnits": j.TotalCost,
		"sampleIds":     sids,
		"orderedStops":  stops,
		"legs":          legs,
		"capacityUsed":  j.CapacityUsed,
		"capacityAvailable": j.CapacityAvail,
		"valid":         j.Valid,
	}
	if j.ParentID != "" {
		out["parentJourneyId"] = j.ParentID
	}
	if j.Estimated != nil {
		out["estimatedDeliveryAt"] = rfc3339(*j.Estimated)
	}
	if viewerRole == RoleRequester {
		// RequesterJourneyPlan required: journeyId, sampleIds, legs
		req := map[string]interface{}{
			"journeyId": j.ID,
			"sampleIds": sids,
			"legs":      legs,
		}
		if j.ParentID != "" {
			req["parentJourneyId"] = j.ParentID
		}
		req["planVersion"] = j.PlanVersion
		req["routeMode"] = j.RouteMode
		req["status"] = j.Status
		if j.Estimated != nil {
			req["estimatedDeliveryAt"] = rfc3339(*j.Estimated)
		}
		req["totalCostUnits"] = j.TotalCost
		req["orderedStops"] = stops
		return req, nil
	}
	return out, nil
}

func (app *App) canSeeSample(u *SessionUser, s *sampleRow) bool {
	if u.isDispatcher() {
		return true
	}
	if u.ActiveRole == RoleRequester {
		return s.RequesterID == u.UserID
	}
	// workers see samples they hold or are assigned
	if s.CurrentHolderID != nil && *s.CurrentHolderID == u.UserID {
		return true
	}
	var n int
	_ = app.store.pg.QueryRow(context.Background(), `
SELECT COUNT(*) FROM assignments
WHERE sample_id=$1 AND (worker_id=$2 OR offered_to=$2)`, s.ID, u.UserID).Scan(&n)
	return n > 0
}

func ptrStr(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}
"}

{"path":"/workspace/backend/handlers_auth.go","command":"create","file_text":"package main

import (
	"net/http"
	"strings"
	"time"
)

func (app *App) handleAuthenticate(w http.ResponseWriter, r *http.Request) {
	body := readBody(r)
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := decodeBody(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.Username == "" || req.Password == "" {
		writeErr(w, 400, "invalid_json", "username and password required")
		return
	}
	var id, hash string
	var active bool
	err := app.store.pg.QueryRow(r.Context(), `SELECT id, password_hash, active FROM users WHERE username=$1`, req.Username).
		Scan(&id, &hash, &active)
	if err != nil || !checkPassword(hash, req.Password) {
		app.audit(r.Context(), "", "", "authenticate", "user", req.Username, false, map[string]interface{}{"reason": "invalid_credentials"})
		writeErr(w, 401, "unauthorized", "invalid credentials")
		return
	}
	if !active {
		writeErr(w, 403, "forbidden", "account inactive")
		return
	}
	u, err := app.loadUser(r.Context(), id, "")
	if err != nil {
		writeErr(w, 500, "internal_error", "internal error")
		return
	}
	activeRole := ""
	if len(u.Roles) == 1 {
		activeRole = u.Roles[0]
	}
	tok := newToken()
	_, err = app.store.pg.Exec(r.Context(), `
INSERT INTO sessions (token, user_id, active_role, expires_at) VALUES ($1,$2,$3,$4)`,
		tok, id, activeRole, time.Now().Add(24*time.Hour))
	if err != nil {
		writeErr(w, 500, "internal_error", "internal error")
		return
	}
	app.audit(r.Context(), id, activeRole, "authenticate", "user", id, true, map[string]interface{}{"username": req.Username})
	writeData(w, 200, map[string]interface{}{
		"sessionToken": tok,
		"userId":       id,
		"roles":        u.Roles,
		"activeRole":   activeRole,
	})
}

func (app *App) handleSelectRole(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	var req struct {
		Role string `json:"role"`
	}
	if err := decodeBody(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if !validRole(req.Role) {
		writeErr(w, 400, "invalid_role", "invalid role")
		return
	}
	if !u.hasRole(req.Role) {
		writeErr(w, 403, "forbidden", "role not assigned")
		return
	}
	tok := bearerToken(r)
	_, err := app.store.pg.Exec(r.Context(), `UPDATE sessions SET active_role=$1 WHERE token=$2`, req.Role, tok)
	if err != nil {
		writeErr(w, 500, "internal_error", "internal error")
		return
	}
	app.audit(r.Context(), u.UserID, req.Role, "select_active_role", "user", u.UserID, true, map[string]interface{}{"role": req.Role})
	writeData(w, 200, map[string]interface{}{
		"activeRole": req.Role,
		"roles":      u.Roles,
	})
}

func (app *App) handleCreateUser(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u.ActiveRole != RoleAdministrator {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	body := readBody(r)
	var req struct {
		Username           string          `json:"username"`
		InitialPassword    string          `json:"initialPassword"`
		Email              string          `json:"email"`
		FullName           string          `json:"fullName"`
		Phone              string          `json:"phone"`
		Roles              []string        `json:"roles"`
		Qualifications     []string        `json:"qualifications"`
		Certifications     []Certification `json:"certifications"`
		Active             bool            `json:"active"`
		AssignedLocationID string          `json:"assignedLocationId"`
	}
	if err := decodeBody(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.Username == "" || req.InitialPassword == "" || len(req.Roles) == 0 {
		writeErr(w, 400, "invalid_json", "username, password and roles required")
		return
	}
	for _, role := range req.Roles {
		if !validRole(role) {
			writeErr(w, 400, "invalid_role", "invalid role")
			return
		}
	}
	hash, err := hashPassword(req.InitialPassword)
	if err != nil {
		writeErr(w, 500, "internal_error", "internal error")
		return
	}
	id := newUUID()
	_, err = app.store.pg.Exec(r.Context(), `
INSERT INTO users (id, username, password_hash, email, full_name, phone, active, assigned_location_id)
VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
		id, req.Username, hash, req.Email, req.FullName, req.Phone, req.Active, nilIfEmpty(req.AssignedLocationID))
	if err != nil {
		if strings.Contains(err.Error(), "unique") || strings.Contains(err.Error(), "duplicate") {
			writeErr(w, 409, "concurrent_conflict", "username already exists")
			return
		}
		writeErr(w, 500, "internal_error", err.Error())
		return
	}
	for _, role := range req.Roles {
		_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO user_roles (user_id, role) VALUES ($1,$2)`, id, role)
	}
	for _, q := range req.Qualifications {
		_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO user_qualifications (user_id, qualification) VALUES ($1,$2)`, id, q)
	}
	for _, c := range req.Certifications {
		_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)`,
			id, c.Code, c.Active, c.ExpiresAt)
	}
	app.audit(r.Context(), u.UserID, u.ActiveRole, "create_user", "user", id, true, map[string]interface{}{"username": req.Username, "roles": req.Roles})
	payload, _ := app.userPayload(r.Context(), id)
	writeData(w, 201, payload)
}

func (app *App) handleUpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u.ActiveRole != RoleAdministrator {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	body := readBody(r)
	var req struct {
		UserID             string          `json:"userId"`
		Roles              []string        `json:"roles"`
		Qualifications     []string        `json:"qualifications"`
		Certifications     []Certification `json:"certifications"`
		Active             bool            `json:"active"`
		AssignedLocationID string          `json:"assignedLocationId"`
	}
	if err := decodeBody(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.UserID == "" {
		writeErr(w, 400, "invalid_json", "userId required")
		return
	}
	for _, role := range req.Roles {
		if !validRole(role) {
			writeErr(w, 400, "invalid_role", "invalid role")
			return
		}
	}
	tag, err := app.store.pg.Exec(r.Context(), `
UPDATE users SET active=$2, assigned_location_id=$3 WHERE id=$1`, req.UserID, req.Active, nilIfEmpty(req.AssignedLocationID))
	if err != nil {
		writeErr(w, 500, "internal_error", "internal error")
		return
	}
	if tag.RowsAffected() == 0 {
		writeErr(w, 404, "not_found", "user not found")
		return
	}
	_, _ = app.store.pg.Exec(r.Context(), `DELETE FROM user_roles WHERE user_id=$1`, req.UserID)
	for _, role := range req.Roles {
		_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO user_roles (user_id, role) VALUES ($1,$2)`, req.UserID, role)
	}
	if req.Qualifications != nil {
		_, _ = app.store.pg.Exec(r.Context(), `DELETE FROM user_qualifications WHERE user_id=$1`, req.UserID)
		for _, q := range req.Qualifications {
			_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO user_qualifications (user_id, qualification) VALUES ($1,$2)`, req.UserID, q)
		}
	}
	if req.Certifications != nil {
		_, _ = app.store.pg.Exec(r.Context(), `DELETE FROM certifications WHERE user_id=$1`, req.UserID)
		for _, c := range req.Certifications {
			_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)`,
				req.UserID, c.Code, c.Active, c.ExpiresAt)
		}
	}
	app.audit(r.Context(), u.UserID, u.ActiveRole, "update_user_access", "user", req.UserID, true, map[string]interface{}{"roles": req.Roles, "active": req.Active})
	payload, err := app.userPayload(r.Context(), req.UserID)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	writeData(w, 201, payload)
}

func (app *App) handleReadUser(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	id := strings.TrimPrefix(r.URL.Path, "/api/read-user/")
	if id == "" {
		writeErr(w, 400, "invalid_json", "userId required")
		return
	}
	if !u.isDispatcher() && u.UserID != id {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	payload, err := app.userPayload(r.Context(), id)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	writeData(w, 200, payload)
}

func (app *App) handleSetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	var req struct {
		WorkerID      string `json:"workerId"`
		Available     bool   `json:"available"`
		CapacityUnits int    `json:"capacityUnits"`
	}
	if err := decodeBody(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.WorkerID == "" {
		writeErr(w, 400, "invalid_json", "workerId required")
		return
	}
	if req.CapacityUnits < 0 {
		writeErr(w, 400, "invalid_capacity", "invalid capacity")
		return
	}
	if !u.isDispatcher() && u.UserID != req.WorkerID {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	tag, err := app.store.pg.Exec(r.Context(), `UPDATE users SET available=$2, capacity_units=$3 WHERE id=$1`, req.WorkerID, req.Available, req.CapacityUnits)
	if err != nil {
		writeErr(w, 500, "internal_error", "internal error")
		return
	}
	if tag.RowsAffected() == 0 {
		writeErr(w, 404, "not_found", "worker not found")
		return
	}
	app.audit(r.Context(), u.UserID, u.ActiveRole, "set_worker_availability", "user", req.WorkerID, true, map[string]interface{}{"available": req.Available})
	writeData(w, 200, map[string]interface{}{
		"workerId":      req.WorkerID,
		"available":     req.Available,
		"capacityUnits": req.CapacityUnits,
	})
}

func (app *App) handleBootstrap(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	data := map[string]interface{}{
		"user": map[string]interface{}{
			"userId":                 u.UserID,
			"username":               u.Username,
			"fullName":               u.FullName,
			"roles":                  u.Roles,
			"activeRole":             u.ActiveRole,
			"roleSelectionRequired":  u.ActiveRole == "" && len(u.Roles) > 1,
		},
		"serverTime": rfc3339(time.Now()),
	}
	if u.ActiveRole == RoleRequester || u.isDispatcher() {
		samples := []map[string]interface{}{}
		q := `SELECT id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC LIMIT 200`
		args := []interface{}{u.UserID}
		if u.isDispatcher() {
			q = `SELECT id FROM samples ORDER BY created_at DESC LIMIT 200`
			args = nil
		}
		rows, err := app.store.pg.Query(r.Context(), q, args...)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var sid string
				if rows.Scan(&sid) != nil {
					continue
				}
				s, err := app.loadSample(r.Context(), sid)
				if err != nil {
					continue
				}
				samples = append(samples, app.sampleStatePayload(r.Context(), s))
			}
		}
		data["requesterSamples"] = samples
	}
	if u.isDispatcher() || u.ActiveRole == RoleNodeHandler || u.ActiveRole == RoleLaboratoryTeam {
		ops, _ := app.operationsState(r.Context(), u, "")
		data["operations"] = ops
	}
	writeData(w, 200, data)
}

func (app *App) handleReady(w http.ResponseWriter, r *http.Request) {
	if err := app.store.Ping(r.Context()); err != nil {
		writeJSON(w, 503, map[string]string{"status": "not_ready"})
		return
	}
	writeJSON(w, 200, map[string]string{"status": "ready"})
}
"}

{"path":"/workspace/backend/handlers_network.go","command":"create","file_text":"package main

import (
	"context"
	"net/http"
	"time"
)

func (app *App) handleCreateLocation(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u.ActiveRole != RoleAdministrator {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	body := readBody(r)
	var req struct {
		Name            string  `json:"name"`
		Coordinate      Coord   `json:"coordinate"`
		CoverageKm      float64 `json:"coverageKm"`
		HandlingMinutes int     `json:"handlingMinutes"`
		Active          bool    `json:"active"`
		Functions       []string `json:"functions"`
	}
	if err := decodeBody(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.Name == "" || len(req.Functions) == 0 {
		writeErr(w, 400, "invalid_json", "name and functions required")
		return
	}
	if req.Coordinate.Latitude < -90 || req.Coordinate.Latitude > 90 || req.Coordinate.Longitude < -180 || req.Coordinate.Longitude > 180 {
		writeErr(w, 400, "invalid_coordinate", "invalid coordinate")
		return
	}
	if req.CoverageKm == 0 {
		req.CoverageKm = 5
	}
	if req.CoverageKm <= 0 || req.CoverageKm > 5 {
		writeErr(w, 400, "invalid_node_coverage", "coverage must be between 0 and 5 km")
		return
	}
	if req.HandlingMinutes < 0 || req.HandlingMinutes > 1440 {
		writeErr(w, 400, "invalid_handling_time", "invalid handling time")
		return
	}
	for _, f := range req.Functions {
		if !validFunction(f) {
			writeErr(w, 400, "invalid_location_function", "invalid location function")
			return
		}
	}
