func (app *App) handleUpdateLocation(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u.ActiveRole != RoleAdministrator {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	body := readBody(r)
	var req struct {
		LocationID      string   `json:"locationId"`
		Name            string   `json:"name"`
		Coordinate      Coord    `json:"coordinate"`
		CoverageKm      *float64 `json:"coverageKm"`
		HandlingMinutes *int     `json:"handlingMinutes"`
		Functions       []string `json:"functions"`
	}
	if err := decodeBody(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.LocationID == "" || req.Name == "" {
		writeErr(w, 400, "invalid_json", "locationId and name required")
		return
	}
	if req.Coordinate.Latitude < -90 || req.Coordinate.Latitude > 90 {
		writeErr(w, 400, "invalid_coordinate", "invalid coordinate")
		return
	}
	if req.CoverageKm != nil && (*req.CoverageKm <= 0 || *req.CoverageKm > 5) {
		writeErr(w, 400, "invalid_node_coverage", "invalid coverage")
		return
	}
	if req.HandlingMinutes != nil && (*req.HandlingMinutes < 0 || *req.HandlingMinutes > 1440) {
		writeErr(w, 400, "invalid_handling_time", "invalid handling time")
		return
	}
	for _, f := range req.Functions {
		if !validFunction(f) {
			writeErr(w, 400, "invalid_location_function", "invalid location function")
			return
		}
	}
	var exists string
	if err := app.store.pg.QueryRow(r.Context(), `SELECT id FROM locations WHERE id=$1`, req.LocationID).Scan(&exists); err != nil {
		writeErr(w, 404, "not_found", "location not found")
		return
	}
	if req.CoverageKm != nil {
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE locations SET coverage_km=$2 WHERE id=$1`, req.LocationID, *req.CoverageKm)
	}
	if req.HandlingMinutes != nil {
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE locations SET handling_minutes=$2 WHERE id=$1`, req.LocationID, *req.HandlingMinutes)
	}
	if len(req.Functions) > 0 {
		fns := functionsFromList(req.Functions)
		_, _ = app.store.pg.Exec(r.Context(), `
UPDATE locations SET fn_collection=$2, fn_transfer=$3, fn_hub=$4, fn_laboratory=$5 WHERE id=$1`,
			req.LocationID, fns.CollectionPoint, fns.TransferPoint, fns.Hub, fns.Laboratory)
	}
	_, err := app.store.pg.Exec(r.Context(), `
UPDATE locations SET name=$2, latitude=$3, longitude=$4 WHERE id=$1`,
		req.LocationID, req.Name, req.Coordinate.Latitude, req.Coordinate.Longitude)
	if err != nil {
		writeErr(w, 500, "internal_error", "internal error")
		return
	}
	app.audit(r.Context(), u.UserID, u.ActiveRole, "update_location", "location", req.LocationID, true, nil)
	app.bumpNetwork(r.Context())
	payload, _ := app.locationPayload(r.Context(), req.LocationID)
	writeData(w, 201, payload)
}

