func (app *App) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	var req struct {
		ResourceID          string `json:"resourceId"`
		CapacityUnits       int    `json:"capacityUnits"`
		CooledCapacityUnits int    `json:"cooledCapacityUnits"`
	}
	if err := decodeBody(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.ResourceID == "" || req.CapacityUnits < 0 || req.CooledCapacityUnits < 0 {
		writeErr(w, 400, "invalid_capacity", "invalid capacity")
		return
	}
	// node handlers / lab team may configure their assigned location only
	if !u.isDispatcher() && u.ActiveRole != RoleAdministrator {
		if u.AssignedLocationID == "" || u.AssignedLocationID != req.ResourceID {
			writeErr(w, 403, "forbidden", "forbidden")
			return
		}
		if u.ActiveRole != RoleNodeHandler && u.ActiveRole != RoleLaboratoryTeam {
			writeErr(w, 403, "forbidden", "forbidden")
			return
		}
	} else if u.ActiveRole != RoleAdministrator && !u.isDispatcher() {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	// try location then connection
	tag, err := app.store.pg.Exec(r.Context(), `
UPDATE locations SET capacity_units=$2, cooled_capacity_units=$3 WHERE id=$1`,
		req.ResourceID, req.CapacityUnits, req.CooledCapacityUnits)
	if err != nil {
		writeErr(w, 500, "internal_error", "internal error")
		return
	}
	if tag.RowsAffected() == 0 {
		tag, err = app.store.pg.Exec(r.Context(), `
UPDATE connections SET capacity_units=$2, cooled_capacity_units=$3 WHERE id=$1`,
			req.ResourceID, req.CapacityUnits, req.CooledCapacityUnits)
		if err != nil || tag.RowsAffected() == 0 {
			writeErr(w, 404, "not_found", "resource not found")
			return
		}
	}
	app.audit(r.Context(), u.UserID, u.ActiveRole, "configure_capacity", "capacity", req.ResourceID, true, map[string]interface{}{
		"capacityUnits": req.CapacityUnits, "cooledCapacityUnits": req.CooledCapacityUnits,
	})
	app.bumpNetwork(r.Context())
	writeData(w, 200, map[string]interface{}{
		"resourceId":            req.ResourceID,
		"capacityUnits":         req.CapacityUnits,
		"cooledCapacityUnits":   req.CooledCapacityUnits,
	})
}

