func (app *App) handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	body := readBody(r)
	var req struct {
		Origin               Coord  `json:"origin"`
		OriginType           string `json:"originType"`
		OriginNodeID         string `json:"originNodeId"`
		SampleTypeID         string `json:"sampleTypeId"`
		RequestedAt          string `json:"requestedAt"`
		DeliveryDeadline     string `json:"deliveryDeadline"`
		EarliestCollectionAt string `json:"earliestCollectionAt"`
		LatestCollectionAt   string `json:"latestCollectionAt"`
	}
	if err := decodeBody(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.SampleTypeID == "" {
		writeErr(w, 400, "invalid_json", "sampleTypeId required")
		return
	}
	if req.OriginType == "" {
		req.OriginType = "home"
	}
	reqAt, err := parseTime(req.RequestedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid requestedAt")
		return
	}
	dead, err := parseTime(req.DeliveryDeadline)
	if err != nil {
		writeErr(w, 400, "invalid_deadline", "invalid deliveryDeadline")
		return
	}
	var earliest, latest time.Time
	if req.EarliestCollectionAt != "" {
		earliest, err = parseTime(req.EarliestCollectionAt)
		if err != nil {
			writeErr(w, 400, "invalid_collection_window", "invalid earliestCollectionAt")
			return
		}
	}
	if req.LatestCollectionAt != "" {
		latest, err = parseTime(req.LatestCollectionAt)
		if err != nil {
			writeErr(w, 400, "invalid_collection_window", "invalid latestCollectionAt")
			return
		}
	}
	plan, err := app.evaluateServiceability(r.Context(), req.Origin, req.OriginType, req.OriginNodeID, req.SampleTypeID, reqAt, dead, earliest, latest)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	ver, _, _, _, _, _ := app.currentServiceability(r.Context())
	out := map[string]interface{}{
		"serviceable":           plan.Serviceable,
		"reason":                plan.Reason,
		"serviceabilityVersion": ver,
	}
	if plan.TargetLab != "" {
		out["targetLaboratoryId"] = plan.TargetLab
	}
	if !plan.EstimatedArrival.IsZero() {
		out["estimatedArrivalAt"] = rfc3339(plan.EstimatedArrival)
	}
	writeData(w, 200, out)
}

