func (app *App) handleCollectAndSeal(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u.ActiveRole != RoleCollectionProfessional && !u.isDispatcher() {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			SampleID              string  `json:"sampleId"`
			AssignmentID          string  `json:"assignmentId"`
			CollectedAt           string  `json:"collectedAt"`
			ContainerType         string  `json:"containerType"`
			ObservedTemperatureC  float64 `json:"observedTemperatureC"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		at, err := parseTime(req.CollectedAt)
		if err != nil {
			return 0, nil, herr(400, "invalid_time", "invalid collectedAt")
		}
		s, err := app.loadSample(r.Context(), req.SampleID)
		if err != nil {
			return 0, nil, err
		}
		if s.Sealed {
			return 0, nil, herr(409, "already_sealed", "already sealed")
		}
		var kind, status string
		var worker, offered *string
		err = app.store.pg.QueryRow(r.Context(), `SELECT kind, status, worker_id, offered_to FROM assignments WHERE id=$1`, req.AssignmentID).
			Scan(&kind, &status, &worker, &offered)
		if err != nil {
			return 0, nil, herr(404, "not_found", "assignment not found")
		}
		if kind != "collection" {
			return 0, nil, herr(409, "invalid_assignment", "not a collection assignment")
		}
		if !u.isDispatcher() {
			ok := (worker != nil && *worker == u.UserID) || (offered != nil && *offered == u.UserID)
			if !ok {
				return 0, nil, herr(403, "forbidden", "not assigned")
			}
		}
		if at.Before(s.Earliest) || at.After(s.Latest) {
			return 0, nil, herr(409, "outside_collection_window", "outside collection window")
		}
		st, _ := app.loadSampleType(r.Context(), s.SampleTypeID)
		if st != nil && st.QualifiedCollector && !u.isDispatcher() {
			if !contains(u.Qualifications, st.RequiredQualification) && !hasActiveCert(u.Certifications, st.RequiredQualification) {
				return 0, nil, herr(403, "forbidden", "missing qualification")
			}
		}
		compliant := true
		if req.ObservedTemperatureC < s.TempMin || req.ObservedTemperatureC > s.TempMax {
			compliant = false
		}
		if req.ContainerType != s.ContainerType && req.ContainerType != "" && s.ContainerType != "" {
			// still record; may be non-compliant if type requires specific
			if st != nil && req.ContainerType != st.ContainerType {
				compliant = false
			}
		}
		now := at
		statusOut := "sealed"
		if !compliant {
			statusOut = "exception"
			_, _ = app.store.pg.Exec(r.Context(), `
UPDATE samples SET status='exception', sealed=TRUE, sealed_at=$2, current_holder_id=$3,
  exception=$4 WHERE id=$1`, s.ID, now, u.UserID, asJSON(map[string]interface{}{"reason": "handling_violation"}))
			_, _ = app.store.pg.Exec(r.Context(), `
INSERT INTO exceptions (id, sample_id, reason, observed_at) VALUES ($1,$2,$3,$4)`,
				newUUID(), s.ID, "handling_violation", now)
		} else {
			_, _ = app.store.pg.Exec(r.Context(), `
UPDATE samples SET status='sealed', sealed=TRUE, sealed_at=$2, current_holder_id=$3 WHERE id=$1`, s.ID, now, u.UserID)
		}
		_, _ = app.store.pg.Exec(r.Context(), `
UPDATE assignments SET status='completed', completed_at=$2, worker_id=$3 WHERE id=$1`, req.AssignmentID, now, u.UserID)
		app.audit(r.Context(), u.UserID, u.ActiveRole, "collect_and_seal", "sample", s.ID, true, map[string]interface{}{
			"assignmentId": req.AssignmentID, "compliant": compliant,
		})
		app.emit("sample.sealed", "sample", s.ID, map[string]interface{}{"status": statusOut})
		return 201, map[string]interface{}{
			"sampleId":           s.ID,
			"status":             "sealed",
			"currentHolderId":    u.UserID,
			"sealedAt":           rfc3339(now),
			"handlingCompliant":  compliant,
		}, nil
	})
}

func (app *App) handleConfirmLabReceipt(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u.ActiveRole != RoleLaboratoryTeam && !u.isDispatcher() {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			SampleID     string `json:"sampleId"`
			LaboratoryID string `json:"laboratoryId"`
			ReceivedAt   string `json:"receivedAt"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		at, err := parseTime(req.ReceivedAt)
		if err != nil {
			return 0, nil, herr(400, "invalid_time", "invalid receivedAt")
		}
		s, err := app.loadSample(r.Context(), req.SampleID)
		if err != nil {
			return 0, nil, err
		}
		if u.ActiveRole == RoleLaboratoryTeam && u.AssignedLocationID != "" && u.AssignedLocationID != req.LaboratoryID {
			return 0, nil, herr(403, "wrong_laboratory_operator", "wrong laboratory")
		}
		if s.TargetLabID != nil && *s.TargetLabID != req.LaboratoryID {
