UPDATE assignments SET status='completed', completed_at=$2, worker_id=$3
WHERE sample_id=$1 AND kind='laboratory' AND status NOT IN ('completed','cancelled')`, s.ID, at, u.UserID)
		if s.ActiveJourneyID != nil {
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE journeys SET status='completed' WHERE id=$1`, *s.ActiveJourneyID)
			app.releaseJourneyCapacity(r.Context(), *s.ActiveJourneyID)
		}
		app.audit(r.Context(), u.UserID, u.ActiveRole, "confirm_laboratory_receipt", "sample", s.ID, true, map[string]interface{}{"laboratoryId": req.LaboratoryID})
		app.emit("sample.received", "sample", s.ID, map[string]interface{}{"laboratoryId": req.LaboratoryID})
		return 201, map[string]interface{}{
			"sampleId":     s.ID,
			"laboratoryId": req.LaboratoryID,
			"status":       "received",
			"receivedAt":   rfc3339(at),
		}, nil
	})
}

