func (app *App) handleRecordCheckpoint(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			SampleID             string  `json:"sampleId"`
			AssignmentID         string  `json:"assignmentId"`
			LocationID           string  `json:"locationId"`
			ContainerType        string  `json:"containerType"`
			ObservedTemperatureC float64 `json:"observedTemperatureC"`
			RecordedAt           string  `json:"recordedAt"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		at, err := parseTime(req.RecordedAt)
		if err != nil {
			return 0, nil, herr(400, "invalid_time", "invalid recordedAt")
		}
		s, err := app.loadSample(r.Context(), req.SampleID)
		if err != nil {
			return 0, nil, err
		}
		if s.Status == "received" || s.Status == "cancelled" {
			return 0, nil, herr(409, "terminal_sample", "sample is terminal")
		}
		if s.CurrentHolderID == nil || *s.CurrentHolderID != u.UserID {
			if !u.isDispatcher() {
				return 0, nil, herr(403, "forbidden", "not current holder")
			}
		}
		compliant := req.ObservedTemperatureC >= s.TempMin && req.ObservedTemperatureC <= s.TempMax
		if req.ContainerType != "" && s.ContainerType != "" && req.ContainerType != s.ContainerType {
			compliant = false
		}
		cid := newUUID()
		_, _ = app.store.pg.Exec(r.Context(), `
INSERT INTO checkpoints (id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, recorded_at, compliant)
VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`, cid, s.ID, req.AssignmentID, nilIfEmpty(req.LocationID), req.ContainerType, req.ObservedTemperatureC, at, compliant)
		status := s.Status
		if !compliant {
			status = "exception"
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET status='exception', exception=$2 WHERE id=$1`, s.ID,
				asJSON(map[string]interface{}{"reason": "handling_violation", "checkpointId": cid}))
			_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO exceptions (id, sample_id, reason, observed_at) VALUES ($1,$2,$3,$4)`,
				newUUID(), s.ID, "handling_violation", at)
		}
		app.audit(r.Context(), u.UserID, u.ActiveRole, "record_handling_checkpoint", "sample", s.ID, true, map[string]interface{}{"compliant": compliant})
		return 201, map[string]interface{}{
			"checkpointId": cid,
			"sampleId":     s.ID,
			"compliant":    compliant,
			"sampleStatus": status,
		}, nil
	})
}
