func (app *App) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	var req struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	_ = decodeBody(body, &req)
	if req.Role != "" && req.Role != u.ActiveRole && !u.isDispatcher() {
		writeErr(w, 400, "invalid_role", "role does not match active role")
		return
	}
	role := u.ActiveRole
	if req.Role != "" && u.isDispatcher() {
		role = req.Role
	}
	pending, inProg, completed := app.roleWork(r.Context(), u, role)
	if req.Status != "" {
		switch req.Status {
		case "pending":
			inProg, completed = []map[string]interface{}{}, []map[string]interface{}{}
		case "in_progress", "accepted", "inProgress":
			pending, completed = []map[string]interface{}{}, []map[string]interface{}{}
		case "completed", "past":
			pending, inProg = []map[string]interface{}{}, []map[string]interface{}{}
		}
	}
	writeData(w, 200, map[string]interface{}{
		"role":      role,
		"pending":   pending,
		"inProgress": inProg,
		"completed": completed,
	})
