func (app *App) roleWork(ctx context.Context, u *SessionUser, role string) (pending, inProg, completed []map[string]interface{}) {
	pending, inProg, completed = []map[string]interface{}{}, []map[string]interface{}{}, []map[string]interface{}{}
	now := time.Now()
	if role == RoleRequester {
		rows, err := app.store.pg.Query(ctx, `SELECT id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, u.UserID)
		if err != nil {
			return
		}
		defer rows.Close()
		for rows.Next() {
			var id string
			if rows.Scan(&id) != nil {
				continue
			}
			s, err := app.loadSample(ctx, id)
			if err != nil {
				continue
			}
			item := app.sampleWorkItem(ctx, s, now)
			switch s.Status {
			case "received", "cancelled", "expired":
				completed = append(completed, item)
			case "requested":
				pending = append(pending, item)
			default:
				inProg = append(inProg, item)
			}
		}
		return
	}
	if role == RoleDispatcher || role == RoleAdministrator {
		rows, err := app.store.pg.Query(ctx, `SELECT id FROM samples ORDER BY created_at DESC LIMIT 300`)
		if err != nil {
			return
		}
		defer rows.Close()
		for rows.Next() {
			var id string
			if rows.Scan(&id) != nil {
				continue
			}
			s, err := app.loadSample(ctx, id)
			if err != nil {
				continue
			}
			item := app.sampleWorkItem(ctx, s, now)
			switch s.Status {
			case "received", "cancelled", "expired":
				completed = append(completed, item)
			case "requested":
				pending = append(pending, item)
			default:
				inProg = append(inProg, item)
			}
		}
		return
	}
	// worker assignments
	rows, err := app.store.pg.Query(ctx, `
SELECT id FROM assignments
WHERE worker_id=$1 OR offered_to=$1
ORDER BY created_at DESC`, u.UserID)
	if err != nil {
		return
	}
	defer rows.Close()
	for rows.Next() {
		var id string
		if rows.Scan(&id) != nil {
			continue
		}
		item, status, ok := app.assignmentWorkItem(ctx, id)
		if !ok {
			continue
		}
		switch status {
		case "completed", "cancelled":
			completed = append(completed, item)
		case "accepted", "in_progress", "at_pickup", "picked_up", "in_transit", "arrived", "delivered":
			inProg = append(inProg, item)
		default:
			pending = append(pending, item)
		}
	}
	return
}

func (app *App) sampleWorkItem(ctx context.Context, s *sampleRow, now time.Time) map[string]interface{} {
	ids := []string{s.ID, s.RequestID}
	hist := app.loadTimeline(ctx, ids...)
	if hist == nil {
		hist = []map[string]interface{}{}
	}
	item := map[string]interface{}{
		"kind":          "sample",
		"sampleId":      s.ID,
		"sample_id":     s.ID,
		"requestId":     s.RequestID,
		"status":        s.Status,
		"serviceability": s.Serviceability,
		"requestedAt":   rfc3339(s.RequestedAt),
		"deliveryDeadline": rfc3339(s.Deadline),
		"earliestCollectionAt": rfc3339(s.Earliest),
		"latestCollectionAt": rfc3339(s.Latest),
		"requesterId":   s.RequesterID,
		"history":       hist,
		"locationStale": isStale(s.LocationRecordedAt, now),
	}
	if s.ActiveJourneyID != nil {
		item["journeyId"] = *s.ActiveJourneyID
		item["activeJourneyId"] = *s.ActiveJourneyID
	}
	if s.TargetLabID != nil {
		item["laboratoryId"] = *s.TargetLabID
	}
	if s.CurrentHolderID != nil {
		item["currentHolderId"] = *s.CurrentHolderID
	}
	if s.LocationRecordedAt != nil {
		item["locationRecordedAt"] = rfc3339(*s.LocationRecordedAt)
	}
	return item
}

