			return 0, nil, herr(409, "offer_not_available", "offer not available")
		}
		_, err = app.store.pg.Exec(r.Context(), `
UPDATE assignments SET status='accepted', worker_id=$2, accepted_at=now(), offered_to=NULL WHERE id=$1`, req.AssignmentID, u.UserID)
		if err != nil {
			return 0, nil, err
		}
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE users SET last_assigned_at=now() WHERE id=$1`, u.UserID)
		app.audit(r.Context(), u.UserID, u.ActiveRole, "accept_assignment", "assignment", req.AssignmentID, true, nil)
		app.emit("assignment.accepted", "assignment", req.AssignmentID, map[string]interface{}{"workerId": u.UserID})
		return 201, map[string]interface{}{
			"assignmentId": req.AssignmentID,
			"workerId":     u.UserID,
			"status":       "accepted",
		}, nil
	})
}

func (app *App) handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			AssignmentID string `json:"assignmentId"`
			Reason       string `json:"reason"`
			DeclinedAt   string `json:"declinedAt"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		at := time.Now().UTC()
		if req.DeclinedAt != "" {
			t, err := parseTime(req.DeclinedAt)
			if err != nil {
				return 0, nil, herr(400, "invalid_time", "invalid declinedAt")
			}
			at = t
		}
		var status string
		var offered *string
		err := app.store.pg.QueryRow(r.Context(), `SELECT status, offered_to FROM assignments WHERE id=$1`, req.AssignmentID).
			Scan(&status, &offered)
		if err != nil {
			return 0, nil, herr(404, "not_found", "assignment not found")
		}
		if offered == nil || *offered != u.UserID {
			if !u.isDispatcher() {
				return 0, nil, herr(409, "offer_not_available", "offer not available")
			}
		}
		_, _ = app.store.pg.Exec(r.Context(), `
UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL, declined_by=$2, declined_at=$3 WHERE id=$1`,
			req.AssignmentID, u.UserID, at)
		_, _ = app.store.pg.Exec(r.Context(), `
UPDATE users SET decline_count = decline_count + 1, decline_penalty_until=$2 WHERE id=$1`,
			u.UserID, time.Now().Add(declinePenalty))
		next := app.offerOne(r.Context(), req.AssignmentID)
		app.audit(r.Context(), u.UserID, u.ActiveRole, "decline_assignment", "assignment", req.AssignmentID, true, map[string]interface{}{"reason": req.Reason})
		out := map[string]interface{}{
			"assignmentId": req.AssignmentID,
			"status":       "pending",
			"declinedBy":   u.UserID,
			"declinedAt":   rfc3339(at),
		}
		if next != "" {
			out["reofferedTo"] = next
		}
		return 201, out, nil
	})
}

func (app *App) handleUpdateProgress(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			AssignmentID string `json:"assignmentId"`
			Status       string `json:"status"`
			OccurredAt   string `json:"occurredAt"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		at, err := parseTime(req.OccurredAt)
		if err != nil {
			return 0, nil, herr(400, "invalid_time", "invalid occurredAt")
		}
		allowed := map[string]bool{"at_pickup": true, "picked_up": true, "in_transit": true, "arrived": true, "delivered": true, "in_progress": true, "completed": true}
		if !allowed[req.Status] {
			return 0, nil, herr(400, "invalid_json", "invalid status")
		}
		var sampleID *string
		var worker *string
		var status string
		err = app.store.pg.QueryRow(r.Context(), `SELECT sample_id, worker_id, status FROM assignments WHERE id=$1`, req.AssignmentID).
			Scan(&sampleID, &worker, &status)
		if err != nil {
			return 0, nil, herr(404, "not_found", "assignment not found")
		}
		if !u.isDispatcher() && (worker == nil || *worker != u.UserID) {
			return 0, nil, herr(403, "forbidden", "not assigned worker")
		}
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET status=$2, completed_at=CASE WHEN $2 IN ('completed','delivered') THEN $3 ELSE completed_at END WHERE id=$1`,
			req.AssignmentID, req.Status, at)
		sid := ""
		if sampleID != nil {
			sid = *sampleID
			if req.Status == "picked_up" || req.Status == "in_transit" {
				_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET status='in_transit', current_holder_id=$2 WHERE id=$1`, sid, u.UserID)
			}
		}
		app.audit(r.Context(), u.UserID, u.ActiveRole, "update_assignment_progress", "assignment", req.AssignmentID, true, map[string]interface{}{"status": req.Status})
		app.emit("assignment.progress", "assignment", req.AssignmentID, map[string]interface{}{"status": req.Status})
		return 201, map[string]interface{}{
			"assignmentId": req.AssignmentID,
			"sampleId":     sid,
			"status":       req.Status,
		}, nil
	})
}

func (app *App) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	var req struct {
		AssignmentID string `json:"assignmentId"`
		Coordinate   Coord  `json:"coordinate"`
		Sequence     int    `json:"sequence"`
		RecordedAt   string `json:"recordedAt"`
	}
	if err := decodeBody(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.Sequence < 1 {
		writeErr(w, 400, "invalid_sequence", "invalid sequence")
		return
	}
	at, err := parseTime(req.RecordedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid recordedAt")
		return
	}
	var worker, sampleID *string
	err = app.store.pg.QueryRow(r.Context(), `SELECT worker_id, sample_id FROM assignments WHERE id=$1`, req.AssignmentID).Scan(&worker, &sampleID)
	if err != nil {
		writeErr(w, 404, "not_found", "assignment not found")
		return
	}
	if !u.isDispatcher() && (worker == nil || *worker != u.UserID) {
		writeErr(w, 403, "forbidden", "not assigned worker")
		return
	}
	var maxSeq int
	_ = app.store.pg.QueryRow(r.Context(), `SELECT COALESCE(MAX(sequence),0) FROM worker_location_updates WHERE assignment_id=$1`, req.AssignmentID).Scan(&maxSeq)
	if req.Sequence <= maxSeq {
		writeErr(w, 409, "stale_location", "stale location sequence")
		return
	}
	_, err = app.store.pg.Exec(r.Context(), `
INSERT INTO worker_location_updates (id, worker_id, assignment_id, latitude, longitude, sequence, recorded_at)
VALUES ($1,$2,$3,$4,$5,$6,$7)`, newUUID(), u.UserID, req.AssignmentID, req.Coordinate.Latitude, req.Coordinate.Longitude, req.Sequence, at)
	if err != nil {
		writeErr(w, 409, "concurrent_conflict", "location conflict")
		return
	}
	_, _ = app.store.pg.Exec(r.Context(), `UPDATE users SET latest_lat=$2, latest_lng=$3, location_recorded_at=$4 WHERE id=$1`,
		u.UserID, req.Coordinate.Latitude, req.Coordinate.Longitude, at)
	if sampleID != nil {
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET latest_lat=$2, latest_lng=$3, location_recorded_at=$4 WHERE id=$1`,
			*sampleID, req.Coordinate.Latitude, req.Coordinate.Longitude, at)
	}
	app.audit(r.Context(), u.UserID, u.ActiveRole, "record_worker_location", "assignment", req.AssignmentID, true, map[string]interface{}{"sequence": req.Sequence})
	app.emit("worker.location", "assignment", req.AssignmentID, map[string]interface{}{"coordinate": req.Coordinate})
	writeData(w, 201, map[string]interface{}{
		"assignmentId": req.AssignmentID,
		"coordinate":   req.Coordinate,
		"sequence":     req.Sequence,
		"recordedAt":   rfc3339(at),
	})
}

func (app *App) handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
