	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			SampleID         string `json:"sampleId"`
			FromAssignmentID string `json:"fromAssignmentId"`
			ToAssignmentID   string `json:"toAssignmentId"`
			ReceiverID       string `json:"receiverId"`
			InitiatedAt      string `json:"initiatedAt"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		at, err := parseTime(req.InitiatedAt)
		if err != nil {
			return 0, nil, herr(400, "invalid_time", "invalid initiatedAt")
		}
		s, err := app.loadSample(r.Context(), req.SampleID)
		if err != nil {
			return 0, nil, err
		}
		if s.CurrentHolderID == nil || *s.CurrentHolderID != u.UserID {
			if !u.isDispatcher() {
				return 0, nil, herr(409, "not_current_holder", "not current holder")
			}
		}
		var pending string
		_ = app.store.pg.QueryRow(r.Context(), `SELECT id FROM handoffs WHERE sample_id=$1 AND status='pending' LIMIT 1`, s.ID).Scan(&pending)
		if pending != "" {
			return 0, nil, herr(409, "pending_handoff_exists", "pending handoff exists")
		}
		hid := newUUID()
		_, err = app.store.pg.Exec(r.Context(), `
INSERT INTO handoffs (id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, initiated_at)
VALUES ($1,$2,$3,$4,$5,$6,'pending',$7)`, hid, s.ID, req.FromAssignmentID, req.ToAssignmentID, u.UserID, req.ReceiverID, at)
		if err != nil {
			return 0, nil, err
		}
		app.audit(r.Context(), u.UserID, u.ActiveRole, "initiate_handoff", "handoff", hid, true, map[string]interface{}{"sampleId": s.ID})
		return 201, map[string]interface{}{
			"handoffId":       hid,
			"senderId":        u.UserID,
			"receiverId":      req.ReceiverID,
			"currentHolderId": ptrStr(s.CurrentHolderID),
			"status":          "pending",
		}, nil
	})
}

func (app *App) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			HandoffID         string `json:"handoffId"`
			ConfirmationSide  string `json:"confirmationSide"`
			ConfirmedAt       string `json:"confirmedAt"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		if req.ConfirmationSide != "sender" && req.ConfirmationSide != "receiver" {
			return 0, nil, herr(400, "invalid_json", "invalid confirmationSide")
		}
		at, err := parseTime(req.ConfirmedAt)
		if err != nil {
			return 0, nil, herr(400, "invalid_time", "invalid confirmedAt")
		}
		var sampleID, sender, receiver, status string
		var sConf, rConf bool
		err = app.store.pg.QueryRow(r.Context(), `
SELECT sample_id, sender_id, receiver_id, status, sender_confirmed, receiver_confirmed
FROM handoffs WHERE id=$1`, req.HandoffID).Scan(&sampleID, &sender, &receiver, &status, &sConf, &rConf)
		if err != nil {
			return 0, nil, herr(404, "not_found", "handoff not found")
		}
		if req.ConfirmationSide == "sender" {
			if !u.isDispatcher() && u.UserID != sender {
				return 0, nil, herr(403, "forbidden", "not sender")
			}
			sConf = true
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE handoffs SET sender_confirmed=TRUE WHERE id=$1`, req.HandoffID)
		} else {
			if !u.isDispatcher() && u.UserID != receiver {
				return 0, nil, herr(403, "forbidden", "not receiver")
			}
			rConf = true
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE handoffs SET receiver_confirmed=TRUE WHERE id=$1`, req.HandoffID)
		}
		holder := sender
		st := "pending"
		if sConf && rConf {
			st = "confirmed"
			holder = receiver
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE handoffs SET status='confirmed', completed_at=$2 WHERE id=$1`, req.HandoffID, at)
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET current_holder_id=$2 WHERE id=$1`, sampleID, receiver)
		}
		app.audit(r.Context(), u.UserID, u.ActiveRole, "confirm_handoff", "handoff", req.HandoffID, true, map[string]interface{}{"side": req.ConfirmationSide})
		return 201, map[string]interface{}{
			"handoffId":          req.HandoffID,
			"status":             st,
			"senderConfirmed":    sConf,
			"receiverConfirmed":  rConf,
			"currentHolderId":    holder,
		}, nil
	})
}

func (app *App) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	var req struct {
		JourneyID string `json:"journeyId"`
	}
	if err := decodeBody(body, &req); err != nil || req.JourneyID == "" {
		writeErr(w, 400, "invalid_json", "journeyId required")
		return
	}
	payload, err := app.journeyPlanPayload(r.Context(), req.JourneyID, u.ActiveRole, u.UserID)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	// requester may only see journeys of their samples
	if u.ActiveRole == RoleRequester {
		sids := app.journeySampleIDs(r.Context(), req.JourneyID)
		ok := false
		for _, sid := range sids {
			s, err := app.loadSample(r.Context(), sid)
			if err == nil && s.RequesterID == u.UserID {
				ok = true
				break
			}
		}
		if !ok {
			writeErr(w, 403, "forbidden", "forbidden")
			return
		}
	}
	writeData(w, 200, payload)
}

func (app *App) bumpPlan(ctx context.Context, journeyID string, expected int) error {
	var ver int
	var status string
	err := app.store.pg.QueryRow(ctx, `SELECT plan_version, status FROM journeys WHERE id=$1`, journeyID).Scan(&ver, &status)
	if err != nil {
		return herr(404, "not_found", "journey not found")
	}
	if expected > 0 && ver != expected {
		return herr(409, "stale_plan", "stale plan version")
	}
	if status == "completed" || status == "cancelled" {
		return herr(409, "inactive_plan", "inactive plan")
	}
	_, err = app.store.pg.Exec(ctx, `UPDATE journeys SET plan_version = plan_version + 1 WHERE id=$1 AND plan_version=$2`, journeyID, ver)
	if err != nil {
		return herr(409, "concurrent_conflict", "concurrent conflict")
	}
	return nil
}

func (app *App) handleCancelJourney(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if !u.isDispatcher() {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			JourneyID            string `json:"journeyId"`
			ExpectedPlanVersion  int    `json:"expectedPlanVersion"`
			Reason               string `json:"reason"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		if req.ExpectedPlanVersion < 1 {
			return 0, nil, herr(400, "invalid_plan_version", "invalid plan version")
		}
		if err := app.bumpPlan(r.Context(), req.JourneyID, req.ExpectedPlanVersion); err != nil {
			return 0, nil, err
		}
		sids := app.journeySampleIDs(r.Context(), req.JourneyID)
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE journeys SET status='cancelled' WHERE id=$1`, req.JourneyID)
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, req.JourneyID)
		for _, sid := range sids {
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET status='cancelled' WHERE id=$1 AND status NOT IN ('received')`, sid)
		}
		app.releaseJourneyCapacity(r.Context(), req.JourneyID)
		app.audit(r.Context(), u.UserID, u.ActiveRole, "cancel_journey", "journey", req.JourneyID, true, map[string]interface{}{"reason": req.Reason})
		return 201, map[string]interface{}{
			"journeyId": req.JourneyID,
			"status":    "cancelled",
			"sampleIds": sids,
		}, nil
	})
}

func (app *App) handleSplitJourney(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if !u.isDispatcher() {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			JourneyID           string   `json:"journeyId"`
			ExpectedPlanVersion int      `json:"expectedPlanVersion"`
			SampleIDs           []string `json:"sampleIds"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		if err := app.bumpPlan(r.Context(), req.JourneyID, req.ExpectedPlanVersion); err != nil {
			return 0, nil, err
		}
		all := app.journeySampleIDs(r.Context(), req.JourneyID)
		if len(req.SampleIDs) == 0 || len(req.SampleIDs) >= len(all) {
			return 0, nil, herr(409, "invalid_split", "invalid split")
		}
		newID := newUUID()
		_, err := app.store.pg.Exec(r.Context(), `
INSERT INTO journeys (id, parent_journey_id, plan_version, route_mode, status, total_cost_units, valid)
SELECT $1, $2, 1, route_mode, 'planned', total_cost_units, TRUE FROM journeys WHERE id=$2`, newID, req.JourneyID)
		if err != nil {
			return 0, nil, err
		}
		for _, sid := range req.SampleIDs {
			_, _ = app.store.pg.Exec(r.Context(), `DELETE FROM journey_samples WHERE journey_id=$1 AND sample_id=$2`, req.JourneyID, sid)
			_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2)`, newID, sid)
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET active_journey_id=$2 WHERE id=$1`, sid, newID)
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET journey_id=$2 WHERE sample_id=$1 AND journey_id=$3 AND status NOT IN ('completed')`, sid, newID, req.JourneyID)
		}
		orig, _ := app.journeyPlanPayload(r.Context(), req.JourneyID, u.ActiveRole, u.UserID)
		split, _ := app.journeyPlanPayload(r.Context(), newID, u.ActiveRole, u.UserID)
		app.audit(r.Context(), u.UserID, u.ActiveRole, "split_journey", "journey", req.JourneyID, true, map[string]interface{}{"splitJourneyId": newID})
		return 201, map[string]interface{}{"journey": orig, "splitJourney": split}, nil
	})
}

func (app *App) handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if !u.isDispatcher() {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			TargetJourneyID     string   `json:"targetJourneyId"`
			ExpectedPlanVersion int      `json:"expectedPlanVersion"`
			SourceJourneyIDs    []string `json:"sourceJourneyIds"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		if err := app.bumpPlan(r.Context(), req.TargetJourneyID, req.ExpectedPlanVersion); err != nil {
			return 0, nil, err
		}
		// pulse cannot batch
		targetSamples := app.journeySampleIDs(r.Context(), req.TargetJourneyID)
		types := map[string]*sampleTypeRow{}
		checkPulse := func(sids []string) error {
			for _, sid := range sids {
				s, err := app.loadSample(r.Context(), sid)
				if err != nil {
					continue
				}
				st, _ := app.loadSampleType(r.Context(), s.SampleTypeID)
				if st != nil {
					types[st.ID] = st
					if !st.BatchingAllowed {
						return herr(409, "pulse_no_batch", "pulse cannot be batched")
					}
				}
			}
			return nil
		}
		if err := checkPulse(targetSamples); err != nil {
			return 0, nil, err
		}
		for _, src := range req.SourceJourneyIDs {
			sids := app.journeySampleIDs(r.Context(), src)
			if err := checkPulse(sids); err != nil {
				return 0, nil, err
			}
			// incompatibilities
			for _, sid := range sids {
				s, _ := app.loadSample(r.Context(), sid)
				if s == nil {
					continue
				}
				for _, tid := range targetSamples {
					t, _ := app.loadSample(r.Context(), tid)
					if t == nil {
						continue
					}
					if contains(s.Incompatible, t.SampleTypeID) || contains(t.Incompatible, s.SampleTypeID) {
						return 0, nil, herr(409, "incompatible_batch", "incompatible samples")
					}
				}
				_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, req.TargetJourneyID, sid)
				_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET active_journey_id=$2 WHERE id=$1`, sid, req.TargetJourneyID)
				_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET journey_id=$2 WHERE sample_id=$1 AND journey_id=$3 AND status NOT IN ('completed')`, sid, req.TargetJourneyID, src)
			}
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE journeys SET status='cancelled' WHERE id=$1`, src)
		}
		payload, err := app.journeyPlanPayload(r.Context(), req.TargetJourneyID, u.ActiveRole, u.UserID)
		if err != nil {
			return 0, nil, err
		}
		app.audit(r.Context(), u.UserID, u.ActiveRole, "merge_journeys", "journey", req.TargetJourneyID, true, map[string]interface{}{"sources": req.SourceJourneyIDs})
		return 201, payload, nil
	})
}

func (app *App) handleRerouteJourney(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
