		if err := app.bumpPlan(r.Context(), req.JourneyID, req.ExpectedPlanVersion); err != nil {
			return 0, nil, err
		}
		status, replacement, err := app.replanJourney(r.Context(), u, req.JourneyID)
		if err != nil {
			return 0, nil, err
		}
		out := map[string]interface{}{"journeyId": req.JourneyID, "replanStatus": status}
		if replacement != "" {
			out["replacementPlanId"] = replacement
			plan, _ := app.journeyPlanPayload(r.Context(), replacement, u.ActiveRole, u.UserID)
			out["replacementJourney"] = plan
		}
		app.audit(r.Context(), u.UserID, u.ActiveRole, "reroute_journey", "journey", req.JourneyID, true, map[string]interface{}{"status": status})
		return 201, out, nil
	})
}

func (app *App) handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if !u.isDispatcher() {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			JourneyID           string                 `json:"journeyId"`
			ExpectedPlanVersion int                    `json:"expectedPlanVersion"`
			ChangeType          string                 `json:"changeType"`
			Changes             map[string]interface{} `json:"changes"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		valid := map[string]bool{
			"add_stop": true, "remove_stop": true, "reorder_stops": true, "replace_worker": true,
			"reassign_worker": true, "merge_samples": true, "split_samples": true, "split_batch": true,
			"cancel_work": true, "reroute": true, "replace_route": true,
		}
		if !valid[req.ChangeType] {
			return 0, nil, herr(400, "invalid_change_type", "invalid change type")
		}
		if err := app.bumpPlan(r.Context(), req.JourneyID, req.ExpectedPlanVersion); err != nil {
			return 0, nil, err
		}
		switch req.ChangeType {
		case "cancel_work":
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE journeys SET status='cancelled' WHERE id=$1`, req.JourneyID)
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, req.JourneyID)
		case "reroute", "replace_route":
			_, _, _ = app.replanJourney(r.Context(), u, req.JourneyID)
		case "replace_worker", "reassign_worker":
			if wid, _ := req.Changes["workerId"].(string); wid != "" {
				if aid, _ := req.Changes["assignmentId"].(string); aid != "" {
					_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET worker_id=$2, offered_to=$2, status='offered' WHERE id=$1 AND status NOT IN ('completed','cancelled')`, aid, wid)
				}
			}
		}
		payload, err := app.journeyPlanPayload(r.Context(), req.JourneyID, u.ActiveRole, u.UserID)
		if err != nil {
			return 0, nil, err
		}
		app.audit(r.Context(), u.UserID, u.ActiveRole, "edit_active_plan", "journey", req.JourneyID, true, map[string]interface{}{"changeType": req.ChangeType})
		return 201, payload, nil
	})
}

func (app *App) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if !u.isDispatcher() {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			ResourceType string `json:"resourceType"`
			ResourceID   string `json:"resourceId"`
			Reason       string `json:"reason"`
			OccurredAt   string `json:"occurredAt"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		valid := map[string]bool{"location": true, "node": true, "laboratory": true, "connection": true, "route": true, "worker": true, "capacity": true}
		if !valid[req.ResourceType] {
			return 0, nil, herr(400, "invalid_resource_type", "invalid resource type")
		}
		at, err := parseTime(req.OccurredAt)
		if err != nil {
			return 0, nil, herr(400, "invalid_time", "invalid occurredAt")
		}
		// mark resource unavailable
		switch req.ResourceType {
		case "location", "node", "laboratory":
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE locations SET active=FALSE WHERE id=$1`, req.ResourceID)
		case "connection", "route":
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE connections SET active=FALSE WHERE id=$1`, req.ResourceID)
		case "worker":
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE users SET available=FALSE WHERE id=$1`, req.ResourceID)
		}
		app.bumpNetwork(r.Context())
		affected := []string{}
		replacements := []string{}
		replanStatus := "not_required"
		// find journeys touching this resource
		var q string
		switch req.ResourceType {
		case "location", "node", "laboratory":
			q = `SELECT DISTINCT journey_id FROM assignments WHERE (from_location_id=$1 OR to_location_id=$1 OR node_id=$1 OR laboratory_id=$1) AND status NOT IN ('completed','cancelled')`
		case "connection", "route":
			q = `SELECT DISTINCT a.journey_id FROM assignments a JOIN connections c ON c.from_location_id=a.from_location_id AND c.to_location_id=a.to_location_id WHERE c.id=$1 AND a.status NOT IN ('completed','cancelled')`
		case "worker":
			q = `SELECT DISTINCT journey_id FROM assignments WHERE worker_id=$1 AND status NOT IN ('completed','cancelled')`
		default:
			q = `SELECT DISTINCT journey_id FROM capacity_reservations WHERE resource_id=$1 AND active=TRUE`
		}
		rows, err := app.store.pg.Query(r.Context(), q, req.ResourceID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var jid string
				if rows.Scan(&jid) != nil {
					continue
				}
				st, repl, _ := app.replanJourney(r.Context(), u, jid)
				sids := app.journeySampleIDs(r.Context(), jid)
				affected = append(affected, sids...)
				if repl != "" {
					replacements = append(replacements, repl)
				}
				if st != "not_required" {
					replanStatus = st
				}
			}
		}
		did := newUUID()
		_, _ = app.store.pg.Exec(r.Context(), `
INSERT INTO disruptions (id, resource_type, resource_id, reason, occurred_at, replan_status)
VALUES ($1,$2,$3,$4,$5,$6)`, did, req.ResourceType, req.ResourceID, req.Reason, at, replanStatus)
		app.audit(r.Context(), u.UserID, u.ActiveRole, "report_disruption", req.ResourceType, req.ResourceID, true, map[string]interface{}{"reason": req.Reason})
		return 201, map[string]interface{}{
			"disruptionId":       did,
			"affectedSampleIds":  affected,
			"replacementPlanIds": replacements,
			"replanStatus":       replanStatus,
		}, nil
	})
}

func (app *App) replanJourney(ctx context.Context, u *SessionUser, journeyID string) (string, string, error) {
	sids := app.journeySampleIDs(ctx, journeyID)
	if len(sids) == 0 {
		return "not_required", "", nil
	}
	// cancel unfinished assignments, keep completed
	_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, journeyID)
	app.releaseJourneyCapacity(ctx, journeyID)
	_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET status='superseded', replan_status='replaced' WHERE id=$1`, journeyID)

	// replan first unfinished sample (and attach others if possible)
	var lastStatus, lastID string
	for _, sid := range sids {
		s, err := app.loadSample(ctx, sid)
		if err != nil || s.Status == "received" || s.Status == "cancelled" {
			continue
		}
		st, _ := app.loadSampleType(ctx, s.SampleTypeID)
		plan, err := app.evaluateServiceability(ctx, Coord{s.OriginLat, s.OriginLng}, s.OriginType, "", s.SampleTypeID, time.Now(), s.Deadline, s.Earliest, s.Latest)
		if err != nil || !plan.Serviceable {
			reason := "no_valid_route"
			status := "exception"
			if plan != nil && plan.Reason == "deadline_unreachable" {
				status = "expired"
				reason = "deadline_unreachable"
			}
			_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status=$2, exception=$3 WHERE id=$1`, sid, status, asJSON(map[string]interface{}{"reason": reason}))
			if status == "expired" {
				lastStatus = "expired"
			} else {
				lastStatus = "exception"
			}
			continue
		}
		req := collectionReqBody{
			Origin: Coord{s.OriginLat, s.OriginLng}, OriginType: s.OriginType, SampleTypeID: s.SampleTypeID,
			ContainerType: s.ContainerType, TemperatureMinC: s.TempMin, TemperatureMaxC: s.TempMax,
		}
		jid, _, err := app.materializeJourney(ctx, u, sid, req, plan, st, s.Sealed, time.Now())
		if err != nil {
			lastStatus = "exception"
			continue
		}
		_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET parent_journey_id=$2 WHERE id=$1`, jid, journeyID)
		_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET active_journey_id=$2, target_laboratory_id=$3 WHERE id=$1`, sid, jid, plan.TargetLab)
		lastStatus = "replaced"
		lastID = jid
	}
	if lastStatus == "" {
		lastStatus = "not_required"
	}
	return lastStatus, lastID, nil
}

func (app *App) offerAssignments(ctx context.Context) {
	// expire stale offers
	_, _ = app.store.pg.Exec(ctx, `
UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL
WHERE status='offered' AND offer_expires_at IS NOT NULL AND offer_expires_at < now()`)
	rows, err := app.store.pg.Query(ctx, `SELECT id FROM assignments WHERE status='pending' AND worker_id IS NULL`)
	if err != nil {
		return
	}
	defer rows.Close()
	for rows.Next() {
		var id string
		if rows.Scan(&id) == nil {
			app.offerOne(ctx, id)
		}
	}
}

func (app *App) offerOne(ctx context.Context, assignmentID string) string {
	var kind string
	var sampleID, nodeID, labID *string
	var expected *string
	err := app.store.pg.QueryRow(ctx, `SELECT kind, sample_id, node_id, laboratory_id, expected_sample_type_id FROM assignments WHERE id=$1`, assignmentID).
		Scan(&kind, &sampleID, &nodeID, &labID, &expected)
	if err != nil {
		return ""
	}
	role := RoleDeliveryPartner
	switch kind {
	case "collection":
		role = RoleCollectionProfessional
	case "node":
		role = RoleNodeHandler
	case "laboratory":
		role = RoleLaboratoryTeam
	}
	q := `
SELECT u.id FROM users u
JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1
WHERE u.active=TRUE AND u.available=TRUE
  AND (u.decline_penalty_until IS NULL OR u.decline_penalty_until < now())
`
	args := []interface{}{role}
	if (kind == "node" || kind == "laboratory") && (nodeID != nil || labID != nil) {
		loc := ""
		if nodeID != nil {
			loc = *nodeID
		}
		if labID != nil {
			loc = *labID
		}
		q += ` AND u.assigned_location_id=$2`
		args = append(args, loc)
	}
	q += ` ORDER BY COALESCE(u.last_offered_at, to_timestamp(0)) ASC, COALESCE(u.last_assigned_at, to_timestamp(0)) ASC,
  (SELECT COUNT(*) FROM assignments a WHERE a.worker_id=u.id AND a.status NOT IN ('completed','cancelled')) ASC
LIMIT 5`
	wrows, err := app.store.pg.Query(ctx, q, args...)
	if err != nil {
		return ""
	}
	defer wrows.Close()
	var candidates []string
	for wrows.Next() {
		var id string
		if wrows.Scan(&id) == nil {
			candidates = append(candidates, id)
		}
	}
	if len(candidates) == 0 {
		if kind == "collection" && expected != nil {
			// no qualified collector — flag after timeout; we flag immediately only if never anyone
			var n int
			_ = app.store.pg.QueryRow(ctx, `SELECT COUNT(*) FROM users u JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1 WHERE u.active`, RoleCollectionProfessional).Scan(&n)
			if n == 0 && sampleID != nil {
				_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status='exception', exception=$2 WHERE id=$1 AND status NOT IN ('received','cancelled')`,
					*sampleID, asJSON(map[string]interface{}{"reason": "no_qualified_worker"}))
				_, _ = app.store.pg.Exec(ctx, `INSERT INTO exceptions (id, sample_id, reason, observed_at) VALUES ($1,$2,$3,now())`,
					newUUID(), *sampleID, "no_qualified_worker")
			}
		}
		return ""
	}
	// qualification filter for collection
	chosen := candidates[0]
	if kind == "collection" && expected != nil {
		st, _ := app.loadSampleType(ctx, *expected)
		if st != nil && st.QualifiedCollector {
			found := ""
			for _, cid := range candidates {
				wu, err := app.loadUser(ctx, cid, "")
				if err != nil {
					continue
				}
				if contains(wu.Qualifications, st.RequiredQualification) || hasActiveCert(wu.Certifications, st.RequiredQualification) {
					found = cid
					break
				}
			}
			if found == "" {
				if sampleID != nil {
					// leave pending; background will eventually exception
				}
				return ""
			}
			chosen = found
		}
	}
	exp := time.Now().Add(offerTTL)
	_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='offered', offered_to=$2, offer_expires_at=$3 WHERE id=$1`, assignmentID, chosen, exp)
	_, _ = app.store.pg.Exec(ctx, `UPDATE users SET last_offered_at=now() WHERE id=$1`, chosen)
	app.emit("assignment.offered", "assignment", assignmentID, map[string]interface{}{"workerId": chosen})
	return chosen
}

func (app *App) handleEvents(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if r.Header.Get("Upgrade") == "websocket" || r.Header.Get("Connection") == "Upgrade" {
		app.handleWS(w, r, u)
		return
	}
	since := int64(0)
	if s := r.URL.Query().Get("since"); s != "" {
		var n int64
		if _, err := parseInt64(s, &n); err == nil {
			since = n
		}
	}
	rows, err := app.store.pg.Query(r.Context(), `
SELECT id, type, entity_type, entity_id, payload, created_at
FROM realtime_events WHERE id > $1 ORDER BY id ASC LIMIT 200`, since)
	if err != nil {
		writeErr(w, 500, "internal_error", "internal error")
		return
	}
	defer rows.Close()
	events := []map[string]interface{}{}
	var cursor int64 = since
	for rows.Next() {
		var id int64
		var typ, et, eid string
		var payload []byte
		var created time.Time
		if rows.Scan(&id, &typ, &et, &eid, &payload, &created) != nil {
			continue
		}
		var p map[string]interface{}
		_ = json.Unmarshal(payload, &p)
		if p == nil {
			p = map[string]interface{}{}
		}
		events = append(events, map[string]interface{}{
			"id": id, "type": typ, "entityType": et, "entityId": eid, "payload": p, "createdAt": rfc3339(created),
		})
		cursor = id
	}
	writeData(w, 200, map[string]interface{}{"events": events, "cursor": cursor})
}

func parseInt64(s string, out *int64) (int, error) {
	var n int64
	for _, c := range s {
		if c < '0' || c > '9' {
			return 0, herr(400, "invalid_json", "invalid since")
		}
		n = n*10 + int64(c-'0')
	}
	*out = n
	return 0, nil
}
"}

