		if err != nil {
			log.Fatalf("store: %v", err)
		}
		if err := store.Reset(ctx); err != nil {
			log.Fatalf("reset: %v", err)
		}
		store.Close()
		log.Printf("reset complete")
		return
	}

	store, err := NewStore(ctx, pgURL, mongoURL)
