	}
	p := filepath.Join(app.frontend, filepath.Clean(r.URL.Path))
	if info, err := os.Stat(p); err == nil && !info.IsDir() {
		http.ServeFile(w, r, p)
		return
	}
	index := filepath.Join(app.frontend, "index.html")
	if _, err := os.Stat(index); err == nil {
		http.ServeFile(w, r, index)
		return
	}
	w.Header().Set("Content-Type", "text/html")
	_, _ = w.Write([]byte(`<!doctype html><html><body><p>frontend not built</p></body></html>`))
}

func (app *App) offerLoop() {
	t := time.NewTicker(offerScanInterval)
	defer t.Stop()
	for range t.C {
		app.offerAssignments(context.Background())
	}
}

