}

func (app *App) handleWS(w http.ResponseWriter, r *http.Request, u *SessionUser) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	defer conn.Close()
	ch := app.subscribe()
	defer app.unsubscribe(ch)
	_ = conn.WriteJSON(map[string]interface{}{
		"id": 0, "type": "hello", "entityType": "session", "entityId": u.UserID,
		"payload": map[string]interface{}{"ok": true}, "createdAt": rfc3339(time.Now()),
	})
	for ev := range ch {
		if err := conn.WriteJSON(ev); err != nil {
			return
		}
	}
}
