	h := r.Header.Get("Authorization")
	if strings.HasPrefix(strings.ToLower(h), "bearer ") {
		return strings.TrimSpace(h[7:])
	}
	if tok := tokenFromWSProtocol(r); tok != "" {
		return tok
	}
	return ""
}

func tokenFromWSProtocol(r *http.Request) string {
	raw := r.Header.Get("Sec-WebSocket-Protocol")
	if raw == "" {
		return ""
	}
	for _, p := range strings.Split(raw, ",") {
		p = strings.TrimSpace(p)
		if !strings.HasPrefix(strings.ToLower(p), "bearer.") {
			continue
		}
		enc := p[len("bearer."):]
		if b, err := decodeWSToken(enc); err == nil && len(b) > 0 {
			return string(b)
		}
		if enc != "" {
			return enc
		}
	}
	return ""
}

func decodeWSToken(enc string) ([]byte, error) {
	if b, err := b64RawURL.DecodeString(enc); err == nil {
		return b, nil
	}
	if b, err := b64URL.DecodeString(enc); err == nil {
		return b, nil
	}
	return nil, errInvalidToken
}"}

